insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'bank', 0, $official_bank_source${"code":"SOC101","courseId":"f0a98038-5829-537e-bb07-a06605f6e2a4","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":523,"shell":{"contentKey":"introduction-sociology-1","titles":["Introduction to Sociology I"],"level":"100-level","semesters":["first-semester"]},"rows":{"audited":0,"keep":0,"retire":0,"add":523}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 1, $official_bank_source${"itemId":"697efd28-69ec-5e11-9a0b-ca37b3017d3d","questionId":"7801a55f-68e8-5c81-b3a7-105b12c4ba9e","sourceKey":"bank:SOC101:SOC-0025","payload":{"prompt":"C. Wright Mills' term for the ability to look beyond personal, everyday explanations of actions and see the wider social forces behind them is","options":["Sociological insight","Sociological understanding","Sociological imagination","Sociological illumination"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"The sociological imagination, a term from C. Wright Mills, is the ability to connect personal experiences and everyday actions to the wider social forces that shape them. Options A, B and D sound similar but are not the recognized name for this idea."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 2, $official_bank_source${"itemId":"03c467e0-d1d7-5ba7-886f-9f87a07d32fb","questionId":"ed6e5b09-2d0d-501b-a423-a5473c3c6b02","sourceKey":"bank:SOC101:SOC-0033","payload":{"prompt":"The application of the method of natural science to the study of man is known as","options":["Naturism","Empiricism","Objectivism","Positivism"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Positivism, associated with Auguste Comte, is the view that the methods of the natural sciences should be used to study society. Empiricism (B) and objectivism (C) are features of scientific study, relying on observation and avoiding bias, but they are not the name for this overall approach."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 3, $official_bank_source${"itemId":"d3864ac1-8b42-5b3d-9ed5-e007b5d6ad53","questionId":"c7ee64f3-8a74-5c7f-9821-794a07ef3e8c","sourceKey":"bank:SOC101:SOC-0035","payload":{"prompt":"The definition of Sociology as \"a science which attempts the interpretive understanding of social action in order thereby to arrive at a causal explanation of its course and effects\" was given by ________","options":["Alex Inkeles","Max Weber","Emile Durkheim","Herbert Spencer"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"This is Max Weber's well-known definition, which reflects his focus on understanding the meanings people attach to their actions. Durkheim (C) instead defined sociology as the study of social facts, and Spencer (D) took an evolutionary, organic view of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 4, $official_bank_source${"itemId":"ad9ea212-525e-5369-b143-f86fc94b5fcd","questionId":"ae43612f-276e-5cef-a4d8-782974cdb430","sourceKey":"bank:SOC101:SOC-0098","payload":{"prompt":"One of these is not a branch of sociology","options":["Sociology of law","Political Sociology","Sociology of Medicine","Anthropology"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Anthropology is a separate social science that studies human cultures, origins and ways of life, so it is related to sociology but not a branch of it. Sociology of law, political sociology and sociology of medicine in A, B and C are all specialised areas within sociology, applying sociological ideas to law, politics and health."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 5, $official_bank_source${"itemId":"1913b7b6-c6e4-5b42-ac66-ce1157b8f9b4","questionId":"28a8ed1f-f263-542a-936a-8ce6afad1474","sourceKey":"bank:SOC101:SOC-0100","payload":{"prompt":"Wright Mills is remembered mostly for one of the following","options":["Looking-glass self","positivism","sociological imagination","survival of the fittest"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"C. Wright Mills is best known for the 'sociological imagination', the ability to link personal troubles to wider public issues and history. The looking-glass self in A belongs to Charles Horton Cooley, positivism in B is linked with Auguste Comte, and 'survival of the fittest' in D was coined by Herbert Spencer."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 6, $official_bank_source${"itemId":"8f6a1d6a-292d-50bf-b1c1-735c20c7495a","questionId":"b949b156-cd48-5c2c-ab06-b35c290e9b47","sourceKey":"bank:SOC101:SOC-0195","payload":{"prompt":"Like the natural sciences the method of sociology is systematic","options":["True","False","Not all the time","Barely"],"correctOption":0,"section":"Definition and scope of sociology","explanation":"True - like the natural sciences, sociology studies society in a systematic, organised way, collecting and analysing evidence by planned methods. This is one of the main features of science that sociology adopts. Options C and D wrongly suggest that being systematic is only occasional."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 7, $official_bank_source${"itemId":"a4d25187-9c8a-5f48-b89b-3d5ab4e7c9e5","questionId":"89223ea0-a989-547f-8f0b-ca04a8753da6","sourceKey":"bank:SOC101:SOC-0206","payload":{"prompt":"The school of thought that insists on the application of the methods of natural science in sociology is known as","options":["Ethnomethodology","Phenomenology","Positivism","Functionalism"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"Positivism, associated with Auguste Comte, holds that sociology should use the methods of the natural sciences, such as observation, measurement and testing, to study society. Option A, ethnomethodology, and option B, phenomenology, focus on how people make sense of their everyday world, and option D, functionalism, is a theory of how society works rather than a position on method."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 8, $official_bank_source${"itemId":"bcfed7e1-44ab-5573-93a4-8de6d2e2a4fa","questionId":"a17e7ef8-d7fc-5c25-807c-d1c5b3053fd6","sourceKey":"bank:SOC101:SOC-0217","payload":{"prompt":"The distinguishing mark of a social problem is that","options":["It is a physically induced problem","It is environmentally based","It evolves as a result of human interaction","All of the above"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"A social problem arises from human interaction and the way society is organised, such as crime, unemployment or poverty. Options A and B describe physical or environmental problems, which are not what makes a problem social. Since A and B are wrong, D ('All of the above') is wrong too."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 9, $official_bank_source${"itemId":"05ab1983-1f3b-587b-9a57-73f8430612c5","questionId":"aa33c920-8aca-5376-8374-d90d06e2c13c","sourceKey":"bank:SOC101:SOC-0225","payload":{"prompt":"Accuracy of predictions is one of the several strengths of the Social science","options":["True","False","maybe","none of the above"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"False - social science studies human behaviour, which is complex and changes with circumstances, so its predictions are less exact than those of the physical sciences, which deal with inanimate objects. Limited accuracy of prediction is therefore a weakness of social science, not one of its strengths. Options C and D dodge the statement instead of judging it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 10, $official_bank_source${"itemId":"ca187432-b86f-5883-9ba1-c0b2d5ddc102","questionId":"ea26f957-7f79-5fbe-9185-beb208821a6d","sourceKey":"bank:SOC101:SOC-0227","payload":{"prompt":"Unlike the pure sciences, sociological knowledge is largely unreliable","options":["True","False","Maybe","None of the above"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"False - sociology adopts features of science such as being systematic, objective, empirical and testable, so its findings can be checked and relied upon. Its knowledge is less exact than that of the physical sciences, but that does not make it largely unreliable."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 11, $official_bank_source${"itemId":"e7b7a269-0132-5d8e-89b9-3102e5d80857","questionId":"07bc5ed7-0a04-51a2-9201-436629c4c9a7","sourceKey":"bank:SOC101:SOC-0248","payload":{"prompt":"Which of these is not true? Objectivity helps the sociologist to","options":["Identify his prejudices and stop them from affecting his findings","Show interest in the relevant facts even when they are unappealing","Find justification for his values","Be critical"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"Objectivity means studying facts without letting personal values or biases shape the findings, so it is not about finding justification for one's own values. Options A, B and D are true: objectivity helps a sociologist spot prejudices, accept unappealing facts and stay critical. That makes C the statement that is not true."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 12, $official_bank_source${"itemId":"34477813-091c-500c-947d-fa1f1aa6d700","questionId":"1bcf4e3e-203e-5064-9f77-6b4b85333e48","sourceKey":"bank:SOC101:SOC-0296","payload":{"prompt":"Sociology may study anything but certainly not the manifestations of disorder in society.","options":["True","False","Maybe","None of the above"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Sociology studies both order and disorder in society, including crime, deviance, conflict and social problems, so the statement is false (B). In fact, much sociological work, such as Durkheim's study of suicide, focuses on disorder. Option A is wrong because it would leave out a major part of what sociologists study."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 13, $official_bank_source${"itemId":"5dfea0e8-13ac-5c2e-99dd-e7717921aa61","questionId":"503327dc-5fcb-5487-a1ca-4c5f3515de0f","sourceKey":"bank:SOC101:S101N1-001","payload":{"prompt":"Sociology is best defined as the scientific study of","options":["The production, demand and supply of goods","Past events and how they happened","The mental processes of the individual","Human beings in social interaction"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Sociology is the scientific study of society, which means studying human beings as they interact with one another. The focus on individual mental processes belongs to psychology, not sociology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 14, $official_bank_source${"itemId":"79bffded-f517-512e-bbb4-46b55240b064","questionId":"beaa1e21-7430-501f-91df-27c6b6438cb6","sourceKey":"bank:SOC101:S101N1-002","payload":{"prompt":"Sociology becomes interested in a situation mainly when","options":["Two or more people interact","A single person thinks alone","A physical object changes its state","An individual's brain chemistry changes"],"correctOption":0,"section":"Definition and scope of sociology","explanation":"Sociology studies what happens when two or more people interact, because its subject is social interaction. A person thinking alone, with no interaction involved, is more a matter for psychology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 15, $official_bank_source${"itemId":"7aead7f7-8418-5c64-88c8-09bc22e9a77d","questionId":"6e44a6df-af96-52d1-b103-c1e7a66577da","sourceKey":"bank:SOC101:S101N1-003","payload":{"prompt":"Which of the following is NOT one of the characteristics of science that sociology adopts?","options":["Reliability","Testability","Empiricism","Subjectivity"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Sociology adopts five characteristics of science: systematic pursuit of knowledge, objectivity, empiricism, testability and reliability. Subjectivity is the opposite of objectivity, so it is not one of them, while empiricism, testability and reliability are all on the list."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 16, $official_bank_source${"itemId":"03f4f5ba-426f-5a15-9f3f-f8b39ef28156","questionId":"fd165fd8-62b5-5005-86f8-f1cfa98fae8d","sourceKey":"bank:SOC101:S101N1-004","payload":{"prompt":"How many characteristics of science does sociology adopt in its study of society?","options":["Six","Five","Four","Three"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Sociology adopts five characteristics of science: systematic pursuit of knowledge, objectivity, empiricism, testability and reliability. Answering four usually means one of them, often reliability, has been left out."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 17, $official_bank_source${"itemId":"d043198e-2a68-5714-92a9-891da69025e1","questionId":"a917a24f-8c64-5290-ac5c-6598b2a7d169","sourceKey":"bank:SOC101:S101N1-005","payload":{"prompt":"The characteristic of science which requires the sociologist to describe situations as they are, \"calling a spade a spade\", is","options":["Reliability","Empiricism","Testability","Objectivity"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Objectivity means describing a situation exactly as it is, without bending it to suit one's feelings, which is what \"calling a spade a spade\" expresses. Empiricism is close but different: it is about relying on what can be observed, not about being free of bias."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 18, $official_bank_source${"itemId":"53d8ba2d-1c36-5b64-9725-0c1ef57ca173","questionId":"76d6d0f7-d922-58a4-a27a-cf2b914d7635","sourceKey":"bank:SOC101:S101N1-006","payload":{"prompt":"The characteristic of science which means that sociology relies on what can be observed is","options":["Positivism","Empiricism","Objectivity","Reliability"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Empiricism means knowledge is based on what can be observed, rather than on guesswork or belief. Objectivity is a different characteristic, concerned with describing things as they are without bias."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 19, $official_bank_source${"itemId":"30b7d5f8-661b-52b2-afdc-5a839a9cabd8","questionId":"c8dc16c4-1dcc-574f-9045-4c64617f1de1","sourceKey":"bank:SOC101:S101N1-007","payload":{"prompt":"When sociologists insist that the information they present can be tested, they are applying the scientific characteristic of","options":["Testability","Objectivity","Empiricism","Systematic pursuit of knowledge"],"correctOption":0,"section":"Definition and scope of sociology","explanation":"Testability means that the information sociology produces can be checked or tested. Empiricism is related but refers to relying on what can be observed in the first place."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 20, $official_bank_source${"itemId":"d8e663b7-9ccb-5977-aba8-edd35433ca9f","questionId":"c277bddf-bcb5-5557-9e8a-5cb9b6095bda","sourceKey":"bank:SOC101:S101N1-008","payload":{"prompt":"A sociologist in Lagos refuses to accept any claim about traders in Balogun market unless it is based on what he or his team actually observed. He is applying","options":["Empiricism","Reliability","Social statics","Objectivity"],"correctOption":0,"section":"Definition and scope of sociology","explanation":"Basing claims only on what can be observed is empiricism, one of the characteristics of science sociology adopts. Objectivity is the tempting alternative, but it concerns describing things as they really are without bias, not the requirement of observation."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 21, $official_bank_source${"itemId":"1cd0490d-d8ce-52cc-bffa-214256802083","questionId":"98eb5e83-2411-5326-ab05-60e3c30d9934","sourceKey":"bank:SOC101:S101N1-009","payload":{"prompt":"A UNILAG researcher studying an ethnic association reports her findings exactly as she found them, even though they embarrass her own ethnic group. This shows","options":["Reliability","Empiricism","Objectivity","Testability"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"Objectivity means describing situations as they are, even when the truth is uncomfortable for the researcher. Empiricism is about relying on observation, but the key point here is that she did not let her personal attachment colour the report."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 22, $official_bank_source${"itemId":"3a24e1a5-2b1e-5537-8136-973407446dfb","questionId":"d9f24586-499a-5a55-a92e-a342d0d2a324","sourceKey":"bank:SOC101:S101N1-010","payload":{"prompt":"Empiricism, as a characteristic of science adopted by sociology, means that sociology","options":["Produces information that can be tested","Pursues knowledge in an orderly way","Relies on what can be observed","Describes situations without personal bias"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"Empiricism means sociology bases its knowledge on what can be observed. Describing situations without personal bias is objectivity, a separate characteristic on the same list."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 23, $official_bank_source${"itemId":"2a7337b4-12c6-52a2-bbe8-2255adff1acc","questionId":"97bf3739-241a-514f-aa32-719f0d0d7d4e","sourceKey":"bank:SOC101:S101N1-011","payload":{"prompt":"The range of subjects that sociology covers, its scope, is best described as","options":["All aspects of human relationships, such as marriage, family, work and criminality","Only the economic activities of people in urban areas","Only the mental health of individual persons","Only the political institutions of the state"],"correctOption":0,"section":"Definition and scope of sociology","explanation":"The scope of sociology covers all aspects of human relationships, including societies, marriage, family, work and criminality. The other options each pick out one narrow area that belongs mainly to economics, psychology or political science."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 24, $official_bank_source${"itemId":"a5bd8772-d9bb-53e4-8a00-81d761678835","questionId":"a27cfca6-7b04-5247-82fa-6b40f1e93131","sourceKey":"bank:SOC101:S101N1-012","payload":{"prompt":"Among the following, the one that is a recognised branch of sociology is","options":["Anthropology","Sociology of law","Psychology","History"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Sociology of law is one of the branches of sociology, alongside political sociology, sociology of economic life and sociology of medicine. Anthropology is tempting because it is closely related, but it is a separate discipline, not a branch of sociology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 25, $official_bank_source${"itemId":"a883bc7c-7707-5fbb-bf4f-7a6a0dab7aba","questionId":"d1d9087a-b493-5a84-afa8-8273ed15f335","sourceKey":"bank:SOC101:S101N1-013","payload":{"prompt":"A sociologist studies how ethnic loyalty shapes the way people vote in Lagos State elections. The branch of sociology involved is","options":["Sociology of medicine","Sociology of law","Political sociology","Sociology of economic life"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"Voting and elections are political matters, so studying their social side falls under political sociology. Sociology of law is tempting, but it deals with law and legal rules rather than voting behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 26, $official_bank_source${"itemId":"5809426e-8207-565d-9b3e-5eff36f4352c","questionId":"fa30669f-085d-55ba-a5c0-a6c48860bb38","sourceKey":"bank:SOC101:S101N1-014","payload":{"prompt":"A study of how trust and family ties shape trading networks among traders in Balogun market belongs to which branch of sociology?","options":["Sociology of medicine","Political sociology","Sociology of law","Sociology of economic life"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Trading is an economic activity, so the social side of trading networks is studied by the sociology of economic life. Political sociology would apply if the study were about power, government or elections instead."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 27, $official_bank_source${"itemId":"86f1a7cc-e2ca-5717-ada6-2bf12c66e652","questionId":"ebc6c6bc-dea0-5805-9fe2-d8019184bd40","sourceKey":"bank:SOC101:S101N1-015","payload":{"prompt":"A researcher studying how patients and doctors relate to each other in a Lagos hospital is working within","options":["Sociology of law","Sociology of economic life","Political sociology","Sociology of medicine"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Health, patients and doctors fall within the sociology of medicine, one of the named branches of sociology. Sociology of economic life is less fitting because the focus is on health care relationships, not trade or production."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 28, $official_bank_source${"itemId":"ac5925be-c4c7-5e55-b832-40b4eea25aa0","questionId":"9aff860e-4c2d-55a2-acc3-31f97721854e","sourceKey":"bank:SOC101:S101N1-016","payload":{"prompt":"How many uses of sociology are identified in the introduction to the discipline?","options":["Four","Two","Three","Five"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Two uses are identified: sociology improves understanding of human beings, their behaviour and society, and it helps in every career field. Five is a common mix-up with the number of characteristics of science that sociology adopts."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 29, $official_bank_source${"itemId":"822d187b-771b-5dd5-8a62-2b85ff43dcaa","questionId":"21bd3f4f-b82a-5b9c-8d5d-ec3ada148bb0","sourceKey":"bank:SOC101:S101N1-017","payload":{"prompt":"Sociology is useful in several ways. Which of these is NOT one of its uses?","options":["It improves understanding of human beings and their behaviour","It allows exact prediction of every human action","It helps in every career field","It improves understanding of society"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Sociology improves our understanding of human beings, their behaviour and society, and it helps in every career field. It cannot predict every human action exactly, because the social sciences cannot be as precise as the physical sciences."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 30, $official_bank_source${"itemId":"622ce69c-9100-5dad-9865-807c693c5c84","questionId":"395dd2da-cf40-52f7-8ed3-3e4069741c4c","sourceKey":"bank:SOC101:S101N1-018","payload":{"prompt":"A 100L student says sociology is only useful to people who want to become sociologists. This is wrong because sociology","options":["Is limited to the study of crime","Helps in every career field","Is a branch of the physical sciences","Deals only with the individual mind"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"One of the uses of sociology is that it helps in every career field, since every job involves dealing with people and society. The claim that it deals only with the individual mind describes psychology, not sociology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 31, $official_bank_source${"itemId":"a0cb21ad-932e-5407-9944-6085914c9afb","questionId":"a516d4a9-b3a7-5f78-9316-1f5a1fdf1715","sourceKey":"bank:SOC101:S101N1-019","payload":{"prompt":"The social sciences cannot be as precise or exact as the physical sciences mainly because","options":["Social scientists never observe what they study","Social sciences deal with human beings, while physical sciences deal with inanimate objects","Physical sciences study only the past","Social sciences do not use any method"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Human beings think, choose and change, while inanimate objects do not, so the social sciences cannot be as exact as the physical sciences. The claim that social sciences use no method is false, since sociology adopts a systematic method."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 32, $official_bank_source${"itemId":"82d820fc-e177-521b-8f8b-33f6f449f9e1","questionId":"9405e93b-25cc-54ca-9c36-0179d76c179d","sourceKey":"bank:SOC101:S101N1-020","payload":{"prompt":"\"The study of social life, social change, and the social causes and consequences of human behaviour\" is a definition of","options":["Psychology","Sociology","Economics","History"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"This is one of the standard definitions of sociology, which covers social life, social change and the social causes and effects of behaviour. Psychology focuses on the individual and their mental processes, not on social change."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 33, $official_bank_source${"itemId":"30c863fd-1ab1-5656-9242-969b57befbb1","questionId":"259f3910-8b45-56ae-859e-4c7166ef29a3","sourceKey":"bank:SOC101:S101N1-021","payload":{"prompt":"All of these have been offered as definitions of sociology EXCEPT","options":["The study of the individual's mental processes and health","The study of human social relationships and institutions","The study of social life, social change, and the social causes and consequences of human behaviour","The scientific study of human beings in social interaction"],"correctOption":0,"section":"Definition and scope of sociology","explanation":"Sociology is defined as the study of human social relationships and institutions, of human beings in social interaction, and of social life and social change. Studying an individual's mental processes and health is the focus of psychology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 34, $official_bank_source${"itemId":"ffc6c476-ad4f-5e0c-8528-e8218f3d0b37","questionId":"02c37fd9-41e5-5d13-a159-e0e4a79d945c","sourceKey":"bank:SOC101:S101N1-022","payload":{"prompt":"As a social science, sociology studies human societies, their interactions and the processes that","options":["Only destroy them","Only preserve them","Make them biologically inherited","Preserve or change them"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Sociology studies the processes that both preserve societies and change them, so it looks at stability and change together. Saying it studies only the processes that preserve societies leaves out social change, which is a central concern of the discipline."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 35, $official_bank_source${"itemId":"9d01be9e-4d9c-5f9c-a8ff-22c04cd9505e","questionId":"14ce0e3c-f248-574f-82d9-903644e7e4cb","sourceKey":"bank:SOC101:S101N1-023","payload":{"prompt":"A researcher in a UNILAG department insists that the methods used in physics and chemistry should be used to study social behaviour. His approach is known as","options":["Empiricism","Positivism","Anomie","Value-free sociology"],"correctOption":1,"section":"Definition and scope of sociology","explanation":"Positivism is the application of natural-science methods to the study of society, which is exactly what this researcher wants. Empiricism is only one characteristic of science, relying on observation, and not the whole approach of applying natural-science methods."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 36, $official_bank_source${"itemId":"9bed902a-c5cc-5b2b-beae-403cbc897d7f","questionId":"2e5c418a-c370-507c-a121-7a462bba2266","sourceKey":"bank:SOC101:S101N1-024","payload":{"prompt":"In Max Weber's definition, sociology is a science which attempts the interpretive understanding of","options":["Social statics","Social facts","Class struggle","Social action"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Weber defined sociology as a science which attempts the interpretive understanding of social action in order to arrive at a causal explanation of its course and effects. Social facts is a Durkheim concept, not part of Weber's definition."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 37, $official_bank_source${"itemId":"4ebb185c-6fd2-5766-a650-7d48550a5d6b","questionId":"1ed82ea5-f372-5e89-b92a-b68403b9208f","sourceKey":"bank:SOC101:S101N1-025","payload":{"prompt":"Pursuing knowledge in an orderly, step-by-step way is a characteristic of science that sociology adopts. It is called","options":["Empiricism","Testability","Objectivity","Systematic pursuit of knowledge"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"Systematic pursuit of knowledge means sociology seeks knowledge in an orderly, methodical way, just as the natural sciences do. Empiricism is a separate characteristic that is about relying on what can be observed, not about the orderliness of the method."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 38, $official_bank_source${"itemId":"cd352241-6d15-500e-b10c-f0fcc0c5fe75","questionId":"bacdf962-baf6-5fdd-9933-79b08bb5cafd","sourceKey":"bank:SOC101:S101N1-026","payload":{"prompt":"The physical sciences differ from the social sciences in that the physical sciences deal with","options":["Social relationships","Human beings","Human institutions","Inanimate objects"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"The physical sciences study inanimate objects, while the social sciences study human beings. Human beings, social relationships and institutions are all subjects of the social sciences."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 39, $official_bank_source${"itemId":"0ec6eec6-531b-5ab2-905e-fabf332e29f2","questionId":"a0184eff-3035-5750-bf83-eaee2ff24833","sourceKey":"bank:SOC101:S101N1-027","payload":{"prompt":"\"The social science that studies human societies, their interactions and the processes that preserve or change them\" describes","options":["Psychology","Political science","Anthropology","Sociology"],"correctOption":3,"section":"Definition and scope of sociology","explanation":"This is one of the definitions of sociology, which is concerned with societies, interaction, and both stability and change. Anthropology is the tempting choice, but it focuses on human culture, ancestors and traditional practices."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 40, $official_bank_source${"itemId":"8a6f5ee4-f58b-577c-9cd5-49db9c78a55d","questionId":"55feeb6d-f757-5da1-8160-4d6f0152e53b","sourceKey":"bank:SOC101:S101N1-028","payload":{"prompt":"One recognised use of sociology is that it","options":["Is limited to explaining physical objects","Removes the need for any other career","Improves understanding of human beings, their behaviour and society","Allows exact prediction of every human action"],"correctOption":2,"section":"Definition and scope of sociology","explanation":"Sociology helps us understand human beings, their behaviour and the society they live in, and it helps in every career field. Exact prediction of every action is not possible, because the social sciences cannot be as precise as the physical sciences."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 41, $official_bank_source${"itemId":"3ddc3d28-66c9-57d3-b329-b02aa4a7e740","questionId":"3ddfde00-add6-52e6-9598-d70b8ff84480","sourceKey":"bank:SOC101:SOC-0011","payload":{"prompt":"The quotation \"The history of all hitherto existing societies has been the history of class struggles\" can be found in the work of:","options":["Vilfredo Pareto","Max Weber","Karl Marx","Ferdinand Tonnies"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"This famous line opens The Communist Manifesto by Karl Marx and Friedrich Engels, and it sums up Marx's view that conflict between classes drives history. Pareto (A) is known for elite theory, Weber (B) for his work on status, power and rationalization, and Tonnies (D) for the contrast between community and association."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 42, $official_bank_source${"itemId":"b2011b54-ef38-523b-afd8-1a5886d90ad0","questionId":"ac858115-37c9-54e7-bb7b-acecbf3d95dd","sourceKey":"bank:SOC101:SOC-0099","payload":{"prompt":"The word 'Sociology' was coined by","options":["Karl Marx","Max Weber","Emile Durkheim","Auguste Comte"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Auguste Comte, the French thinker often called the father of sociology, coined the word 'sociology' to describe a scientific study of society. Karl Marx and Max Weber in A and B were major founding figures who wrote about class and social action, and Emile Durkheim in C helped establish sociology as an academic discipline, but none of them invented the term."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 43, $official_bank_source${"itemId":"99c6f539-4ead-5590-a5fd-88d74ee238ff","questionId":"626744f1-25a9-582a-836a-032877266ca1","sourceKey":"bank:SOC101:SOC-0287","payload":{"prompt":"The theory of social class was originally formulated by","options":["Ralf Dahrendorf","Talcott Parsons","Karl Marx","Max Weber"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Karl Marx developed the theory of social class, arguing that society is divided by people's relation to the means of production, into owners (bourgeoisie) and workers (proletariat). Option D, Weber, later added status and party to class but built on Marx's earlier work. Option A, Dahrendorf, came much later, and Option B, Parsons, was a functionalist."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 44, $official_bank_source${"itemId":"d446f0fd-3fe5-57c3-97ef-ca022c028afd","questionId":"b0625b75-2ad5-5dd4-93a4-446d7879e643","sourceKey":"bank:SOC101:SOC-0302","payload":{"prompt":"One of these is not true of the man Auguste Comte","options":["He was a Frenchman","He led the French Revolution","He christened Sociology","He was a positivist sociologist"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"Comte did not lead the French Revolution; he was born after it began, and he was a thinker reacting to the disorder it left behind, so B is the false statement. Options A, C and D are all true: Comte was French, he gave sociology its name, and he championed positivism, the scientific study of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 45, $official_bank_source${"itemId":"8cdc3eb9-f620-5edc-bc99-f8a2f7dad059","questionId":"705025e3-31c3-5de3-8548-6540c81e9588","sourceKey":"bank:SOC101:S101N1-029","payload":{"prompt":"Sociology as a discipline is said to have started from","options":["North Africa","England","France","Germany"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Sociology is said to have started from France, where Auguste Comte coined the term and the French Revolution shook up society. Germany is tempting because Marx and Weber were German, but they came after the discipline was founded."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 46, $official_bank_source${"itemId":"69642c05-4f86-55aa-9cda-457a00610c2c","questionId":"70a9885b-9e55-5222-8bbc-038eaf6fd735","sourceKey":"bank:SOC101:S101N1-030","payload":{"prompt":"The two revolutions that gave rise to sociology were the","options":["Industrial Revolution and the American Revolution","French Revolution and the Russian Revolution","French Revolution and the Industrial Revolution","Agricultural Revolution and the Russian Revolution"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"The French (political) Revolution of 1789 and the Industrial Revolution created social problems that led to the birth of sociology. The Russian and American Revolutions are real events, but they are not the two revolutions linked to the emergence of the discipline."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 47, $official_bank_source${"itemId":"05b07062-56c4-5677-88a4-4bd0056e08b4","questionId":"897f342b-93d1-518b-86ea-fd027a25f6d1","sourceKey":"bank:SOC101:S101N1-031","payload":{"prompt":"The French Revolution, which helped give rise to sociology, took place in","options":["1760","1838","1840","1789"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"The French Revolution took place in 1789 and restructured French society. The date 1838 is when Comte coined the word sociology, and 1760 and 1840 are the rough start and end of the Industrial Revolution."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 48, $official_bank_source${"itemId":"b83a42c3-d4ec-5a4d-b6fc-d3b3597b0811","questionId":"f08efafa-c035-5e76-8ab3-27a9f5c0b350","sourceKey":"bank:SOC101:S101N1-032","payload":{"prompt":"The Industrial Revolution in Europe is dated to about","options":["1838-1857","1760-1840","1789-1799","1858-1917"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"The Industrial Revolution ran from about 1760 to 1840. The years 1858-1917 are Durkheim's lifetime, and 1789 is the year of the French Revolution, so those options mix up different events."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 49, $official_bank_source${"itemId":"038fa851-d7e0-5bc1-9cbe-b121049fd129","questionId":"cff60901-0839-59d4-aae1-9fc64af58566","sourceKey":"bank:SOC101:S101N1-033","payload":{"prompt":"Which of the following was an effect of the French Revolution on social classes?","options":["Aristocrats lost wealth and position, and many peasants moved up the social ladder","People moved from cities back to rural areas","Society shifted from agricultural to industrial production","Peasants lost their land and aristocrats gained more power"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"The French Revolution disrupted social classes: aristocrats lost their wealth and position while many peasants moved up. The shift from agricultural to industrial production describes the Industrial Revolution, not the French one."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 50, $official_bank_source${"itemId":"521601c4-a611-58bd-bcec-5c31af2e84dd","questionId":"c07da46d-d1df-52bd-8397-69ac2d6b6cb7","sourceKey":"bank:SOC101:S101N1-034","payload":{"prompt":"Which of the following was NOT a problem brought by the Industrial Revolution?","options":["Overcrowding","A fall in rural-urban migration","More poverty and crime","Long working hours in poor conditions for low pay"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"The Industrial Revolution caused increased rural-urban migration, not a fall in it, as people moved to cities for factory work. Overcrowding, more poverty and crime, and long hours for low pay were all problems it brought."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 51, $official_bank_source${"itemId":"33630799-b6ba-5ef1-bf6b-c9112bda6988","questionId":"172e9b4e-0880-5328-a80d-6a2fb7a05529","sourceKey":"bank:SOC101:S101N1-035","payload":{"prompt":"The Industrial Revolution is best described as a shift from","options":["Industrial to agricultural production","Monarchy to democracy","Religious to scientific thinking","Agricultural to industrial production"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"The Industrial Revolution moved economies from agricultural to industrial production and drew people from rural to urban areas. A shift from religious to scientific thinking sounds like Comte's law of three stages, which is a different idea."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 52, $official_bank_source${"itemId":"94f1f61f-a037-533c-9d00-526960c192e5","questionId":"5512d2cb-cbe9-5d44-b240-52e3904c4f18","sourceKey":"bank:SOC101:S101N1-036","payload":{"prompt":"Auguste Comte proposed a new discipline, sociology, because","options":["He wanted to lead the French Revolution","The natural sciences had been abolished in France","He wished to replace religion with economics","The existing social sciences could not explain the problems created by the revolutions"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Comte saw that the existing social sciences could not explain the problems arising from the French and Industrial Revolutions, so he proposed a new discipline. He did not lead the French Revolution, which is a common false claim about him."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 53, $official_bank_source${"itemId":"abd7bc2e-d604-5e21-9d0b-db4e057185ec","questionId":"f6865292-8638-54be-9b06-30749be23083","sourceKey":"bank:SOC101:S101N1-037","payload":{"prompt":"The word \"sociology\" comes from the Latin socius, which means","options":["Law","Nation","Study of","Companion, or being with others"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Socius is Latin for companion, or being with others, which gives the \"socio\" part of sociology. \"Study of\" is the meaning of the Greek logia, the other half of the word."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 54, $official_bank_source${"itemId":"9780b2ed-0e34-5e84-9c13-19acd4134c7f","questionId":"0c28eb44-87eb-5d4c-9553-193c42b53c39","sourceKey":"bank:SOC101:S101N1-038","payload":{"prompt":"The \"-logy\" part of the word sociology comes from the Greek logia, which means","options":["Being with others","Society","Companion","Study of"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Logia is Greek for \"study of\", so sociology is the study of companionship or society. Companion and being with others are the meanings of the Latin socius, the first half of the word."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 55, $official_bank_source${"itemId":"4843dc29-6123-5e0b-93f1-3139c8b8139a","questionId":"a422da47-2d91-5f13-8513-cd25d855a917","sourceKey":"bank:SOC101:S101N1-039","payload":{"prompt":"In which year did Auguste Comte coin the word \"sociology\"?","options":["1857","1780","1838","1789"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Comte coined the word sociology in 1838. The year 1780 is when Sieyes used the word in an unpublished manuscript, and 1857 is the year of Comte's death."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 56, $official_bank_source${"itemId":"7b7a9aed-a43f-5e7b-8ac2-aa6f38307f87","questionId":"4c42c431-6256-556c-a0e2-0326ad9609d8","sourceKey":"bank:SOC101:S101N1-040","payload":{"prompt":"Before Comte, the word \"sociology\" had been used in an unpublished manuscript by the French essayist","options":["Ibn Khaldun","Emmanuel Joseph Sieyes","Max Weber","Emile Durkheim"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"The French essayist Emmanuel Joseph Sieyes used the word in an unpublished manuscript of 1780, before Comte made it known. Durkheim was also French, but he was born in 1858, long after the word was in use."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 57, $official_bank_source${"itemId":"4e7d05f5-1d14-512e-add9-e0194ffc7c1d","questionId":"b020a3bc-7326-5568-b59f-8b257577c6e1","sourceKey":"bank:SOC101:S101N1-041","payload":{"prompt":"Who is regarded as the \"Father of Sociology\"?","options":["Auguste Comte","Ibn Khaldun","Karl Marx","Max Weber"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"Auguste Comte is called the Father of Sociology because he named the discipline and set out its first plan. Ibn Khaldun is sometimes put forward, but he is not the one regarded as the father of sociology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 58, $official_bank_source${"itemId":"92b69b30-c5a0-5516-8169-4b71a402c36d","questionId":"2dbe86f7-23a0-5eb3-ac86-cd9ce3156f50","sourceKey":"bank:SOC101:S101N1-042","payload":{"prompt":"Auguste Comte is best described as a","options":["German philosopher, economist and journalist","German sociologist who argued for value-free research","French philosopher, mathematician and sociologist","French essayist who never published on society"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Comte was a French philosopher, mathematician and sociologist. The German philosopher, economist and journalist was Karl Marx, and value-free sociology is associated with Max Weber."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 59, $official_bank_source${"itemId":"6f9de9c2-57bf-54ba-a895-8124e957ecaf","questionId":"4dfa0888-57d1-5de4-b1ae-1465375c140b","sourceKey":"bank:SOC101:S101N1-043","payload":{"prompt":"Auguste Comte hoped that sociology could","options":["Remove the need for any social change","Replace the scientific method with religion","Lead workers to overthrow the bourgeoisie","Unite all sciences in order to improve society"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Comte hoped sociology would unite all the sciences and be used to improve society. Leading workers against the bourgeoisie is Marx's idea of class struggle, not Comte's aim."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 60, $official_bank_source${"itemId":"aa7a2118-9408-5f2b-9241-502a9a24797c","questionId":"29ea9ee8-867f-5cdf-bb50-2aedad3c6343","sourceKey":"bank:SOC101:S101N1-044","payload":{"prompt":"In Comte's division of sociology, social statics refers to","options":["The conflict between owners and workers","The factors that produce change in society","The stage in which religion dominates","The factors that give society stability and continuity"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Social statics are the factors that give society stability and continuity. The factors that produce change are the other half of Comte's division, called social dynamics."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 61, $official_bank_source${"itemId":"b2cdc813-5113-50fc-a4e9-56c35fe3a4d8","questionId":"b1368d49-782d-5bf1-8d23-e3a98dd62b13","sourceKey":"bank:SOC101:S101N1-045","payload":{"prompt":"The part of Comte's sociology that deals with the factors producing change in society is called","options":["Collective conscience","Social dynamics","Social facts","Social statics"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"Social dynamics is Comte's name for the factors that produce change in society. Social statics is the opposite part, dealing with stability and continuity."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 62, $official_bank_source${"itemId":"4c16013b-4f9d-572c-92d9-53fafb208d0e","questionId":"4e4f7ae0-9c38-589d-ad60-9c5586857e33","sourceKey":"bank:SOC101:S101N1-046","payload":{"prompt":"Which of the following gives the correct order of Comte's law of three stages?","options":["Scientific, metaphysical, theological","Metaphysical, theological, scientific","Theological, scientific, metaphysical","Theological, metaphysical, scientific"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Comte held that society moves from the theological stage, through the metaphysical stage, to the scientific (positive) stage. The scientific stage is the most advanced, so it must come last, not first or in the middle."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 63, $official_bank_source${"itemId":"ed08d1ed-49fa-5d45-88bf-098da070c31d","questionId":"cd750e0a-1c14-573b-be23-aa0878a3c112","sourceKey":"bank:SOC101:S101N1-047","payload":{"prompt":"In Comte's law of three stages, the most advanced stage is the","options":["Scientific or positive stage","Feudal stage","Metaphysical stage","Theological stage"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"The scientific or positive stage is the most advanced, governed by reliable knowledge rather than religion or sentiment. Feudalism is one of Marx's stages of history, not one of Comte's three stages."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 64, $official_bank_source${"itemId":"90141a8f-1da6-5209-8a23-54630976c88c","questionId":"12ea822b-b92d-59e1-b891-1cd9d82b921a","sourceKey":"bank:SOC101:S101N1-048","payload":{"prompt":"The stage in Comte's law of three stages in which religion dominates and development is low is the","options":["Metaphysical stage","Theological stage","Scientific stage","Positive stage"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"In the theological stage religion dominates and the level of development is low. The metaphysical stage comes next, when society is understood as natural rather than supernatural."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 65, $official_bank_source${"itemId":"94d88826-99d6-5d32-aace-badb7f14223a","questionId":"e3dcab15-a682-5248-925f-a5fac07f0463","sourceKey":"bank:SOC101:S101N1-049","payload":{"prompt":"In Durkheim's work, solidarity refers to","options":["The bonds holding society together","The conflict between social classes","A state of normlessness","The factors producing change in society"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"Solidarity is Durkheim's term for the bonds that hold society together. A state of normlessness is anomie, which describes the breakdown of those bonds."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 66, $official_bank_source${"itemId":"6a05fb91-cf3f-52f1-a22c-b93db3bb1469","questionId":"045362af-511a-5e4c-bbc0-700eb3e575a4","sourceKey":"bank:SOC101:S101N1-050","payload":{"prompt":"Durkheim's term for the shared values, beliefs and norms of a society is","options":["Division of labour","Anomie","Social dynamics","Collective consciousness"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Collective consciousness (or conscience) is the set of shared values, beliefs and norms in a society. Anomie is the opposite situation, where norms break down and rules are disregarded."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 67, $official_bank_source${"itemId":"ca217d91-307a-5a48-8065-39b83f2d1b6b","questionId":"ee7f62b1-36f6-53d3-8836-70a4d58266a3","sourceKey":"bank:SOC101:S101N1-051","payload":{"prompt":"A small rural village where everyone knows everyone else, relationships are face-to-face and people are very alike would be described by Durkheim as having","options":["Legal-rational authority","Anomie","Mechanical solidarity","Organic solidarity"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Mechanical solidarity describes small, rural, face-to-face and homogeneous societies. Organic solidarity is the opposite type, found in large, urban, heterogeneous and anonymous societies."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 68, $official_bank_source${"itemId":"1e46607a-7ade-58fa-a8a9-ade24dc9bde8","questionId":"e5a0d57e-57ff-5370-9e94-8e2d0aa48fc8","sourceKey":"bank:SOC101:S101N1-052","payload":{"prompt":"Lagos, a large city of people from many backgrounds where most people are strangers to one another, fits Durkheim's type of society based on","options":["Traditional authority","Mechanical solidarity","Organic solidarity","Social statics"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Organic solidarity describes large, urban, heterogeneous and highly anonymous societies like Lagos. Mechanical solidarity fits small, rural, homogeneous communities instead."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 69, $official_bank_source${"itemId":"34a109aa-b7cf-5965-b165-7553da43d24f","questionId":"3c5f8c88-2238-59b1-9f20-9d91a8757175","sourceKey":"bank:SOC101:S101N1-053","payload":{"prompt":"Durkheim's concept of a state of normlessness, a breakdown of the social system and disregard for rules, is","options":["Collective consciousness","Solidarity","Social facts","Anomie"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Anomie is normlessness: rules lose their hold and the social system breaks down. Collective consciousness is the opposite, the shared values and norms that keep people together."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 70, $official_bank_source${"itemId":"a87ff2cf-77e5-5d44-b785-395102ec460c","questionId":"a5f22966-d858-557c-b52f-171e07bfa91b","sourceKey":"bank:SOC101:S101N1-054","payload":{"prompt":"According to Durkheim, the division of labour","options":["Unites society through mutual reliance","Divides society into two hostile classes","Creates normlessness in every society","Is a stage in which religion dominates"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"For Durkheim, the division of labour unites society because people depend on one another for different tasks. Dividing society into two hostile classes is Marx's view, not Durkheim's."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 71, $official_bank_source${"itemId":"cb2fda5b-db8b-5283-81db-f81de3edff7b","questionId":"45b33fa7-d1e3-5e4b-9f52-48da944d1630","sourceKey":"bank:SOC101:S101N1-055","payload":{"prompt":"External social forces such as laws, morals, values and customs that shape individuals were called by Durkheim","options":["Sociological imagination","Social facts","Social dynamics","Social action"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"Durkheim called these external forces social facts, because they exist outside the individual and shape behaviour. Social action is Weber's concern, and sociological imagination is associated with C. Wright Mills."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 72, $official_bank_source${"itemId":"8648364a-d33c-55c3-92b2-15585587335c","questionId":"6c9e11a0-c634-5706-84f9-0cd26814171b","sourceKey":"bank:SOC101:S101N1-056","payload":{"prompt":"In Marx's analysis of society, the bourgeoisie are","options":["The holders of charismatic authority","The owners of the means of production","The peasants freed by the French Revolution","The working class"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"The bourgeoisie are the class that owns the means of production. The working class is the proletariat, the other side of the conflict Marx described."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 73, $official_bank_source${"itemId":"b3797d42-674f-55f7-be0d-8e980d91edf0","questionId":"10f49874-70b4-593d-b907-d209850cdf86","sourceKey":"bank:SOC101:S101N1-057","payload":{"prompt":"Factory workers in Ikeja who own nothing but their labour belong to the class Marx called the","options":["Bourgeoisie","Aristocracy","Collective conscience","Proletariat"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"The proletariat is the working class, people who sell their labour because they do not own the means of production. The bourgeoisie are the owners of the factories, so they are the opposite class."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 74, $official_bank_source${"itemId":"5454cdd8-0bd9-5df0-88c5-87ee1be2303b","questionId":"713ca0c3-2183-5c8a-8edf-9029d853f368","sourceKey":"bank:SOC101:S101N1-058","payload":{"prompt":"In Marx's stages of history, the first stage is","options":["Capitalism","Feudalism","Slavery","Primitive communism"],"correctOption":3,"section":"Emergence of sociology and founding fathers","explanation":"Marx's history begins with primitive communism, before slavery, feudalism and capitalism. Slavery is the stage that comes immediately after it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 75, $official_bank_source${"itemId":"0d9530af-3704-5096-b294-54bf8c5a70cf","questionId":"6d492028-60c3-5030-8e3d-b38ca6308c8a","sourceKey":"bank:SOC101:S101N1-059","payload":{"prompt":"In Marx's stages of history, the highest stage, marked by distribution according to need and no exploitation, is","options":["Capitalism","Communism","Primitive communism","Socialism"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"Communism is the highest stage for Marx, where goods are distributed according to need and there is no exploitation. Primitive communism is the very first stage, not the last."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 76, $official_bank_source${"itemId":"64f4e61d-350f-5bae-917c-f1847bb9c935","questionId":"30394c19-cd4e-57fd-bdc0-68609335dd6a","sourceKey":"bank:SOC101:S101N1-060","payload":{"prompt":"Max Weber's argument that a researcher's personal values should not interfere with research is known as","options":["Value-free sociology","Sociological imagination","Positivism","Social statics"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"Weber argued for value-free sociology, keeping personal values out of research. Positivism is a different idea, the use of natural-science methods to study society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 77, $official_bank_source${"itemId":"65c91874-ac55-5ef7-a6b6-1090ef074c55","questionId":"c32ee541-ac31-5a72-bfb0-640c70667750","sourceKey":"bank:SOC101:S101N1-061","payload":{"prompt":"An Oba in a Yoruba town inherits his throne by custom from his late father. In Weber's terms, his authority is","options":["Legal-rational authority","Charismatic authority","Traditional authority","Social dynamics"],"correctOption":2,"section":"Emergence of sociology and founding fathers","explanation":"Traditional authority rests on custom and can be inherited, as with a throne passed down a royal line. Charismatic authority cannot be inherited, because it depends on the personal qualities of one leader."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 78, $official_bank_source${"itemId":"7d5763d3-3c78-5bab-874b-9149c744b3b8","questionId":"5841c237-4532-57ed-9c20-464546792a0b","sourceKey":"bank:SOC101:S101N1-062","payload":{"prompt":"In Weber's classification, the type of authority based on a leader's personal qualities, which cannot be inherited or transferred, is","options":["Legal-rational authority","Charismatic authority","Organic solidarity","Traditional authority"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"Charismatic authority comes from the personal qualities of a leader, so it cannot be passed to someone else. Traditional authority is the tempting option, but it rests on custom and can be inherited."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 79, $official_bank_source${"itemId":"110b3bd9-2c2e-50fb-9488-8e1b912c1cce","questionId":"924dc143-3628-56b8-a679-b3bc7446e479","sourceKey":"bank:SOC101:S101N1-063","payload":{"prompt":"A bank in Lagos appoints its managing director purely on qualifications, regardless of age or gender. In Weber's terms, this is","options":["Charismatic authority","Legal-rational authority","Traditional authority","Mechanical solidarity"],"correctOption":1,"section":"Emergence of sociology and founding fathers","explanation":"Legal-rational authority is based on reason, with positions going to the most qualified person regardless of age or gender. Traditional authority would instead rest on custom, age and often gender."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 80, $official_bank_source${"itemId":"9a1b27b9-c4ba-59a6-9316-a12c6cc16467","questionId":"d76568a2-39a6-57cb-97e5-1b11489339f3","sourceKey":"bank:SOC101:S101N1-064","payload":{"prompt":"The Weberian theory of social change emphasises","options":["The increasing rationality of human beings","The movement from mechanical to organic solidarity","The return of society to the theological stage","The struggle between bourgeoisie and proletariat"],"correctOption":0,"section":"Emergence of sociology and founding fathers","explanation":"Weber's theory of change stresses the increasing rationality of human beings. Class struggle between bourgeoisie and proletariat is Marx's explanation of change, not Weber's."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 81, $official_bank_source${"itemId":"35e8032c-6c20-510f-9624-401ecd46a2e1","questionId":"f19e2740-1d09-5b9c-b730-9dc3cb9e7efd","sourceKey":"bank:SOC101:SOC-0027","payload":{"prompt":"Social Science is different from Natural Sciences in all but one of these areas","options":["Their procedure","Their subject matter","Their environment","The ease of running controlled laboratory experiments"],"correctOption":0,"section":"Sociology and other social sciences","explanation":"Both the social and natural sciences follow the same basic scientific procedure: systematic observation, testing and objective analysis. Where they differ is in subject matter (B), since social science studies people, in the settings they work in (C), and in how easily they can run controlled laboratory experiments (D), which is much harder with human groups."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 82, $official_bank_source${"itemId":"9b9d2816-a177-5c3d-a1f6-038f11cd593e","questionId":"d5eb61c9-53db-5430-94e6-29fb5b553d35","sourceKey":"bank:SOC101:SOC-0246","payload":{"prompt":"The major difference between natural and social science is","options":["Their procedure","Their environment","Their scientific theory","Their object of study"],"correctOption":3,"section":"Sociology and other social sciences","explanation":"The key difference between the natural and social sciences is what they study: natural sciences study the physical world, while social sciences study human beings and their society. Option A is wrong because both follow scientific procedures, which is why sociology is called a science."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 83, $official_bank_source${"itemId":"ada46039-1d04-5dcc-bb85-5fa6dc8b0f37","questionId":"610b671a-4ffc-548d-9d4c-0be28cbb7c6e","sourceKey":"bank:SOC101:S101N1-065","payload":{"prompt":"Psychology differs from sociology in that psychology focuses on","options":["Past and present societies and how they changed","How group interaction affects the individual","The individual and their mental processes or health","Political institutions, processes and structures"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Psychology concentrates on the individual and their mental processes or health. Looking at how group interaction affects the individual is the sociological angle, not the psychological one."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 84, $official_bank_source${"itemId":"9cb3bdbc-997e-5bc1-bc76-375edc44ca97","questionId":"8965822b-49f7-5a29-92ad-a33cf2c0ef1d","sourceKey":"bank:SOC101:S101N1-066","payload":{"prompt":"Compared with psychology, sociology is more concerned with","options":["How group interaction affects the individual","The production, demand and supply of goods","The study of early human ancestors only","The individual's mental processes alone"],"correctOption":0,"section":"Sociology and other social sciences","explanation":"Sociology looks at how interaction within groups shapes the individual. Studying the individual's mental processes alone is what psychology does."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 85, $official_bank_source${"itemId":"eab79d48-c81b-5cc1-af9b-8c41aa7e6207","questionId":"7863368b-570a-5124-8d6a-bbcb80bda85d","sourceKey":"bank:SOC101:S101N1-067","payload":{"prompt":"Anthropology is the social science that studies","options":["Production, demand and supply","Human culture, environment, ancestors, early life and traditional practices","Political institutions, processes and structures","The individual's mental processes"],"correctOption":1,"section":"Sociology and other social sciences","explanation":"Anthropology studies human culture, environment, ancestors, early life and traditional practices. Political institutions and processes are the field of political science."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 86, $official_bank_source${"itemId":"d69f7199-c110-5c2f-875c-67813ac356a7","questionId":"05a0bd5e-b7c4-50c5-be6a-f2a69046acae","sourceKey":"bank:SOC101:S101N1-068","payload":{"prompt":"Unlike anthropology, sociology covers","options":["Only the mental health of individuals","Only demand and supply in markets","Only traditional practices of early human societies","Both past and present societies and the change from traditional to modern"],"correctOption":3,"section":"Sociology and other social sciences","explanation":"Sociology studies both past and present societies, including how societies change from traditional to modern. Focusing on traditional practices and early societies is the emphasis of anthropology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 87, $official_bank_source${"itemId":"1b6bdf6d-47d8-5f61-a771-e8ca5f690335","questionId":"3199ae5c-2fe4-5e6c-a252-78c890897480","sourceKey":"bank:SOC101:S101N1-069","payload":{"prompt":"Political science is the study of","options":["Political institutions, processes and structures","Past events only","Human culture, ancestors and traditional practices","The individual and their mental processes"],"correctOption":0,"section":"Sociology and other social sciences","explanation":"Political science studies political institutions, processes and structures. Human culture, ancestors and traditional practices belong to anthropology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 88, $official_bank_source${"itemId":"b4bd056c-f8a1-54d9-b719-0f7f4d7dd1eb","questionId":"bf1f762f-29c8-5957-b438-58f60d75ba94","sourceKey":"bank:SOC101:S101N1-070","payload":{"prompt":"When sociology examines political institutions, processes and structures, its main interest is","options":["How to win elections","How individual voters think in isolation","How they affect society","How demand and supply are balanced"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Political science studies political institutions themselves, while sociology asks how these institutions affect society. How individual voters think in isolation would lean towards psychology rather than sociology."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 89, $official_bank_source${"itemId":"f69b7afc-892d-5431-bed5-1f0ca06c55d2","questionId":"b8a27bc4-0fc5-5f4d-b8e9-e8e1a3ca1696","sourceKey":"bank:SOC101:S101N1-071","payload":{"prompt":"Economics, as a social science, covers","options":["Past events and how they happened","Production, demand and supply","Human ancestors and early life","All institutions and relationships that affect behaviour"],"correctOption":1,"section":"Sociology and other social sciences","explanation":"Economics deals with production, demand and supply. Covering all institutions and relationships that affect behaviour is how sociology differs from economics, not what economics itself does."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 90, $official_bank_source${"itemId":"359e2d5a-0173-5041-8c50-ab8decf832f9","questionId":"f088721d-b4e9-50e2-b302-1f2851015f36","sourceKey":"bank:SOC101:S101N1-072","payload":{"prompt":"Compared with economics, sociology covers","options":["All institutions and relationships that affect behaviour, and how behaviour affects the economy","Only political processes and structures","Only the mental processes of individuals","Only production, demand and supply"],"correctOption":0,"section":"Sociology and other social sciences","explanation":"Sociology is broader than economics: it covers all institutions and relationships that affect behaviour, including how behaviour affects the economy. Production, demand and supply alone is the narrower focus of economics."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 91, $official_bank_source${"itemId":"d54834ce-bc1a-56c1-9fea-debc6113eec9","questionId":"56132385-4003-5080-83aa-f97b079dcc37","sourceKey":"bank:SOC101:S101N1-073","payload":{"prompt":"History, as a discipline, studies","options":["The individual's mental processes","Past and present societies and how the past shapes the present","Past events","Political institutions and structures"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"History studies past events. Studying both past and present, and how the past shapes the present, is what sociology does, which makes it the tempting wrong choice."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 92, $official_bank_source${"itemId":"4e67e142-e728-5a5f-8a40-710743fe392a","questionId":"310eead2-6d8a-5e8c-be2f-25ceb295c466","sourceKey":"bank:SOC101:S101N1-074","payload":{"prompt":"How does sociology differ from history?","options":["Sociology studies only past events","Sociology studies only the individual mind","Sociology studies past and present, how society changed, and how the past shapes the present","Sociology ignores the past completely"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"History focuses on past events, while sociology studies both past and present, how society has changed, and how the past shapes the present. Saying sociology studies only past events describes history instead."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 93, $official_bank_source${"itemId":"253f68ed-a6af-59d7-82d8-28aa4d508771","questionId":"d0b64bd3-559e-54c1-9f5f-1e0ef13aa24e","sourceKey":"bank:SOC101:S101N1-075","payload":{"prompt":"A researcher studies the memory and stress levels of one UNILAG student before examinations. This study belongs mainly to","options":["Anthropology","Political science","Psychology","Sociology"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Studying one person's memory and stress is about the individual and their mental processes, which is psychology. Sociology would be the answer if the study looked at how group interaction affected the student."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 94, $official_bank_source${"itemId":"4e3f1486-d2bf-5035-8bcf-58d925381df5","questionId":"00ea7c94-307c-5f5d-ad0b-31a88b89f4af","sourceKey":"bank:SOC101:S101N1-076","payload":{"prompt":"A scholar studies the burial rites, ancestry and early way of life of an ancient community in Nigeria. This work belongs mainly to","options":["Political science","Economics","Anthropology","Psychology"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Ancestors, early life and traditional practices such as burial rites are what anthropology studies. Economics would only apply if the study were about production, demand and supply."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 95, $official_bank_source${"itemId":"438f6743-e8f7-5441-bb2a-cf390a96eaa1","questionId":"6a17b13f-6486-55ee-86ae-a19c7acd516d","sourceKey":"bank:SOC101:S101N1-077","payload":{"prompt":"A study of how the structure and processes of the Nigerian National Assembly work is mainly a study in","options":["Psychology","Anthropology","Economics","Political science"],"correctOption":3,"section":"Sociology and other social sciences","explanation":"The National Assembly is a political institution, and its structure and processes are the subject matter of political science. Anthropology deals with culture, ancestors and traditional practices instead."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 96, $official_bank_source${"itemId":"4fd2ff60-f714-5b78-ae4c-d536652d2364","questionId":"e48c989a-163d-56e6-bcf8-ed88f08abc26","sourceKey":"bank:SOC101:S101N1-078","payload":{"prompt":"A researcher studies how the demand and supply of tomatoes affect prices at Mile 12 market in Lagos. This is mainly a study in","options":["Anthropology","History","Economics","Sociology"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Demand, supply and prices are the core concerns of economics. Sociology would be involved if the study asked how relationships among traders affect their behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 97, $official_bank_source${"itemId":"11672231-ca4e-5531-b900-8c4e42fddefc","questionId":"1676590c-5a85-5ada-8c8c-9a3b5ff62f14","sourceKey":"bank:SOC101:S101N1-079","payload":{"prompt":"A scholar records the events that led to the amalgamation of Nigeria in 1914 without relating them to present-day society. This is mainly a study in","options":["Psychology","Sociology","History","Political science"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Recording past events for their own sake is the work of history. Sociology would also look at the present and at how the past shapes society today."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 98, $official_bank_source${"itemId":"0244624f-5d82-5a53-aae5-f081b0bdda63","questionId":"3a0175ac-952c-59bc-b5dd-a01e46ed5e0e","sourceKey":"bank:SOC101:S101N1-086","payload":{"prompt":"Which discipline studies the change of societies from traditional to modern, covering both past and present societies?","options":["Psychology","Anthropology","Sociology","History"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"Sociology covers past and present societies and the change from traditional to modern. Anthropology is the tempting choice, but it focuses on culture, ancestors, early life and traditional practices."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 99, $official_bank_source${"itemId":"38450485-3970-53a5-ba8a-ad37caa8f9d5","questionId":"95a97b7d-17bb-5698-95dd-9c67e300529f","sourceKey":"bank:SOC101:S101N1-087","payload":{"prompt":"Which discipline studies how behaviour affects the economy, in addition to all institutions and relationships that affect behaviour?","options":["History","Sociology","Political science","Economics"],"correctOption":1,"section":"Sociology and other social sciences","explanation":"Sociology looks at all institutions and relationships that affect behaviour, and how behaviour in turn affects the economy. Economics itself is narrower, covering production, demand and supply."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 100, $official_bank_source${"itemId":"c789d5fa-4326-5631-a1c0-f60d60827000","questionId":"25a33510-492d-571e-856a-7f6e24b0704e","sourceKey":"bank:SOC101:S101N1-088","payload":{"prompt":"Which of the following statements correctly compares sociology with another social science?","options":["Psychology focuses on the individual, while sociology looks at how group interaction affects the individual","Economics covers all institutions, while sociology covers only demand and supply","Anthropology covers past and present, while sociology studies only early human life","History studies past and present, while sociology studies only past events"],"correctOption":0,"section":"Sociology and other social sciences","explanation":"Psychology centres on the individual's mental processes, while sociology looks at how group interaction affects the individual. Each of the other statements reverses the two disciplines, for example history studies past events while sociology covers past and present."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 101, $official_bank_source${"itemId":"6cf58d7a-3d7b-5932-b00e-52040c7ec878","questionId":"881aadd6-077e-5bcc-b197-4fb449b61a91","sourceKey":"bank:SOC101:S101N1-089","payload":{"prompt":"Which of the following statements about sociology and other social sciences is NOT correct?","options":["Political science studies political institutions, while sociology asks how they affect society","Psychology focuses on the individual, while sociology looks at how group interaction affects the individual","History studies past and present, while sociology studies only past events","Economics covers production, demand and supply, while sociology covers all institutions that affect behaviour"],"correctOption":2,"section":"Sociology and other social sciences","explanation":"This statement reverses the two disciplines: history studies past events, while sociology studies past and present and how the past shapes the present. The statements about political science, economics and psychology are all correct comparisons."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 102, $official_bank_source${"itemId":"e99024a9-f978-5eab-8266-f9e5e110df19","questionId":"55c6b070-2d51-5eaf-951c-d07e0d633b53","sourceKey":"bank:SOC101:S101N1-091","payload":{"prompt":"How many social sciences are compared with sociology to show how it differs from them?","options":["Five","Six","Three","Four"],"correctOption":0,"section":"Sociology and other social sciences","explanation":"Sociology is compared with five social sciences: psychology, anthropology, political science, economics and history. Four is a common slip when history is forgotten as one of the comparisons."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 103, $official_bank_source${"itemId":"3ed7c6dc-8565-5137-9991-33c17c9c6bf8","questionId":"ca816750-252a-5320-b88c-19ba1a7bc3ff","sourceKey":"bank:SOC101:S101N1-092","payload":{"prompt":"Sociology is compared with psychology, anthropology, political science, economics and one other discipline. The other discipline is","options":["Chemistry","History","Physics","Geography"],"correctOption":1,"section":"Sociology and other social sciences","explanation":"The five disciplines compared with sociology are psychology, anthropology, political science, economics and history. Physics and chemistry are physical sciences, not social sciences."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 104, $official_bank_source${"itemId":"84cc7382-4705-5d0e-9fa4-fd656719079a","questionId":"d93fa1b6-9f21-5f44-94c2-898fb073027d","sourceKey":"bank:SOC101:SOC-0001","payload":{"prompt":"Which of these is true of a society?","options":["Its interest is secondary to the interest of individual members","Its lifespan can be equated to that of an individual member","It can be within a larger society","It can be without a differentiation of roles"],"correctOption":2,"section":"Status, role, society and culture","explanation":"A society can exist inside a bigger one, for example the Yoruba society existing within the wider Nigerian society. Option A is wrong because the interests of the society generally come before those of any single member, and option B is wrong because a society usually outlives its individual members. Option D fails because every society has some division of roles among its members."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 105, $official_bank_source${"itemId":"7e9109ba-8ece-51f0-8a14-5b6ff1ac3c76","questionId":"8faeb4ae-547b-5252-9775-f86a0f7a9ff9","sourceKey":"bank:SOC101:SOC-0030","payload":{"prompt":"The classical definition of culture as a complex whole of man's acquisition of knowledge, morals, beliefs, art, customs and any other capabilities and habits acquired by man as a member of society was given by","options":["Talcott Parsons","Charles Taylor","Ibn Khaldun","Edward Tylor"],"correctOption":3,"section":"Status, role, society and culture","explanation":"Edward Tylor gave this classic definition of culture in 1871, describing it as a complex whole that includes knowledge, belief, art, morals, law and custom. Charles Taylor (B) is a tempting look-alike name but a different scholar, and Parsons (A) and Ibn Khaldun (C) are known for other contributions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 106, $official_bank_source${"itemId":"d66be5de-7386-5f32-bcdc-be928eab34fc","questionId":"b7995059-7ab2-5bbc-aa7f-247dccdda7bb","sourceKey":"bank:SOC101:SOC-0032","payload":{"prompt":"The definition of behavioural patterns that suits a certain position accorded to somebody is regarded as","options":["Status","Role","Values","Sentiments"],"correctOption":1,"section":"Status, role, society and culture","explanation":"A role is the set of expected behaviours attached to a position, so it describes how someone in that position should act. Status (A) is the position itself, not the behaviour expected of it, while values (C) are standards of what is good and sentiments (D) are feelings."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 107, $official_bank_source${"itemId":"5ed0316c-2bb5-5d7a-a41a-0e824642d0b4","questionId":"0160ff39-ff53-57ff-8585-179c833636f5","sourceKey":"bank:SOC101:SOC-0034","payload":{"prompt":"One of the following is not an example of ascribed status","options":["The age of Nigeria's first lady","The gender of a housewife","The complexion of a beauty queen","The position of the Vice Chancellor of University of Lagos"],"correctOption":3,"section":"Status, role, society and culture","explanation":"The Vice Chancellor's position is an achieved status because it is earned through qualifications, effort and appointment. Age (A), gender (B) and complexion (C) are ascribed statuses, since people are born with them or acquire them without any effort."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 108, $official_bank_source${"itemId":"17297d1b-e20a-55d7-95bf-f69f9c9d977b","questionId":"0d762313-1e93-5e26-a189-41d2faafeee3","sourceKey":"bank:SOC101:SOC-0036","payload":{"prompt":"The social position which individuals occupy in society is referred to as:","options":["Social roles","Social status","Social class","Social placement"],"correctOption":1,"section":"Status, role, society and culture","explanation":"Social status is the position a person occupies in society or in a group, such as student, mother or chief. Social roles (A) are the behaviours expected of that position, and social class (C) is a wider economic ranking of groups rather than an individual's position."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 109, $official_bank_source${"itemId":"29df16ca-d25f-5c43-b655-0b8f4b1128bd","questionId":"95260857-3734-5109-ad32-3af5ace4e9d5","sourceKey":"bank:SOC101:SOC-0037","payload":{"prompt":"These are some of the features of culture except","options":["It is shared","It is social heritage","It is transmitted to children","It is biologically inherited"],"correctOption":3,"section":"Status, role, society and culture","explanation":"Culture is learned, not passed on through our genes, so saying it is biologically inherited is false. Options A, B and C are true features: culture is shared by a group, handed down as social heritage, and transmitted to children through socialization."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 110, $official_bank_source${"itemId":"20e7706a-c559-5d73-b365-c4dd0f25607d","questionId":"e0e1d19f-1ade-5a74-aa25-cf6d8c033386","sourceKey":"bank:SOC101:SOC-0038","payload":{"prompt":"The most comprehensive definition of society is a ________","options":["Membership of a social unit","Human beings in social interaction","Individuals in social interactions","A network of social relationships"],"correctOption":3,"section":"Status, role, society and culture","explanation":"Defining society as a network of social relationships captures the whole web of links between people, groups and institutions. Options B and C focus only on people interacting, and option A describes belonging to a unit, so none of them is as complete as D."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 111, $official_bank_source${"itemId":"a6ea9f5a-d599-591a-8ae9-f017b534093e","questionId":"90940c91-1e5f-555e-ab1d-e5e3d7923b3e","sourceKey":"bank:SOC101:SOC-0074","payload":{"prompt":"How is culture sustained?","options":["The fact of being transmitted from one generation to another generation","Because it is shared","Because it is learned","Because it is taught at home"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Culture survives over time because it is passed down from one generation to the next through socialization. Being shared (B) and learned (C) are true features of culture, but on their own they do not explain how it continues after its current members die, and the home (D) is only one place where it is passed on."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 112, $official_bank_source${"itemId":"a9069bba-0823-54ea-b91b-0d8d801fef12","questionId":"d7b01ad1-7558-5a3c-a0d1-9efa0ddd2e21","sourceKey":"bank:SOC101:SOC-0075","payload":{"prompt":"Cultural universals capture the fact that all societies are confronted with similar problems of adaptation and survival","options":["Yes","No","Not sure","Sometimes"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Yes - cultural universals, such as family, religion, language and some form of economy, are found everywhere because all societies face similar basic problems of survival. B, C and D wrongly deny or weaken this link."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 113, $official_bank_source${"itemId":"1b6de1a2-07a6-5e72-90f4-6006d6b7a762","questionId":"bd1a0ab4-12d0-575a-9102-04261c685532","sourceKey":"bank:SOC101:SOC-0077","payload":{"prompt":"One of the following is a feature of culture","options":["It is shared","It is learned","It is socially transmitted","All of the above"],"correctOption":3,"section":"Status, role, society and culture","explanation":"Culture is shared by members of a group, learned rather than inherited biologically, and transmitted from one generation to the next. Because A, B and C are all true features, D is the complete answer."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 114, $official_bank_source${"itemId":"accb2d33-e761-5a97-bfd0-eee6d57e1297","questionId":"75ed5cfc-ebb3-5034-88fa-c27bbb02599e","sourceKey":"bank:SOC101:SOC-0080","payload":{"prompt":"One of the following is not a culture area in Africa","options":["Zulu men area","Congo area","East African Cattle area","The Desert region"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Herskovits' culture areas of Africa include the Congo area, the East African Cattle area and the Desert region, among others such as the Guinea Coast and the Bushman area. 'Zulu men area' is not one of these zones, so it is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 115, $official_bank_source${"itemId":"07718610-62f1-5fa1-b3d9-bdb33fcc4e0c","questionId":"c88c8b51-8f39-57b0-9695-c3b8b81a37e0","sourceKey":"bank:SOC101:SOC-0240","payload":{"prompt":"Opposition or conflict with the norms and values of the dominant culture in a society describes","options":["Counterculture","Subculture","Opposition party","Cultism"],"correctOption":0,"section":"Status, role, society and culture","explanation":"A counterculture is a group whose norms and values oppose or conflict with those of the dominant culture in a society. Option B, a subculture, has some distinct ways but still fits within the dominant culture rather than opposing it, and option D, cultism, refers to secret cult groups, not this general concept."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 116, $official_bank_source${"itemId":"e8973652-a873-5d6e-bf2b-0d39085f3bee","questionId":"d9c839ef-52f0-5a16-903b-0bf736d58f1c","sourceKey":"bank:SOC101:SOC-0241","payload":{"prompt":"Which of the following makes an individual a member of any given society?","options":["Being born by a human being","Being born by parents who are legally married","Passing through socialization","Being able to speak the language of the members of that society"],"correctOption":2,"section":"Status, role, society and culture","explanation":"A person becomes a member of a society through socialization, the process of learning its norms, values and way of life. Being born to humans or to married parents in A and B does not by itself make someone part of a society. Speaking the language in D is one result of socialization, not the whole of it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 117, $official_bank_source${"itemId":"8c576d83-f7da-5b32-befd-26d504830fc0","questionId":"6e0c8b1f-906a-5517-bc6b-6ed50ec59ac7","sourceKey":"bank:SOC101:SOC-0261","payload":{"prompt":"Which of these best describes a society?","options":["Any crowd of people who happen to gather in one place","Its life span equates that of an individual","It is created by a single individual","An aggregate of interacting members with mutual obligations and expectations"],"correctOption":3,"section":"Status, role, society and culture","explanation":"A society is made up of people who interact with one another over time and share mutual obligations and expectations, which is why D fits best. Option A describes a mere crowd or aggregate, whose members need not interact or share expectations. Option B is wrong because a society outlives any single member, and option C is wrong because no one person creates a society."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 118, $official_bank_source${"itemId":"df1aa46b-465e-5ee7-aefe-3aea8e2abba9","questionId":"762e5598-e859-5643-baad-cb190221a4bc","sourceKey":"bank:SOC101:SOC-0270","payload":{"prompt":"The definition of society as \"a number of individuals connected by interaction\" was by","options":["Herbert Spencer","George Mead","Georg Simmel","Edward Tylor"],"correctOption":2,"section":"Status, role, society and culture","explanation":"Georg Simmel defined society as a number of individuals connected by interaction, stressing that society exists in the interactions between people. Herbert Spencer in A compared society to a living organism, and Edward Tylor in D is known for his classic definition of culture. George Mead in B focused on the self and symbolic interaction."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 119, $official_bank_source${"itemId":"fb2749b0-ceae-5b84-8b29-225a25a9c072","questionId":"8621a3cc-6dee-5456-9a9b-8dbdc6141f88","sourceKey":"bank:SOC101:SOC-0291","payload":{"prompt":"Which of the following combinations are correct in the make-up of non-material culture?","options":["Buildings and furniture","Furnishing and language","Institutions and ideas","Schools and colleges"],"correctOption":2,"section":"Status, role, society and culture","explanation":"Non-material culture is made up of intangible things such as ideas, beliefs, values and institutions. Options A and D list buildings, furniture, schools and colleges, which are material objects. Option B mixes material furnishings with non-material language, so it is not a correct combination."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 120, $official_bank_source${"itemId":"f9bb1d5c-c683-5ab6-aab8-c46bb27e61c8","questionId":"6b93a6c5-6ad6-5a84-86ee-0524e7745c74","sourceKey":"bank:SOC101:S101N1-093","payload":{"prompt":"In sociology, concepts are best described as","options":["Laws that govern the behaviour of inanimate objects","Positions people occupy in a group","Physical objects made by members of a society","Mental constructs that represent parts of the world in simplified form"],"correctOption":3,"section":"Status, role, society and culture","explanation":"Concepts are mental constructs that social scientists use to represent parts of the world in a simplified form. Positions people occupy in a group are statuses, not concepts."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 121, $official_bank_source${"itemId":"5b6c8292-7cb6-51d3-9176-8af2f29f742d","questionId":"dc238675-0c8a-5ed8-ae81-1cd2fe20f011","sourceKey":"bank:SOC101:S101N1-094","payload":{"prompt":"Defining an abstract concept in terms of how it will be measured is called","options":["Operationalisation","Socialization","Role strain","Positivism"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Operationalisation means defining an abstract concept by the way it will be measured. Socialization sounds similar but is the process by which a person becomes a member of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 122, $official_bank_source${"itemId":"18ecd67c-b430-5cdd-b3bd-ba16456b084e","questionId":"131a387d-7b24-5cfc-af5d-a4fa5372adb3","sourceKey":"bank:SOC101:S101N1-095","payload":{"prompt":"A UNILAG researcher decides to measure the social class of households in Ikeja by their monthly income. She is","options":["Showing cultural variability","Operationalising the concept of social class","Creating a counterculture","Assigning an ascribed status"],"correctOption":1,"section":"Status, role, society and culture","explanation":"Deciding how an abstract concept like social class will be measured, here through income, is operationalisation. Ascribed status is a position assigned at birth, which has nothing to do with choosing a measure."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 123, $official_bank_source${"itemId":"f9782a9c-fdf6-5d42-b157-c65569742bd1","questionId":"980ec3ad-7eef-5e9d-a735-514f44fd1b70","sourceKey":"bank:SOC101:S101N1-096","payload":{"prompt":"Concepts such as discrimination, exploitation, social class and power are described as","options":["Both descriptive and evaluative","Ascribed statuses","Material aspects of culture","Purely descriptive and never evaluative"],"correctOption":0,"section":"Status, role, society and culture","explanation":"These concepts both describe something and carry emotional or theoretical weight, so they are descriptive and evaluative at the same time. Calling them purely descriptive misses that they are loaded terms."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 124, $official_bank_source${"itemId":"ed0b44e0-0119-502f-acbd-64b18ac63adf","questionId":"e18227d7-2c74-5eed-a52a-234df6e7aa3c","sourceKey":"bank:SOC101:S101N1-097","payload":{"prompt":"A 100L student makes four claims about sociological concepts. The claim that is NOT true is that concepts","options":["Are mental constructs","Always describe only directly observable phenomena","May describe inferred phenomena","Must be operationalised when abstract"],"correctOption":1,"section":"Status, role, society and culture","explanation":"Some concepts describe directly observable phenomena, but others describe inferred phenomena, so saying they always describe only observable things is false. The other statements are all true of concepts."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 125, $official_bank_source${"itemId":"6302f1ff-6780-5f05-a495-4ec7d6203587","questionId":"202116b6-f761-5278-b022-b8eec43f2f41","sourceKey":"bank:SOC101:S101N1-098","payload":{"prompt":"Ascribed status is a status that is","options":["Assigned at birth, without effort","Earned through effort, merit or ability","Gained by passing an examination","Attached to a set of expected behaviours"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Ascribed status is assigned at birth and needs no effort, for example gender or complexion. Status earned through effort, merit or ability is achieved status."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 126, $official_bank_source${"itemId":"3ed20295-b742-5889-b1d2-ad9bcf9b9c49","questionId":"5d7bd497-a752-51cd-b5d4-d8fb52a9ac75","sourceKey":"bank:SOC101:S101N1-099","payload":{"prompt":"Being born female, or being born with a dark complexion, is an example of","options":["Role strain","Role conflict","Ascribed status","Achieved status"],"correctOption":2,"section":"Status, role, society and culture","explanation":"Gender and complexion come with birth and require no effort, so they are ascribed statuses. Achieved status would apply only to positions earned through effort or merit."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 127, $official_bank_source${"itemId":"f23b70c9-2a79-5850-b051-53e773ebcaf3","questionId":"ebcc9dbb-6ae3-5738-bd99-bf6b1acc09f7","sourceKey":"bank:SOC101:S101N1-100","payload":{"prompt":"A trader in Balogun market who is elected chairman of the market association after years of hard work holds","options":["An ascribed status","A counterculture","An achieved status","A role strain"],"correctOption":2,"section":"Status, role, society and culture","explanation":"The chairmanship was earned through effort and merit, so it is an achieved status. Ascribed status is assigned at birth without effort, which does not fit an elected position."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 128, $official_bank_source${"itemId":"6660bfe4-9d2b-5886-9239-136638fae7fa","questionId":"8dae1a5f-969a-5654-aa92-2c1a64f4cd00","sourceKey":"bank:SOC101:S101N1-101","payload":{"prompt":"Incompatible demands arising from the different statuses a person holds are known as","options":["Role conflict","Ascribed status","Counterculture","Role strain"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Role conflict arises when the different statuses a person holds make incompatible demands. Role strain is the related but separate idea of difficulty in meeting the demands of multiple roles."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 129, $official_bank_source${"itemId":"a7e730fe-7c30-5959-9712-4ff731965c17","questionId":"dedc13e4-6457-56b7-862a-3443754fe65d","sourceKey":"bank:SOC101:S101N1-103","payload":{"prompt":"How does role differ from status?","options":["Role is a position, while status is the expected behaviour","Role and status mean exactly the same thing","Status is a position a person occupies, while role is the set of expected behaviour attached to it","Status is always earned, while role is always assigned at birth"],"correctOption":2,"section":"Status, role, society and culture","explanation":"Status is the position a person occupies, and role is the set of norms, values and behaviour expected of someone in that position. The option that swaps them gets the two terms the wrong way round."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 130, $official_bank_source${"itemId":"b2cec2bd-8972-5772-a724-5842871746da","questionId":"863d743a-26aa-5520-9c19-9437ec3292ed","sourceKey":"bank:SOC101:S101N1-104","payload":{"prompt":"A man is a father at home, a manager at a firm in Ikeja and a member of a church choir. Each of these positions is an example of","options":["A status","A counterculture","A culture","A role strain"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Each of these is a position the man occupies in a specific context, which is what a status is. Role strain is the difficulty of meeting the demands of several roles, not the positions themselves."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 131, $official_bank_source${"itemId":"6a3698fa-e322-5a9d-862f-b9dfaaf662d8","questionId":"2ba9eaab-5138-581f-b436-5f46d405803f","sourceKey":"bank:SOC101:S101N1-105","payload":{"prompt":"A society is best defined as","options":["A population living in a given territory, with a social structure and a common culture","A mental construct used to explain social phenomena","The way of life of a people","A subgroup with its own customs inside a larger culture"],"correctOption":0,"section":"Status, role, society and culture","explanation":"A society is a population living in a given territory with a social structure and a common culture, forming a distinct, unified entity. The way of life of a people is the definition of culture, not society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 132, $official_bank_source${"itemId":"411ae883-f88e-5ded-8ffc-71f93241eb39","questionId":"5da37172-f323-5fd0-831e-78a83bdf5cb4","sourceKey":"bank:SOC101:S101N1-106","payload":{"prompt":"When societies are classified by economic system, which of the following is NOT one of the types?","options":["Horticultural society","Feudal society","Agrarian society","Pastoral society"],"correctOption":1,"section":"Status, role, society and culture","explanation":"Societies classified by economic system are hunting and gathering, pastoral, horticultural, agrarian, industrial and post-industrial. Feudalism is one of Marx's stages of history, not one of these types."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 133, $official_bank_source${"itemId":"51608132-b63d-5108-95bb-259a074e6f01","questionId":"89c42421-704a-5b27-8f80-30e3f5802ab8","sourceKey":"bank:SOC101:S101N1-107","payload":{"prompt":"Into how many types are societies classified by economic system?","options":["Seven","Five","Four","Six"],"correctOption":3,"section":"Status, role, society and culture","explanation":"There are six types: hunting and gathering, pastoral, horticultural, agrarian, industrial and post-industrial. Five is a common slip when post-industrial is forgotten."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 134, $official_bank_source${"itemId":"f2620277-bfa4-5a87-970f-5bb253b75e29","questionId":"44c94564-5949-5b20-bfaa-1769c9a56cf2","sourceKey":"bank:SOC101:S101N1-108","payload":{"prompt":"The example of China, with about 1.4 billion people, and Vatican City, with fewer than 800, shows that","options":["Societies vary in size","Culture is biologically inherited","Societies cannot exist within a larger society","Only large populations count as societies"],"correctOption":0,"section":"Status, role, society and culture","explanation":"China and Vatican City are both societies despite the huge difference in their populations, which shows that societies vary in size. Saying only large populations count as societies is contradicted by Vatican City itself."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 135, $official_bank_source${"itemId":"7a1f2b71-604d-52c3-a195-56c19def5868","questionId":"3136c475-1659-5b63-9bd7-7fabfb53e2ea","sourceKey":"bank:SOC101:S101N1-109","payload":{"prompt":"Culture is best defined as","options":["The way of life of a people, including the ideas and material objects that let them live together","Incompatible demands arising from different statuses","A population living in a given territory with a common social structure","The position a person occupies at a particular time"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Culture is the way of life of a people, covering both their ideas and the objects that allow them to live together. A population in a given territory with a social structure is the definition of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 136, $official_bank_source${"itemId":"1850dc49-e8b0-57fb-ba8b-a8f49b6b9d97","questionId":"56c647ed-2a25-5099-834a-84f23e90a27a","sourceKey":"bank:SOC101:S101N1-110","payload":{"prompt":"The two aspects of culture are","options":["Mechanical and organic","Ascribed and achieved","Material and non-material","Static and dynamic"],"correctOption":2,"section":"Status, role, society and culture","explanation":"Culture has two aspects: the physical objects people make and use, and the non-physical side such as ideas and institutions. Ascribed and achieved are the two types of status, not aspects of culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 137, $official_bank_source${"itemId":"4921d9b4-2cbf-57ab-a1ae-bc491a7c340a","questionId":"55cba697-6556-5bcf-8f42-a076dbbc47f4","sourceKey":"bank:SOC101:S101N1-111","payload":{"prompt":"The ideas and institutions of a people make up their","options":["Material culture","Ascribed status","Counterculture","Non-material culture"],"correctOption":3,"section":"Status, role, society and culture","explanation":"Ideas and institutions cannot be touched, so they belong to the non-physical side of culture. The physical objects a people produce and use, such as tools and clothing, make up the other aspect, so the option naming that physical side is wrong here."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 138, $official_bank_source${"itemId":"0da4e051-5aa7-5913-9b69-c6d4d0d4ca48","questionId":"a51fdac5-0d0d-5ce2-9ffd-fb4210770313","sourceKey":"bank:SOC101:S101N1-112","payload":{"prompt":"Culture has several features. Which of these does NOT describe culture?","options":["It is learned","It is personal to each individual","It is socially transmitted","It is shared"],"correctOption":1,"section":"Status, role, society and culture","explanation":"Culture is learned, shared and socially transmitted, and it is not personal because it is a product of social interaction. Each of the other options is a recognised feature of culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 139, $official_bank_source${"itemId":"b754a00a-cb20-5dca-b039-051ced8fdfcf","questionId":"05740313-0e81-5c62-852e-d8bcd9c7bf6b","sourceKey":"bank:SOC101:S101N1-113","payload":{"prompt":"Culture is not personal because it is","options":["A product of man's imagination","A product of social interaction","Biologically inherited","Limited to one individual"],"correctOption":1,"section":"Status, role, society and culture","explanation":"Culture comes from people interacting in society, so it is shared rather than personal. Biological inheritance is wrong because culture is learned, not passed on through genes."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 140, $official_bank_source${"itemId":"4e015768-981a-54f8-81c4-298592b4a6e4","questionId":"4b94a665-bc80-5fe7-a288-c4c3a7a3319d","sourceKey":"bank:SOC101:S101N1-114","payload":{"prompt":"Yoruba, Hausa and Igbo communities use different wedding customs to meet the same need of forming families. This illustrates","options":["Cultural variability","Cultural universals","Counterculture","Role conflict"],"correctOption":0,"section":"Status, role, society and culture","explanation":"Cultural variability means societies use different customs and artefacts to solve problems, as these different wedding customs show. Cultural universals is the tempting choice, but it refers to the fact that all societies face similar problems, not to the different ways they solve them."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 141, $official_bank_source${"itemId":"a587b35c-43d5-580d-807d-177cb7e4645c","questionId":"9c06b0b9-91dd-52da-a79f-25f77190f4af","sourceKey":"bank:SOC101:S101N1-115","payload":{"prompt":"Danfo drivers in Lagos share their own slang and practices while still being part of the wider Nigerian culture. This is an example of a","options":["Subculture","Ascribed status","Counterculture","Cultural universal"],"correctOption":0,"section":"Status, role, society and culture","explanation":"A subculture relates to a subgroup that has its own patterns within a larger culture. A counterculture would go further and oppose the norms and values of the dominant culture, which these drivers do not."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 142, $official_bank_source${"itemId":"1c73c119-e08e-5972-83c2-3dab2bdbc61b","questionId":"0d747fb7-cc68-57da-8d85-398ca9223eb9","sourceKey":"bank:SOC101:S101N1-116","payload":{"prompt":"Which of the following statements about society is correct?","options":["It must have more than one million people","It cannot have a social structure","It persists beyond the lifespan of its individual members","It ends when its oldest members die"],"correctOption":2,"section":"Status, role, society and culture","explanation":"A society continues to exist even as individual members are born and die, so it outlives any one of them. The claim that a society needs over a million people is contradicted by Vatican City, which has fewer than 800."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 143, $official_bank_source${"itemId":"a2bb7c36-c455-56dc-9d21-b6a2649e8e59","questionId":"71cb3047-fb48-5ea1-b5fe-dd4e0434ebe5","sourceKey":"bank:SOC101:SOC-0026","payload":{"prompt":"Societal order is particularly made possible through","options":["The police","The military","Religion","Shared rules of behavior"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Order in society rests mainly on shared rules of behaviour, that is, norms and values that most people accept and follow without being forced. The police (A) and military (B) only step in when those rules break down, and religion (C) is just one of several places such rules come from."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 144, $official_bank_source${"itemId":"59acd2c3-afbe-5b76-be71-3a0ae34f5bbe","questionId":"b746873b-9689-5c84-a8da-bf406903aadc","sourceKey":"bank:SOC101:SOC-0031","payload":{"prompt":"The feeling of confusion which people exhibit when confronted with a new situation or setting is regarded as:","options":["Cultural relativity","Culture diffusion","Culture shock","Ethnic values"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Culture shock is the disorientation and confusion people feel when they meet an unfamiliar culture or setting, such as a new student arriving in a very different city. Cultural relativity (A) is judging a culture by its own standards, and culture diffusion (B) is the spread of cultural traits from one society to another."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 145, $official_bank_source${"itemId":"91f2df8a-21b4-56e7-909b-859dee5a0997","questionId":"1a19011c-514d-5b9c-a61a-2e863a1bfefb","sourceKey":"bank:SOC101:SOC-0040","payload":{"prompt":"An attitude of judging other people's cultural practices based on one's cultural upbringing is called","options":["Ethnometricism","Ethnic comparison","Ethnocentrism","Ethnic division"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Ethnocentrism is the habit of judging other cultures by the standards of one's own and seeing one's own ways as superior. Options A, B and D sound similar but do not name this attitude; its opposite is cultural relativism."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 146, $official_bank_source${"itemId":"509f2257-5db4-5602-a4bc-c145b2bc6eb0","questionId":"12d5a8b1-953d-5133-858a-3b4c29b228c7","sourceKey":"bank:SOC101:SOC-0042","payload":{"prompt":"An attitude of respect for cultural differences rather than condemnation is","options":["Cultural independence","Cultural universals","Cultural relativity","Cultural traits"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Cultural relativity, or cultural relativism, means understanding and evaluating a culture on its own terms instead of condemning it by outside standards. Cultural universals (B) are features found in all societies, and cultural traits (D) are the single elements that make up a culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 147, $official_bank_source${"itemId":"d460f59d-1a4c-532b-be46-ccb80cb19e0f","questionId":"504c2ed8-9521-569b-b78a-02526405f162","sourceKey":"bank:SOC101:SOC-0193","payload":{"prompt":"The specific guide to action which defines acceptable and appropriate behaviour in a given situation is referred to as","options":["Norm","Value","Etiquette","Folkway"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"A norm is a specific guide to action that defines what behaviour is acceptable and appropriate in a particular situation. Option B, a value, is a broader standard of what is good or desirable, not a specific rule for a situation, and option D, a folkway, is only one type of norm."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 148, $official_bank_source${"itemId":"a1ae2762-32b7-534c-b3cf-d7b2436d3c0d","questionId":"6b410a0c-71ed-5483-92b5-048988f67612","sourceKey":"bank:SOC101:SOC-0211","payload":{"prompt":"The confusion that an unprepared visitor might experience when placed in an unfamiliar culture is called","options":["Cultural confusion","Ethical shock","Culture shock","Ethical relativism"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Culture shock is the disorientation and confusion a person feels when suddenly placed in an unfamiliar culture without preparation. Option A, cultural confusion, is not the standard term, and option D, ethical relativism, is the view that moral standards vary between cultures, not a feeling of confusion."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 149, $official_bank_source${"itemId":"002ae3e4-414a-5a35-9874-8ef848c3f96a","questionId":"0d4c9610-933f-5781-b8df-afc7adc19889","sourceKey":"bank:SOC101:SOC-0220","payload":{"prompt":"Is it possible to have a better or superior culture in the world than others?","options":["Yes","No","Sometimes","Neither true or false"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Cultural relativism holds that every culture should be understood on its own terms, so no culture can be ranked as better or superior to others. Option A reflects ethnocentrism, judging other cultures by the standards of one's own. Options C and D do not give a clear answer."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 150, $official_bank_source${"itemId":"5ada3080-748a-58b8-9ef9-6cb2f4a87ead","questionId":"8e57d16c-6973-5cc7-926b-ce82a0510a83","sourceKey":"bank:SOC101:SOC-0223","payload":{"prompt":"________ is dysfunctional when it breeds conflict and unhealthy communication","options":["Cultural variability","Ethnocentrism","Sub-culture","Culture"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Ethnocentrism is the view that one's own way of life is right and better than others. It can build group pride, but it becomes dysfunctional when it breeds conflict, prejudice and poor communication between groups. Option C, a sub-culture, is simply a group with distinct ways within a larger culture, and option A, cultural variability, just means cultures differ."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 151, $official_bank_source${"itemId":"f856badd-bad7-53ec-9bdc-683a9fdd0fc7","questionId":"be534123-8a52-55ff-bce2-d95d7a703989","sourceKey":"bank:SOC101:SOC-0258","payload":{"prompt":"The statement that a woman's place is in the kitchen is","options":["A religious injunction","Value laden","A law of nature","A truism"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"The statement that a woman's place is in the kitchen is value laden, meaning it reflects a judgement about how things should be rather than an objective fact. Option C is wrong because gender roles are shaped by culture, not fixed by nature, and option D, a truism, would mean it is obviously true for everyone."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 152, $official_bank_source${"itemId":"3c028b1d-6547-591b-8772-9f087fba9836","questionId":"51d7f961-3bb2-5ac5-86d0-02af5088eae8","sourceKey":"bank:SOC101:SOC-0277","payload":{"prompt":"The statement \"a man should not cry like a woman\" is","options":["A biological fact","A social belief","A general claim","A natural law"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"This statement reflects a gender expectation that society teaches people, so it is a social belief (B). Options A and D are wrong because nothing in biology or nature stops men from crying; the idea comes from culture. Option C is too vague, since the main point is that the belief is socially created."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 153, $official_bank_source${"itemId":"3affcdad-9f60-5bab-b49a-43430b4289dc","questionId":"8246b28c-84f5-5817-bae4-59ec6821ea42","sourceKey":"bank:SOC101:SOC-0292","payload":{"prompt":"The aspect of institutions that represents an acceptable way of behaving enforced through sanctions/punishments and seen as fundamental to the survival of society is described as:","options":["Beliefs","Folkways","Fashions","Mores"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Mores are strongly held norms seen as vital to the survival and moral order of society, and breaking them attracts serious sanctions. Option B, folkways, are everyday customs that carry little or no punishment. Beliefs in A and fashions in C are not norms enforced by strong sanctions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 154, $official_bank_source${"itemId":"60afee29-14bd-572a-9dc8-97828c2deae4","questionId":"25eb7bc4-f23f-5045-babb-7b802a328e9c","sourceKey":"bank:SOC101:SOC-0299","payload":{"prompt":"The tendency to judge other people's culture by comparing it with one's own is regarded as","options":["Cultural variability","Cultural diversity","Ethnocentrism","Cultural universals"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Ethnocentrism is the view that one's own way of life is right and better than others, so it means judging other cultures by the standards of your own (C). Options A and B simply describe the fact that cultures differ, without any judgement. Option D refers to features found in all cultures."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 155, $official_bank_source${"itemId":"5637b78d-e6ae-564e-b716-13da5596239a","questionId":"00b5b81d-97c3-5213-a532-c5901614493a","sourceKey":"bank:SOC101:S101N2-001","payload":{"prompt":"Contact between peoples with different cultures, which can lead to changes in both cultural systems, is known as","options":["Culture contact","Ethnocentrism","Cultural relativism","Cultural lag"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"Culture contact is simply the meeting of peoples who hold different cultures, and such meetings can change both cultures involved. Cultural lag is a different idea: it describes material culture changing faster than non-material culture within one society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 156, $official_bank_source${"itemId":"a38d9877-3463-571c-affa-4dbefc0d8b4d","questionId":"a5e1264e-a5a5-5341-b6d9-1711ab8737f7","sourceKey":"bank:SOC101:S101N2-002","payload":{"prompt":"The process of cultural change in which a person acquires, adopts or adjusts to a dominant culture in a new cultural environment is called","options":["Culture shock","Acculturation","Ethnocentrism","Cultural lag"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Acculturation describes a person taking on or adjusting to the dominant culture of a new environment. Culture shock is tempting, but it is only the confusion felt on first entering an unfamiliar setting, not the gradual adoption of the new culture."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 157, $official_bank_source${"itemId":"89d4336e-a145-5b5b-9ffc-cf39496cdda8","questionId":"c3297346-c84a-548c-b616-d47450236938","sourceKey":"bank:SOC101:S101N2-003","payload":{"prompt":"Halima moved from Sokoto to Lagos for her 100L studies at UNILAG. Over two years she gradually adopted Lagos styles of dressing, speech and food. This process is best described as","options":["Culture shock","Ethnocentrism","Acculturation","Cultural lag"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Halima is adjusting to and adopting the dominant culture of her new environment, which is acculturation. Culture shock would describe the confusion she might have felt in her first days, but the scenario stresses gradual adoption over two years."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 158, $official_bank_source${"itemId":"1e5c382a-752a-51ae-b847-5bdb6d027331","questionId":"4e21e9b7-f643-5b8d-9255-ae0829843ca9","sourceKey":"bank:SOC101:S101N2-004","payload":{"prompt":"Acculturation occurs when","options":["Members of a society disregard all of its norms","Peoples of different cultures come into contact","A person judges others by the standards of his own culture","Material culture changes faster than non-material culture"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Acculturation takes place when cultures come into contact, so that a person in a new cultural environment adjusts to the dominant culture there. The option about material culture changing faster describes cultural lag, which is a separate process inside one culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 159, $official_bank_source${"itemId":"161ee83a-fbe8-5b42-a255-6556d0f1b3e9","questionId":"d3084a46-d7e2-5f80-bce3-558736608296","sourceKey":"bank:SOC101:S101N2-005","payload":{"prompt":"A fresher from a small village arrives at UNILAG and spends her first week confused and disoriented by the crowds, slang and fast pace of life in Akoka. She is experiencing","options":["Culture shock","Acculturation","Cultural lag","Cultural relativism"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"Culture shock is the confusion a person feels in a new or unfamiliar setting, which is exactly what the fresher feels in her first week. Acculturation would come later, when she gradually adopts the new ways, so it does not fit this early confusion."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 160, $official_bank_source${"itemId":"1eaa513d-d772-56ee-8b1f-e9760004e4e7","questionId":"aa204a5c-59e4-563d-bf21-2970a7b5110d","sourceKey":"bank:SOC101:S101N2-006","payload":{"prompt":"Chinedu felt confused during his first weeks in Lagos (X), but over time he took on the city's ways of living (Y). X and Y are respectively","options":["Culture shock and acculturation","Acculturation and culture shock","Cultural lag and ethnocentrism","Ethnocentrism and cultural relativism"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"The early confusion in an unfamiliar setting is culture shock, and the later adjustment to the dominant culture is acculturation. Reversing the two terms is the tempting mistake, but acculturation is the adoption stage, not the confusion stage."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 161, $official_bank_source${"itemId":"bd4190e3-5f16-57be-9547-f683ff23d7c8","questionId":"1669516f-edd5-58ba-b752-31f9a980fb04","sourceKey":"bank:SOC101:S101N2-007","payload":{"prompt":"The situation in which material culture changes faster than non-material culture is called","options":["Culture contact","Cultural relativism","Cultural lag","Acculturation"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Cultural lag describes the gap that opens when physical objects and technology change faster than ideas, values and rules. Acculturation is about a person adjusting to a dominant culture in a new environment, not about one part of culture trailing another."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 162, $official_bank_source${"itemId":"ced3379f-f795-5f87-a6b0-def102ade5b0","questionId":"5a9dc3c8-b025-5daf-bd5b-cecefc6f8584","sourceKey":"bank:SOC101:S101N2-008","payload":{"prompt":"Which of the following correctly describes cultural lag?","options":["Material culture changes faster than non-material culture","Material and non-material culture always change at the same rate","A person adjusts to the dominant culture of a new environment","Non-material culture changes faster than material culture"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"In cultural lag, material culture (objects and technology) moves ahead while non-material culture (ideas, norms and laws) trails behind. The reversed statement, that non-material culture changes faster, is the most tempting wrong option, but it gets the direction of the lag the wrong way round."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 163, $official_bank_source${"itemId":"1c4d882d-df32-56b4-a4cb-7f06404b19b8","questionId":"99a1a673-d359-5dd2-9164-def1ac2cedd8","sourceKey":"bank:SOC101:S101N2-009","payload":{"prompt":"Smartphones and social media spread rapidly across Nigeria, but laws and public attitudes about online privacy took many years to catch up. This illustrates","options":["Ethnocentrism","Acculturation","Culture shock","Cultural lag"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"The technology (material culture) changed quickly while the laws and attitudes (non-material culture) trailed behind, which is cultural lag. Culture shock is about an individual's confusion in a strange setting, not a society's rules lagging behind its technology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 164, $official_bank_source${"itemId":"01f74d82-b35e-529e-916c-6c305f679536","questionId":"156225b0-2baa-51b6-bec7-d1263911ef42","sourceKey":"bank:SOC101:S101N2-010","payload":{"prompt":"Judging a person's behaviour by the standards of that person's own culture, rather than by the evaluator's culture, is known as","options":["Cultural relativism","Acculturation","Culture contact","Ethnocentrism"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"Cultural relativism means understanding behaviour in terms of the actor's own culture. Ethnocentrism is the opposite attitude, because it judges others by the evaluator's own ways and treats them as the best."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 165, $official_bank_source${"itemId":"3bdc9faf-0a43-5dc3-89c4-a09b5c0a0907","questionId":"52db5556-f52c-5d20-ba84-b32797ddeef3","sourceKey":"bank:SOC101:S101N2-011","payload":{"prompt":"On a field trip, a UNILAG sociology student sees a community where people greet elders by kneeling for a long time. Instead of calling it strange, she interprets it by that community's own customs. She is practising","options":["Cultural lag","Ethnocentrism","Culture shock","Cultural relativism"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Interpreting a practice by the standards of the people who practise it is cultural relativism. Ethnocentrism would mean judging the greeting by her own culture and treating her own ways as better."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 166, $official_bank_source${"itemId":"2acdeb86-96e6-5f6c-a9ea-90feb620c61e","questionId":"9efb81bc-e2ca-5f86-9ec6-7033eb918056","sourceKey":"bank:SOC101:S101N2-012","payload":{"prompt":"Which attitude is the opposite of ethnocentrism?","options":["Cultural lag","Culture shock","Acculturation","Cultural relativism"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Ethnocentrism treats one's own ways as right and better than others', while cultural relativism judges behaviour by the actor's own culture and respects differences. Acculturation is a process of adjusting to a dominant culture, not an attitude that opposes ethnocentrism."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 167, $official_bank_source${"itemId":"25ec4a5f-a387-50ab-a6a2-0f25d0f2586d","questionId":"d902ce48-81bd-5ea0-8014-0ad099c78488","sourceKey":"bank:SOC101:S101N2-013","payload":{"prompt":"A trader in Balogun market insists that only his own ethnic group's wedding customs are proper and that every other group's customs are backward. His attitude is an example of","options":["Ethnocentrism","Acculturation","Cultural relativism","Cultural lag"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"Ethnocentrism is the view that one's own ways are right and better than other people's, which is exactly the trader's attitude. Cultural relativism would require him to judge other weddings by their own cultures, which he refuses to do."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 168, $official_bank_source${"itemId":"2009357f-09b9-5ec9-89ee-ebde8f01a53b","questionId":"8d5042bd-f82b-5df8-b6a9-b93fc2738c9f","sourceKey":"bank:SOC101:S101N2-014","payload":{"prompt":"Which of the following statements best expresses ethnocentrism?","options":["\"Every culture should be judged by its own standards.\"","\"I felt confused when I first arrived in this new city.\"","\"Our way of doing things is right and better than other people's.\"","\"New technology spreads faster than new laws.\""],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Ethnocentrism is the belief that one's own ways are right and superior to those of others. The statement that every culture should be judged by its own standards expresses cultural relativism, which is the opposite attitude."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 169, $official_bank_source${"itemId":"60cc2631-2700-502c-8e88-059acec30a39","questionId":"af655b2d-1183-5211-b6eb-dfb366032120","sourceKey":"bank:SOC101:S101N2-015","payload":{"prompt":"A norm is best described as","options":["The confusion felt in a new or unfamiliar setting","A shared expectation of behaviour that shows what is culturally appropriate","The process of adjusting to a dominant culture","A standard for deciding what is good and just within a culture"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"A norm is a shared expectation about how people should behave, showing what the culture considers appropriate. The standard for deciding what is good and just describes a value, which is the reason behind behaviour rather than the expectation itself."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 170, $official_bank_source${"itemId":"26f5d492-67c4-54ec-995f-f2e2b3c23de7","questionId":"007044a1-40eb-571c-b890-518e03d2949b","sourceKey":"bank:SOC101:S101N2-016","payload":{"prompt":"Norms are prescriptive, so they resemble laws. In what way do norms differ from laws?","options":["They are never enforced","They lack the formal status of rules","They are biologically inherited","They apply only to individuals and never to groups"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Norms tell people how to behave, much like laws, but they do not carry the formal status of written rules. The idea that norms are never enforced is wrong, because norms are backed by positive and negative sanctions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 171, $official_bank_source${"itemId":"db7c0506-afcc-54e8-af0c-281d7c6265b0","questionId":"e754a070-b340-53bd-96bc-51b24ed85066","sourceKey":"bank:SOC101:S101N2-017","payload":{"prompt":"To say that norms are prescriptive means that they","options":["Indicate how people ought to behave","Describe how technology changes over time","Are passed on biologically from parents","Are enforced only by the government"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"Prescriptive means that norms set out how people are expected to behave, which is why they resemble laws. Saying they are enforced only by the government is wrong, since norms lack the formal status of rules and are enforced through social sanctions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 172, $official_bank_source${"itemId":"1dcd9413-82c3-548c-bee8-6449cc397b96","questionId":"1732ca2e-84d7-5d29-a6d9-d3ab88b0efc6","sourceKey":"bank:SOC101:S101N2-018","payload":{"prompt":"Behaviour that departs from a norm may be described as","options":["Ethnocentric","Acculturated","Conformist","Deviant"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Deviance is departure from a norm, so behaviour that breaks a shared expectation may be called deviant. Conformist behaviour is the opposite, since it follows the norm rather than departing from it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 173, $official_bank_source${"itemId":"5aff44da-3d23-5ed4-90ec-34951fe4ff76","questionId":"edd5ac61-7040-51f0-8439-789fc6610475","sourceKey":"bank:SOC101:S101N2-019","payload":{"prompt":"Standards for deciding what is good and just within a culture are called","options":["Norms","Folkways","Sanctions","Values"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Values are a culture's standards of what is good and just, and they shape attitudes and decisions. Norms are related but different: they are the shared expectations of behaviour, while values are the deeper standards behind them."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 174, $official_bank_source${"itemId":"66f4b5ed-5506-5dae-9357-63fe09fecf26","questionId":"143a751d-ee99-50d3-b97a-918f60fe0deb","sourceKey":"bank:SOC101:S101N2-020","payload":{"prompt":"The underlying reasons behind people's behaviour within a culture are provided by its","options":["Sanctions","Values","Cultural lag","Material objects"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Values transmit a culture's beliefs, shape attitudes and decisions, and serve as the underlying reasons for behaviour. Sanctions are rewards and punishments that enforce norms; they push people to comply but are not the deeper reasons behind behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 175, $official_bank_source${"itemId":"944931ac-126a-537a-ad21-dd8292250938","questionId":"06b0ffc3-140c-5bcc-8635-9e05c5a8dc8f","sourceKey":"bank:SOC101:S101N2-021","payload":{"prompt":"Which of the following is NOT a role of values in a culture?","options":["They serve as the underlying reasons for behaviour","They transmit the culture's beliefs","They give norms the formal status of written laws","They shape people's attitudes and decisions"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Values transmit beliefs, shape attitudes and decisions, and give the underlying reasons for behaviour. They do not turn norms into formal laws; norms resemble laws but lack the formal status of rules."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 176, $official_bank_source${"itemId":"eeb33f44-e377-50ef-beff-995933b3e76c","questionId":"43adb655-d321-5e5b-96ea-c6e9f1eb4796","sourceKey":"bank:SOC101:S101N2-022","payload":{"prompt":"Which pair is correctly matched?","options":["Norm: a standard for judging what is good and just; Value: a shared expectation of behaviour","Norm: material culture; Value: non-material culture","Norm: a shared expectation of behaviour; Value: a standard for judging what is good and just","Norm: confusion in a new setting; Value: judging others by one's own culture"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"A norm is the shared expectation of how to behave, while a value is the standard for deciding what is good and just. The swapped pairing is the tempting error, because the two ideas are closely linked, but it reverses their meanings."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 177, $official_bank_source${"itemId":"40c689d5-3e30-5572-b6ae-2ae39f2d644b","questionId":"2c24974b-72ae-522a-b021-8dab88339ddb","sourceKey":"bank:SOC101:S101N2-023","payload":{"prompt":"Norms in a society are enforced through","options":["Positive and negative sanctions","Negative sanctions only","Biological instincts","Written laws and courts only"],"correctOption":0,"section":"Culture contact, norms and values","explanation":"Norms are backed by both rewards (positive sanctions) and punishments (negative sanctions). Limiting enforcement to negative sanctions misses the rewards people receive for conforming, and norms lack the formal status of laws, so courts are not their only means of enforcement."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 178, $official_bank_source${"itemId":"ab89c4c3-25e1-5f43-b9de-e2e529d206fe","questionId":"c9f195af-353d-5eba-9a2f-d3d0712f91da","sourceKey":"bank:SOC101:S101N2-024","payload":{"prompt":"A department at UNILAG publicly praises and gives a prize to the student with the best attendance record. This is an example of","options":["Cultural lag","A positive sanction","Ethnocentrism","A negative sanction"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Rewarding people for keeping to a norm, here punctual attendance, is a positive sanction. A negative sanction would be a punishment for breaking the norm, such as a penalty for absence."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 179, $official_bank_source${"itemId":"08609e84-df28-55dc-8713-69131ff53773","questionId":"4bbf35fe-48b8-50b4-b574-292d3dfb4a5d","sourceKey":"bank:SOC101:S101N2-025","payload":{"prompt":"Folkways and mores are both types of","options":["Sanctions","Values","Norms","Institutions"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Folkways and mores are kinds of norms, that is, shared expectations of behaviour; mores are the more serious ones, seen as fundamental to society's survival. They are not institutions, which are organised structures such as the family or education."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 180, $official_bank_source${"itemId":"af1d950a-583b-5cd1-9215-2c370c389a8a","questionId":"2fea3e96-a9ac-59fa-a58e-f4f462c2b636","sourceKey":"bank:SOC101:S101N2-026","payload":{"prompt":"Which of the following is NOT true of norms?","options":["Departing from them may be called deviant","They are enforced by positive and negative sanctions","They are shared expectations of behaviour","They have the same formal status as written rules"],"correctOption":3,"section":"Culture contact, norms and values","explanation":"Norms resemble laws because they are prescriptive, but they lack the formal status of rules, so this statement is false. The other statements are all true: norms are shared expectations, they are backed by sanctions, and departing from them may be called deviant."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 181, $official_bank_source${"itemId":"32d6cc12-9da5-544b-9f7d-3d9a3f3086de","questionId":"d3bd5708-b266-53c5-b1b7-ea475c4bfaba","sourceKey":"bank:SOC101:S101N2-027","payload":{"prompt":"When two peoples with different cultures come into contact, which of their cultures may change?","options":["Only the dominant culture","Both cultures","Only the weaker culture","Neither culture"],"correctOption":1,"section":"Culture contact, norms and values","explanation":"Culture contact can change both cultural systems involved, not just one of them. Saying only the weaker culture changes is tempting because acculturation involves adjusting to a dominant culture, but culture contact itself can affect both sides."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 182, $official_bank_source${"itemId":"72496e18-6898-5bc8-be8f-e96396a589a3","questionId":"0942181a-5f24-58cc-b8f7-58249e411e47","sourceKey":"bank:SOC101:S101N2-028","payload":{"prompt":"A family in Surulere scolds and withdraws privileges from a teenage son who refuses to greet visiting elders. The family is applying","options":["Acculturation","Cultural relativism","A negative sanction","A positive sanction"],"correctOption":2,"section":"Culture contact, norms and values","explanation":"Punishing someone for breaking a norm, here the expectation of greeting elders, is a negative sanction. A positive sanction would be a reward for keeping the norm, which is the opposite of what the family is doing."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 183, $official_bank_source${"itemId":"dcebb8de-28e5-5edb-bc30-aea19a66243c","questionId":"a02696c1-c36b-5e40-83fc-0eebfae08d8d","sourceKey":"bank:SOC101:SOC-0081","payload":{"prompt":"The three main components of the self according to Sigmund Freud are ________, ________ and ________","options":["Id, Ego and Persona","Ego, Ido and superior Ego","Id, the Ego and the Superego","Superman, idea and Ego"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"Freud divided the personality into the id (basic drives), the ego (the reality-based self) and the superego (the conscience shaped by society's rules). Option A swaps in 'persona', which is a term from Carl Jung, and options B and D are distortions of Freud's terms."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 184, $official_bank_source${"itemId":"4f3c830b-d2c2-565d-9589-e275b7c723fd","questionId":"3b13f980-8f42-5a6f-bc6f-645f36d41df9","sourceKey":"bank:SOC101:SOC-0297","payload":{"prompt":"Which of these attributes gender roles to capitalism?","options":["Biological determinism","Marxism","Cultural determinism","Socio-biology"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Marxism, and Marxist feminism in particular, argues that gender roles serve capitalism, for example by having women do unpaid housework that supports male workers. Options A and D explain gender roles through biology, and C, cultural determinism, explains them through culture in general rather than capitalism."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 185, $official_bank_source${"itemId":"50702061-357b-5912-a4f4-013e8bcd4700","questionId":"dab302e0-3619-5436-9674-36fff13c85e0","sourceKey":"bank:SOC101:S101N2-029","payload":{"prompt":"A set of related ideas meant to explain a phenomenon, based on general principles independent of the thing being explained, is a","options":["Social fact","Concept","Value","Theory"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"A theory links several ideas together to explain something, using general principles that stand apart from the thing explained. A concept is narrower: it is a single mental construct or term used to describe part of the social world, not a set of related explanatory ideas."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 186, $official_bank_source${"itemId":"ad7405e8-f0a3-5c4e-bf70-e17462fbe57f","questionId":"4ab49661-eb4c-5804-9a1b-84c5cb03e826","sourceKey":"bank:SOC101:S101N2-030","payload":{"prompt":"Related ideas or suppositions that explain social reality from a sociological standpoint are known as","options":["Social structure","Sociological theory","Sociological imagination","Value consensus"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Sociological theory is the set of related ideas or suppositions used to explain social reality from a sociological point of view. The sociological imagination is a different idea, linked to looking beyond the everyday meaning of actions to their hidden reasons."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 187, $official_bank_source${"itemId":"d8089d98-02f1-5f45-9284-41c582e4d1b0","questionId":"0dca98b3-4dc8-59cf-b391-edfae192f0ff","sourceKey":"bank:SOC101:S101N2-031","payload":{"prompt":"Sociological theories that address society-wide problems are described as","options":["Manifest theories","Micro theories","Latent theories","Macro theories"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"Macro theories look at problems across the whole society, while micro theories focus on smaller groups. Latent and manifest are terms for kinds of functions, not for the scope of a theory."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 188, $official_bank_source${"itemId":"f8bb4721-c9e2-5e0e-9bd9-b3300b595b03","questionId":"dad601f7-677b-59e7-be57-1346862e1911","sourceKey":"bank:SOC101:S101N2-032","payload":{"prompt":"In sociology, each major theory is described as a distinct","options":["Paradigm","Superstructure","Pattern variable","Social fact"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Each sociological theory offers its own way of seeing society, so it is called a distinct paradigm. A pattern variable is a specific concept from Parsons, such as universalism versus particularism, not a name for a whole theory."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 189, $official_bank_source${"itemId":"ef82f79d-fada-5068-a550-ea638bee3cf1","questionId":"bd396e2d-7949-5380-8e33-cfe730bb8792","sourceKey":"bank:SOC101:S101N2-033","payload":{"prompt":"Functionalist, conflict and symbolic interactionist perspectives are three of the four main sociological perspectives. Which completes the four?","options":["Evolutionist","Positivist","Feminist","Ethnocentric"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"The four perspectives are functionalist, conflict, feminist and symbolic interactionist. Evolutionist is tempting because Comte and Durkheim held evolutionary views of society, but evolutionism is not counted among the four perspectives."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 190, $official_bank_source${"itemId":"2e5fa137-9349-50e8-8168-6336e9317afb","questionId":"90a2fa32-4664-528f-ac40-6c3b81118168","sourceKey":"bank:SOC101:S101N2-034","payload":{"prompt":"The perspective that sees society as a system of interrelated parts, each understood by its contribution to maintaining the whole, is","options":["Feminism","Functionalism","Symbolic interactionism","The conflict perspective"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Functionalism treats society as a system whose parts, such as the family, are explained by how they help keep the system going. The conflict perspective instead sees fundamental differences of interest making conflict a permanent feature of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 191, $official_bank_source${"itemId":"ca46496b-98f6-5118-a896-7ae19274f8ac","questionId":"bbfe53fd-0175-5e84-9915-6748f914417c","sourceKey":"bank:SOC101:S101N2-035","payload":{"prompt":"In functionalism, the basic needs that must be met for a society to survive are called","options":["Latent functions","Functional prerequisites","Social facts","Pattern variables"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Functional prerequisites are the basic needs a society must meet to survive, and each part of society meets some of them. Latent functions are something else: the unintended and unrecognised consequences of social activities."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 192, $official_bank_source${"itemId":"0d7b6179-7243-5d5c-a835-fab45650a3ed","questionId":"dbf0378a-953a-5253-9e11-4b6434127e06","sourceKey":"bank:SOC101:S101N2-036","payload":{"prompt":"Functionalists hold that the parts of society are integrated by agreement on goals, morals and ethics. This agreement is called","options":["Value consensus","Ruling-class ideology","False consciousness","Functional prerequisites"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Value consensus is shared agreement on goals, morals and ethics, and functionalists see it as what holds the parts of society together. False consciousness is a Marxist idea about workers accepting an unfair system, not a genuine agreement on values."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 193, $official_bank_source${"itemId":"05831820-6f43-54de-bf26-d4a179180c6f","questionId":"d2d62014-9b4d-5851-9504-6908ead18c79","sourceKey":"bank:SOC101:S101N2-037","payload":{"prompt":"Functionalists argue that social order requires mechanisms of","options":["Patriarchy","False consciousness","Social control","Class struggle"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"In functionalism, keeping social order depends on mechanisms of social control. Class struggle belongs to the conflict perspective, which sees conflict, not order, as the permanent feature of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 194, $official_bank_source${"itemId":"b249f421-b987-5562-9467-7f25942464fd","questionId":"440573c7-4696-52c3-8dae-e72d18afc950","sourceKey":"bank:SOC101:S101N2-038","payload":{"prompt":"The view that fundamental differences of interest make conflict a permanent feature of society belongs to","options":["Functionalism","Structural functionalism","Symbolic interactionism","The conflict perspective"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"The conflict perspective holds that groups have fundamentally different interests, so conflict never disappears from society. Functionalism, by contrast, stresses value consensus and the smooth working of interrelated parts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 195, $official_bank_source${"itemId":"277ec6ec-7196-5e82-8893-b9e39bd742b4","questionId":"794f2ade-cc45-57a9-903e-d03cfdd4840d","sourceKey":"bank:SOC101:S101N2-039","payload":{"prompt":"Which statement about conflict theorists is correct?","options":["They see conflict as permanent but disagree on its nature, causes and extent","They believe value consensus integrates the parts of society","They hold that meaning is constructed through interpreting gestures","They regard conflict as a temporary feature of society"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Conflict theorists share the view that conflict is a permanent feature of society, yet they disagree about its nature, causes and extent. Value consensus integrating society is the functionalist position, which is the opposite of the conflict view."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 196, $official_bank_source${"itemId":"6647c2da-8a84-5dcd-8b14-7e7aad8f9cd3","questionId":"96f71124-b972-5359-8805-bdd4ab6ccaac","sourceKey":"bank:SOC101:S101N2-040","payload":{"prompt":"In Marxist theory, the economic base or infrastructure of society is made up of","options":["Ruling-class ideology and false consciousness","The forces of production and the social relations of production","Value consensus and social control","Political, legal and educational institutions"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Marxism defines the economic base as the forces of production plus the social relations of production. Political, legal and educational institutions make up the superstructure, which the base determines."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 197, $official_bank_source${"itemId":"38bc7c80-d359-5a33-85e5-b3ae8510255e","questionId":"02cb855c-9a36-5b3b-bd69-9729154071fd","sourceKey":"bank:SOC101:S101N2-041","payload":{"prompt":"In Marxist theory, the political, legal and educational institutions of a society together form the","options":["Relations of production","Forces of production","Infrastructure","Superstructure"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"Marxists call the political, legal, educational and similar institutions the superstructure. The infrastructure is the economic base, made up of the forces and relations of production, which shapes the superstructure."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 198, $official_bank_source${"itemId":"32b01d13-7964-59b0-9d4c-eb49db1b9df6","questionId":"395c6bb8-08f0-52cf-8e83-86e1484230ea","sourceKey":"bank:SOC101:S101N2-042","payload":{"prompt":"In Marxist theory, ruling-class ideology makes workers accept the system that exploits them. The resulting state of mind is called","options":["Value consensus","Collective conscience","Anomie","False consciousness"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"False consciousness is the condition, created by ruling-class ideology, in which workers accept an unfair system. Value consensus is the functionalist idea of genuine agreement on goals and morals, not acceptance produced by ideology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 199, $official_bank_source${"itemId":"c063da01-92df-578a-9cc7-fb8c04c9edaf","questionId":"66d9950d-a457-5b47-9fff-808ad0e6083f","sourceKey":"bank:SOC101:S101N2-043","payload":{"prompt":"Factory workers in Ikeja earn very low wages, yet they believe the system is fair and that their bosses deserve all the profit. A Marxist would describe the workers as having","options":["Latent functions","Value consensus","False consciousness","A looking-glass self"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"Marxists say ruling-class ideology produces false consciousness, which makes exploited workers accept the system. Value consensus is the functionalist idea of real agreement on values; a Marxist would not see the workers' acceptance as genuine agreement."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 200, $official_bank_source${"itemId":"643fb9a5-cad7-58b9-949e-7b181a9525ae","questionId":"ddccb303-b6ad-5835-a94b-9641d60d7101","sourceKey":"bank:SOC101:S101N2-044","payload":{"prompt":"Feminism agrees with Marxism that society involves exploitation, but holds that the most important form of exploitation is","options":["Women's exploitation by men","Poor nations' exploitation by rich nations","Workers' exploitation by capitalists","Peasants' exploitation by aristocrats"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Feminism sees exploitation in society, like Marxism, but treats the exploitation of women by men as the most important kind. The exploitation of workers by capitalists is the Marxist emphasis, which is exactly where feminism differs."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 201, $official_bank_source${"itemId":"29dade0a-8498-576c-b82b-667126185241","questionId":"b31695a3-57f3-5e83-94ba-180830cd89bf","sourceKey":"bank:SOC101:S101N2-045","payload":{"prompt":"Feminists describe contemporary societies as","options":["Patriarchal","Egalitarian","Classless","Matriarchal"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Feminists argue that contemporary societies are patriarchal, meaning they are dominated by men. Egalitarian would mean the sexes are already equal, which is the opposite of the feminist claim, since equality is what feminism aims to achieve."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 202, $official_bank_source${"itemId":"ebd0a861-b3ff-576e-94fc-3fd984c026fa","questionId":"a8c4ff14-a961-5011-b240-a476d73ac751","sourceKey":"bank:SOC101:S101N2-046","payload":{"prompt":"Which strand of feminism seeks equality for women mainly through political and legal reform?","options":["Marxist feminism","Liberal feminism","Socialist feminism","Radical feminism"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Liberal feminism works through political and legal reform within the existing society. Radical feminism goes further and seeks to reorganise society itself in order to abolish patriarchy."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 203, $official_bank_source${"itemId":"df3bbeab-a037-5435-99e7-dd33c14e4acf","questionId":"601c4ff5-5ab4-5306-b62d-c4ac7701de19","sourceKey":"bank:SOC101:S101N2-047","payload":{"prompt":"Which strand of feminism sees capitalism as the primary cause of women's oppression?","options":["Liberal feminism","Marxist feminism","Radical feminism","Socialist feminism"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Marxist feminism treats capitalism as the main cause of women's oppression. Socialist feminism is close but different, because it blames both patriarchy and capitalism together."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 204, $official_bank_source${"itemId":"9539ce7b-a1c6-5e0f-9db9-f97f8ee42143","questionId":"1bd0b8e5-7cc6-50ac-8e63-dbc7fd450eb6","sourceKey":"bank:SOC101:S101N2-048","payload":{"prompt":"Which strand of feminism calls for society to be reorganised in order to abolish patriarchy?","options":["Marxist feminism","Liberal feminism","Radical feminism","Socialist feminism"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"Radical feminism wants a reorganisation of society to abolish patriarchy altogether. Liberal feminism is more moderate, seeking change through political and legal reform rather than reorganising society."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 205, $official_bank_source${"itemId":"898e361f-2359-5318-91de-f329fd0b7d60","questionId":"8d3f107d-914b-51a4-b1ec-ae5612458798","sourceKey":"bank:SOC101:S101N2-049","payload":{"prompt":"A feminist argues that women in Nigeria are oppressed by both patriarchy and capitalism working together. This position is","options":["Socialist feminism","Marxist feminism","Liberal feminism","Radical feminism"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Socialist feminism holds that both patriarchy and capitalism oppress women. Marxist feminism is the tempting choice, but it treats capitalism alone as the primary cause of women's oppression."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 206, $official_bank_source${"itemId":"e214dba4-2552-56b2-95e2-f2385dcf50ff","questionId":"566545ca-5ea2-519b-95f6-0937a7f3ece6","sourceKey":"bank:SOC101:S101N2-050","payload":{"prompt":"The perspective which holds that meaning is constructed in interaction through the interpretation of language, gestures, appearance and manner is","options":["Symbolic interactionism","Functionalism","The conflict perspective","Marxism"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Symbolic interactionism focuses on how people create meaning as they interpret each other's words, gestures, appearance and manner. Functionalism looks instead at how the parts of society contribute to maintaining the whole system."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 207, $official_bank_source${"itemId":"7359f2d3-be32-57ac-a15d-a8e6f3517ead","questionId":"7c043d3d-1976-543e-aac8-8fc4a183abe3","sourceKey":"bank:SOC101:S101N2-051","payload":{"prompt":"Lighting a candle can signal mourning at a vigil, celebration on a birthday cake or simply light during a power cut in Lagos. A sociologist uses this to show that meaning depends on context. This reasoning reflects","options":["Liberal feminism","Marxism","Functionalism","Symbolic interactionism"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"Symbolic interactionists stress that meanings are not fixed but are created in interaction and depend on context, and the candle is a classic example. Functionalism would ask what the act contributes to maintaining society, not how its meaning changes between settings."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 208, $official_bank_source${"itemId":"e0545caa-336d-5e17-86c7-79d947d5bc38","questionId":"f264485e-18cb-5dd5-bf66-f8b5723b9ba0","sourceKey":"bank:SOC101:S101N2-052","payload":{"prompt":"Which of the following is NOT a claim of symbolic interactionism?","options":["Meaning is constructed through language, gestures, appearance and manner","Meanings are fixed and determined by the economic base","People act on the meanings they interpret","Meanings are created and changed in interaction"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Symbolic interactionism holds that meanings are not fixed; they are created and changed in interaction, and people act on what they interpret. The idea of meaning being set by the economic base borrows from Marxism and contradicts the interactionist view."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 209, $official_bank_source${"itemId":"6ca1bdf8-6cf5-5060-95cb-be1a0eea6d78","questionId":"52d435c2-10a9-5df5-80c7-1349345502fe","sourceKey":"bank:SOC101:S101N2-053","payload":{"prompt":"The concept of the looking-glass self is associated with","options":["Talcott Parsons","Robert K. Merton","Charles Horton Cooley","Karl Marx"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"Charles Horton Cooley (1864-1929) introduced the looking-glass self, the idea that self-concept grows from other people's reactions. Robert K. Merton is linked to manifest and latent functions and the self-fulfilling prophecy, not the looking-glass self."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 210, $official_bank_source${"itemId":"54799dcb-cbeb-5ca6-941f-2627beb93efb","questionId":"2d585b71-45fd-5b78-ae07-f5fb7433db72","sourceKey":"bank:SOC101:S101N2-054","payload":{"prompt":"A 100L student starts to see herself as a gifted speaker because her classmates always cheer when she presents. This development of self-concept from others' reactions illustrates","options":["False consciousness","The self-fulfilling prophecy","Value consensus","The looking-glass self"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"The looking-glass self describes how our self-concept develops from the reactions of others, as the student's does from her classmates' cheers. The self-fulfilling prophecy is about a prediction that makes itself come true, which is not what is happening here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 211, $official_bank_source${"itemId":"2791e4a8-d71f-5370-9ba8-78b8f612cb48","questionId":"bb3f04b8-68b3-5faf-a936-0cef14f9f2ad","sourceKey":"bank:SOC101:S101N2-055","payload":{"prompt":"Which of the following is NOT one of the four key aspects of structural functionalism?","options":["Equilibrium","Consensus and cooperation","Social structures","Class conflict"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"The four key aspects of structural functionalism are social structures, functions, consensus and cooperation, and equilibrium. Class conflict is central to the conflict perspective, which is why it does not belong in this list."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 212, $official_bank_source${"itemId":"2e04b224-abbf-555b-bc99-9769a019dc70","questionId":"7a328183-bcba-53ad-8540-574954eb8835","sourceKey":"bank:SOC101:S101N2-056","payload":{"prompt":"A critic argues that structural functionalism neglects change and conflict in society. This is the criticism that it","options":["Oversimplifies by neglecting agency","Justifies inequality","Exaggerates the role of patriarchy","Takes a static view of society"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"The static-view criticism says structural functionalism ignores change and conflict. The criticism of oversimplifying is different, since it refers to neglecting human agency rather than neglecting change and conflict."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 213, $official_bank_source${"itemId":"9c92ea4a-3be5-5763-a4ee-0ac7bc1b5ab8","questionId":"697915ab-9c9e-5345-9799-1d5326bf5a6a","sourceKey":"bank:SOC101:S101N2-057","payload":{"prompt":"Which of the following is NOT a criticism of structural functionalism?","options":["It oversimplifies by neglecting agency","It overemphasises conflict and change","It justifies inequality","It takes a static view of society"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Structural functionalism is criticised for a static view, for justifying inequality and for oversimplifying by neglecting agency. It cannot be accused of overemphasising conflict and change, because the static-view criticism says it neglects exactly those things."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 214, $official_bank_source${"itemId":"1cc161ef-5416-51cb-87f0-fa6da7d543c6","questionId":"80ad7308-ab84-52d1-97c3-dd232baa66db","sourceKey":"bank:SOC101:S101N2-058","payload":{"prompt":"Pattern variables such as universalism versus particularism are associated with","options":["Talcott Parsons","Emile Durkheim","Robert K. Merton","Charles Horton Cooley"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Talcott Parsons, the American structural functionalist who compared society to an organism, developed pattern variables such as universalism versus particularism. Merton is also a structural functionalist, but he is known for manifest and latent functions and strain theory, not pattern variables."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 215, $official_bank_source${"itemId":"ac96623a-794c-5351-a54c-0c7657855657","questionId":"1c928dac-5011-5820-8696-a70109416a11","sourceKey":"bank:SOC101:S101N2-059","payload":{"prompt":"Which of the following is one of Talcott Parsons' pattern variables?","options":["Mechanical versus organic solidarity","Base versus superstructure","Manifest versus latent functions","Affectivity versus affective neutrality"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"Affectivity versus affective neutrality is one of Parsons' pattern variables, alongside universalism versus particularism. Manifest versus latent functions is a tempting pair, but it comes from Robert K. Merton, not Parsons."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 216, $official_bank_source${"itemId":"bdf7ce94-e924-5083-afa0-139ac376b1e2","questionId":"ae554669-9538-5dd0-a141-0bf9f7ee63e6","sourceKey":"bank:SOC101:S101N2-060","payload":{"prompt":"In Merton's terms, the intended and recognised consequences of a social activity are its","options":["Latent functions","Manifest functions","Functional prerequisites","Dysfunctions"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Manifest functions are the consequences that are intended and recognised. Latent functions are the opposite, being unintended and unrecognised."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 217, $official_bank_source${"itemId":"f1c48210-456e-53a3-a71a-304defd7fe85","questionId":"cdcf9b4c-e6b5-502a-9d48-6ac823da6418","sourceKey":"bank:SOC101:S101N2-061","payload":{"prompt":"The main intended purpose of UNILAG is to educate students, but many students also meet future business partners and spouses there, which nobody planned. In Merton's terms, these meetings are","options":["Functional prerequisites","Dysfunctions","Manifest functions","Latent functions"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"Latent functions are unintended and unrecognised consequences, like the friendships and marriages that come out of university life. Education itself is the manifest function, because it is the intended and recognised purpose."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 218, $official_bank_source${"itemId":"b4a2c47f-92ea-55b5-b70e-5681b634a58a","questionId":"23ca206c-1821-5f32-a73c-b1aca4c21d14","sourceKey":"bank:SOC101:S101N2-062","payload":{"prompt":"In Merton's terms, the negative consequences of a social activity for society are called","options":["Dysfunctions","Latent functions","Pattern variables","Manifest functions"],"correctOption":0,"section":"Introduction to sociological theories","explanation":"Dysfunctions are the negative consequences of a social activity. Latent functions are unintended and unrecognised, but they are not by definition harmful, so they are not the same as dysfunctions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 219, $official_bank_source${"itemId":"7d38464f-a2e1-5167-a8b2-72cb46fc9063","questionId":"f80e012e-5387-5385-8591-cd931a095327","sourceKey":"bank:SOC101:S101N2-063","payload":{"prompt":"A Lagos graduate wants wealth but cannot find a job, so he turns to internet fraud to get rich. Which theory best explains this?","options":["The Marxist idea of false consciousness","Cooley's looking-glass self","Merton's strain theory of deviance","Parsons' pattern variables"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"Merton's strain theory says that when legitimate means to accepted goals are blocked, people turn to deviant means, as this graduate does. The looking-glass self explains how self-concept forms from others' reactions, not why people choose deviant routes to success."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 220, $official_bank_source${"itemId":"f7232a78-d79e-5a73-b9b3-971d24e04928","questionId":"12b443a8-75e4-5245-b95b-5d2dfb0a18bf","sourceKey":"bank:SOC101:S101N2-064","payload":{"prompt":"The term self-fulfilling prophecy was coined by","options":["Charles Horton Cooley","Robert K. Merton","Max Weber","Talcott Parsons"],"correctOption":1,"section":"Introduction to sociological theories","explanation":"Robert K. Merton coined the self-fulfilling prophecy, a prediction that makes itself come true. Cooley is a tempting choice because his looking-glass self also deals with how others' views shape us, but the self-fulfilling prophecy is Merton's."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 221, $official_bank_source${"itemId":"1de2d462-408b-53ae-b122-1809d83ef004","questionId":"5d7fab80-e30f-5e54-b685-177c97494a0a","sourceKey":"bank:SOC101:S101N2-065","payload":{"prompt":"A false rumour spreads that a bank in Lagos is about to collapse. Customers rush to withdraw their money, and the bank does collapse. This illustrates","options":["Value consensus","A manifest function","A self-fulfilling prophecy","The looking-glass self"],"correctOption":2,"section":"Introduction to sociological theories","explanation":"A self-fulfilling prophecy is a prediction that makes itself come true: the rumour caused the withdrawals that brought the bank down. A manifest function is an intended and recognised consequence, and nobody intended the bank to fail."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 222, $official_bank_source${"itemId":"1bac1a70-d948-57c2-87d3-4bae79cf09e9","questionId":"4f05cd8c-c40b-530b-8dc3-fb6305154f42","sourceKey":"bank:SOC101:S101N2-066","payload":{"prompt":"Which of these is NOT one of Durkheim's ideas that influenced structural functionalism?","options":["Division of labour","Collective conscience","Social facts","False consciousness"],"correctOption":3,"section":"Introduction to sociological theories","explanation":"Durkheim influenced structural functionalism through social facts, collective conscience, division of labour, social integration and anomie. False consciousness is a Marxist idea about workers accepting an exploitative system."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 223, $official_bank_source${"itemId":"644f98e2-a4f9-51d9-98a5-70f8de300ba5","questionId":"4eab4bae-9c11-5074-8ef1-8a218a3ed73f","sourceKey":"bank:SOC101:SOC-0004","payload":{"prompt":"To describe contact between members of a group as ephemeral means that such contact is:","options":["long lasting","not lasting","not intense","quite intense"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Ephemeral means short-lived or passing, so ephemeral contact is contact that does not last. Option A is the exact opposite, while options C and D are about how deep or intense the contact is, not how long it lasts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 224, $official_bank_source${"itemId":"30592701-6f91-563f-9a53-4a24121f9580","questionId":"399bd60f-f916-595f-8fdb-9ae466fd3c4d","sourceKey":"bank:SOC101:SOC-0005","payload":{"prompt":"One of these is NOT necessarily true of a social category","options":["Members are classified on the basis of a characteristic which they share","Members must share more than one social characteristic","Members may not be bound by any relationship","It is used for statistical grouping"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"A social category only needs one shared characteristic, such as age, sex or occupation, so members do not have to share more than one. Options A, C and D are all true of a social category: it groups people by a shared trait, its members need not interact or know each other, and it is often used for statistical purposes."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 225, $official_bank_source${"itemId":"b62539cb-8a3b-591d-b4ed-f68993caa80b","questionId":"7a3b5d57-f2fe-5cea-92ec-9cb76bb6ecc3","sourceKey":"bank:SOC101:SOC-0007","payload":{"prompt":"Which of these social institutions is charged with the replacement of the human species?","options":["religion","state","economy","family"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Reproduction, which replaces members of society from one generation to the next, is a core function of the family. Religion (A) provides beliefs and values, the state (B) maintains order and makes laws, and the economy (C) handles the production and distribution of goods and services."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 226, $official_bank_source${"itemId":"450cfdb5-824a-52cf-a9a9-50f11f8f0c8f","questionId":"87e863f0-6868-5203-a5c8-b014ce8b9bbb","sourceKey":"bank:SOC101:SOC-0008","payload":{"prompt":"The primary social institution in society is","options":["family","school","education","marriage"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"The family is regarded as the most basic social institution because it is the first place where people are born, cared for and socialized. School (B) and education (C) come later in a person's life, and marriage (D) is important but is usually seen as one of the foundations on which the family rests, not the primary institution itself."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 227, $official_bank_source${"itemId":"d2e478fd-7b3f-5847-8a0a-db47aab559d6","questionId":"9202280d-ddfb-5ce9-b2ec-e1abaf451aa6","sourceKey":"bank:SOC101:SOC-0047","payload":{"prompt":"Which of these best describes primary group relationships? i) Intimate interaction ii) Impersonal contact iii) Emotional involvement iv) Group consciousness","options":["i & iii only","i, ii & iii","ii & iv only","i, iii & iv"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Primary groups such as the family and close friends involve intimate interaction, emotional involvement and a strong sense of belonging, so i, iii and iv all apply. Any option containing ii is wrong because impersonal contact is a mark of secondary groups, and option A leaves out group consciousness."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 228, $official_bank_source${"itemId":"4f60980b-166e-5b66-802f-991bef503a27","questionId":"097116fe-7b38-5d68-b98d-30f8e5cc9df0","sourceKey":"bank:SOC101:SOC-0049","payload":{"prompt":"Which of these does not describe secondary group relationships?","options":["They are less intimate but more intense","They are highly impersonal","They are less frequent","They are less permanent"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"Secondary relationships are less intimate and also less intense, so describing them as more intense is wrong. Options B, C and D are all accurate: secondary relationships, like those with a bank teller or a clerk at a government office, are impersonal, less frequent and short-lived."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 229, $official_bank_source${"itemId":"5d2b1f0c-8fc8-5691-a886-0b3f8b85f74d","questionId":"28f86784-f9b6-5e50-8a86-a9dba875fce3","sourceKey":"bank:SOC101:SOC-0051","payload":{"prompt":"Interactions in secondary groups are means to an end, so they are said to be","options":["Ephemeral","Instrumental","Expressive","Permanent"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Instrumental relationships are used as tools to achieve a goal, such as a customer dealing with a cashier just to make a payment. Ephemeral (A) means short-lived, which is about duration rather than purpose, and expressive (C) describes relationships valued for themselves, which is typical of primary groups."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 230, $official_bank_source${"itemId":"cfb3e35c-fbd6-5e9f-969e-1b97e2060170","questionId":"2462f051-873d-5ac5-9876-8e9ea8a48b34","sourceKey":"bank:SOC101:SOC-0052","payload":{"prompt":"Which of these is not true of a bureaucracy?","options":["The principle of meritocracy is observed","Offices are arranged hierarchically","Specialization can be dispensed with","There are rules guiding office holders"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"Specialization, or a clear division of labour, is one of the core features of Weber's bureaucracy, so it cannot be dispensed with. Options A, B and D are all genuine features: appointment on merit, a hierarchy of offices and written rules guiding officials."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 231, $official_bank_source${"itemId":"e189cb6b-ca7f-5fb7-b3ff-ea7608b64e53","questionId":"2cbd59af-5b77-582f-b94c-b02301746032","sourceKey":"bank:SOC101:SOC-0053","payload":{"prompt":"Formal organizations are also known as:","options":["Serious organizations","Complex organizations","Government organizations","Business organizations"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Formal organizations are large, deliberately structured bodies with many roles and rules, which is why sociologists also call them complex organizations. Government (C) and business (D) organizations are only particular examples of formal organizations, not another name for them."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 232, $official_bank_source${"itemId":"f0cf364b-b645-54d5-9c15-188c70abec90","questionId":"e14c1e26-08dd-594e-8f89-b6ac16cf5548","sourceKey":"bank:SOC101:SOC-0086","payload":{"prompt":"________ is the way in which a society is organized","options":["Social group","Subculture","Social structure","Social role"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"Social structure is the way a society is organized into related parts, such as families, schools and government, that fit together into a whole. A social group (A) is just one unit within it, a subculture (B) is a smaller culture within a larger one, and a social role (D) is the behaviour attached to a position."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 233, $official_bank_source${"itemId":"1941ea98-f398-57df-b719-740c7b824513","questionId":"281acc52-0c52-5b1b-8969-0c1deeaea868","sourceKey":"bank:SOC101:SOC-0094","payload":{"prompt":"Social institutions are characterized by division of labour and ________","options":["conservation","territorialisation","Self preservation","specialization"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Social institutions organise tasks so that different people and groups perform different roles, which is division of labour, and each role becomes focused on particular skills and duties, which is specialization. The two go together: dividing work naturally leads to people specialising. Conservation, territorialisation and self preservation in A, B and C are not defining features of institutions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 234, $official_bank_source${"itemId":"2c8dd95d-161c-53c3-8878-6e55e0d0cb32","questionId":"2fc86287-4e7d-5776-88eb-178f585c1d02","sourceKey":"bank:SOC101:SOC-0095","payload":{"prompt":"The sociological relevance of religion is that it","options":["reinforces moral values of society","punishes witches","ensures that worshippers remain faithful to their belief","all of the above"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"Sociologically, religion matters because it provides shared beliefs and moral codes that bind people together and reinforce the values of society, a point stressed by Durkheim. Option B, punishing witches, is not a general social function of religion, and option C describes what believers do rather than what religion does for society. Because B is not a valid answer, D (all of the above) cannot be correct either."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 235, $official_bank_source${"itemId":"a01ce594-7c75-5a14-ada0-c6c3a17a730e","questionId":"5d379795-49f4-5a62-b6a7-c241f8efaf78","sourceKey":"bank:SOC101:SOC-0096","payload":{"prompt":"The role of procreation is carried out by which social institution?","options":["husband and wife","extended family","doctors and nurses","marriage and family"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Marriage and the family are the social institutions that regulate sexual relations and provide the socially approved setting for having and raising children. An institution is an established pattern of norms and roles, not a set of individuals. Options A and B name people or a family type rather than the institution, and option C, doctors and nurses, assist with childbirth but do not carry out the role of procreation."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 236, $official_bank_source${"itemId":"f17f1e43-10e0-5864-8307-df3b2c5d34a8","questionId":"5a7b09b4-dd1f-5a13-b59c-348c062f2a6a","sourceKey":"bank:SOC101:SOC-0097","payload":{"prompt":"One of these is not an institution of society","options":["Economy","Religion","Family","corruption"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Social institutions are established patterns of norms, values and roles that meet basic needs of society, such as the economy, religion and the family. Corruption is a social problem or form of deviance that breaks institutional rules, not an institution itself. Options A, B and C are all standard examples of social institutions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 237, $official_bank_source${"itemId":"45f54f5d-75a1-5192-9717-499e12624345","questionId":"99892129-8ef5-5bad-98db-e6de24689c24","sourceKey":"bank:SOC101:SOC-0196","payload":{"prompt":"The rule of inheritance called primogeniture means that","options":["Only males inherit from their parents","The last son inherits","The only son inherits","The first son inherits"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Primogeniture is the rule of inheritance under which the first-born son inherits. Option B describes the opposite rule, where the youngest son inherits, and option A is too broad because primogeniture does not give property to all males."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 238, $official_bank_source${"itemId":"058508a4-9189-57f0-a76f-c7427ff71d88","questionId":"0b2108e1-b25c-569a-a41f-6d43cb517d18","sourceKey":"bank:SOC101:SOC-0233","payload":{"prompt":"The University of Lagos has asked all students who do not know their social statuses to do a social registration. The students are being described here as","options":["An aggregate","A social category","A primary group","A secondary group"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"A social category is a set of people who share a common characteristic but do not necessarily interact or know one another, such as all students who have not done a registration. Option A, an aggregate, is people who happen to be in the same place at the same time, like passengers at a bus stop. Primary and secondary groups in C and D require real interaction among members."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 239, $official_bank_source${"itemId":"ec79a356-4cc5-50ae-b9b8-429904f9e26d","questionId":"f364aef8-3327-5a15-be84-0daa75d08564","sourceKey":"bank:SOC101:SOC-0235","payload":{"prompt":"In a formal organization, the distinction between the person and the office means that:","options":["Managers must give due recognition to primordial connections","As a result of their personal relations, managers may deal with workers according to their opinion","In spite of their personal relations, managers may deal with workers according to written rules and regulations","Managers may apply rules differently when their relations are concerned"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"In a formal organization or bureaucracy, the office is separate from the person who holds it, so managers must deal with workers according to written rules and regulations, whatever their personal relationships. Options A, B and D all let personal ties or connections decide treatment, which is exactly what this principle rules out."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 240, $official_bank_source${"itemId":"b7b41bbe-403f-53e0-a8c6-dbe3b8ab45c0","questionId":"2dbcfad6-d799-596f-bdfb-95d18da25195","sourceKey":"bank:SOC101:SOC-0252","payload":{"prompt":"________ and ________ are two types of institution","options":["Folkways and mores","Norms and customs","Belief and knowledge","Political and economic"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Social institutions include the political institution, which handles power and governance, and the economic institution, which handles production and distribution. Options A, B and C are norms, customs, beliefs and knowledge, which are parts of culture rather than types of institution."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 241, $official_bank_source${"itemId":"32bec07b-134a-5afe-a473-5e4ef0bc0138","questionId":"a0606d62-6927-558c-8aea-033492ccd8c7","sourceKey":"bank:SOC101:SOC-0281","payload":{"prompt":"Which of these is not a secondary group?","options":["A collection of people at a worship center","A collection of trainees at a computer center","A number of guys who share the same room","None of the above"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"People who share the same room interact closely and personally every day, so they form a primary group rather than a secondary one. Worshippers at a centre in A and trainees at a computer centre in B are larger, more impersonal gatherings typical of secondary groups. Since C is the answer, D does not apply."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 242, $official_bank_source${"itemId":"701dba37-f88e-5613-8921-3f8d7c35a747","questionId":"97c48220-fb7f-5f00-9da0-bbd0b4e7a81d","sourceKey":"bank:SOC101:S101N2-067","payload":{"prompt":"Families, schools and governments working together as parts of one whole are an illustration of","options":["Social structure","Cultural lag","Culture shock","Social category"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"Social structure is the way a society is organised into parts, such as families, schools and governments, that work together as a whole. A social category is just a set of people classified by a shared characteristic, with no requirement that they work together."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 243, $official_bank_source${"itemId":"f4f812fa-29aa-59e7-968b-97cb69e04c62","questionId":"c66daa0e-9a7e-5a3d-b659-88d2230dd4f0","sourceKey":"bank:SOC101:S101N2-068","payload":{"prompt":"Recurring, predictable ways in which people behave, interact and organise themselves are called","options":["Latent functions","Social categories","Social patterns","Functional prerequisites"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"Social patterns are the regular, predictable ways people behave, interact and organise themselves. A social category is different: it is a classification of people by a shared characteristic, not a regular way of behaving."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 244, $official_bank_source${"itemId":"27c558d2-3a51-5b1d-8a6b-3fb13fda4e72","questionId":"9e0055ee-e656-5765-af22-31457faa6c87","sourceKey":"bank:SOC101:S101N2-069","payload":{"prompt":"Every weekday morning, thousands of Lagos commuters queue at the same BRT stops at about the same time and follow the same boarding routine. This regular behaviour is an example of","options":["A social category","Culture shock","A social pattern","A primary group"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"A social pattern is a recurring, predictable way people behave and organise themselves, like the daily commuter routine. The commuters could be counted as a social category, but the stem describes their repeated behaviour, which is what makes it a pattern."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 245, $official_bank_source${"itemId":"c9c00a7c-77af-5530-8f4b-f644a906f0d2","questionId":"125cdf77-e853-5296-b177-1b31796dbe9f","sourceKey":"bank:SOC101:S101N2-070","payload":{"prompt":"Which of the following is NOT one of the basic questions the study of social structure seeks to answer?","options":["How does social life relate to behaviour?","What gives rise to change and development?","Where do power, authority and inequality come from?","How does the human brain store memories?"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"The study of social structure asks what gives social life, what brings about change and development, how social life relates to behaviour, and where power, authority and inequality come from. How the brain stores memories is a question about individual mental processes, which belongs to psychology rather than sociology."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 246, $official_bank_source${"itemId":"80ab94cb-73d7-51ca-8af0-2682224ae026","questionId":"2304f138-abab-58fd-85a5-624654f9230b","sourceKey":"bank:SOC101:S101N2-071","payload":{"prompt":"Which of the following is NOT a function of the family as a social institution?","options":["Law enforcement","Socialization of children","Reproduction","Emotional support"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"The family, the most basic institution, provides reproduction, the socialization of children and emotional support. Law enforcement is a function of government, alongside keeping order and providing public services."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 247, $official_bank_source${"itemId":"319ab71a-6e37-56aa-8c89-821736b5a6a6","questionId":"16c0ab90-43df-5bc7-8ae7-585f9206b6f8","sourceKey":"bank:SOC101:S101N2-072","payload":{"prompt":"The social institution whose main function is to transmit knowledge, skills and values is","options":["Media","Education","Government","Religion"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Education is the institution that passes on knowledge, skills and values from one group to another. Religion is tempting because it involves values, but it is described as a system of beliefs and values rather than an institution for transmitting skills and knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 248, $official_bank_source${"itemId":"9b426ff9-96e2-553e-95d0-aa37ead4bf58","questionId":"faa8c471-87b3-5489-a540-d1d4e524ed01","sourceKey":"bank:SOC101:S101N2-073","payload":{"prompt":"Maintaining order, providing public services and enforcing laws are the main functions of which institution?","options":["Government","Religion","Family","Education"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"Government is the institution responsible for order, public services and law enforcement. The family's functions are reproduction, socializing children and emotional support, not enforcing laws."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 249, $official_bank_source${"itemId":"80eb61c6-a84a-560b-9974-81669f186d1c","questionId":"9f95079c-6638-549d-9c5a-0cad228e5a8f","sourceKey":"bank:SOC101:S101N2-074","payload":{"prompt":"Which pairing of social institution and function is correct?","options":["Education: reproduction of the species","Government: emotional support of children","Family: law enforcement","Religion: a system of beliefs and values"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"Religion is described as a system of beliefs and values. The other pairings mix up functions: reproduction and emotional support belong to the family, and law enforcement belongs to government."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 250, $official_bank_source${"itemId":"c0fcbe38-9a46-5a5d-b5ca-9d873493b89d","questionId":"58e29060-cb56-5d92-a20a-1e5ef6471775","sourceKey":"bank:SOC101:S101N2-075","payload":{"prompt":"A department at UNILAG trains students in accounting skills and the values of honesty and hard work. The department is performing the function of which institution?","options":["Healthcare","Family","Education","Government"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"Transmitting knowledge, skills and values is the defining function of education, which is what the department is doing. The family also teaches values, but it is the institution of reproduction, child socialization and emotional support, not formal skills training."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 251, $official_bank_source${"itemId":"3c665aef-2298-5735-aee8-efe426271152","questionId":"c712a707-ffe9-5dd1-bbbe-8323ca9eefd3","sourceKey":"bank:SOC101:S101N2-076","payload":{"prompt":"Which item does not belong in a list of the major social institutions of society?","options":["Social category","Economy","Health","Religion"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"The major institutions are family, education, economy, politics, religion and health. A social category is not an institution at all; it is a statistical grouping of people who share one characteristic."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 252, $official_bank_source${"itemId":"9d2d8db8-a9cf-565d-a9e0-2a02b527cc6f","questionId":"15b21b58-6181-53e9-a61a-8ef5d737753b","sourceKey":"bank:SOC101:S101N2-077","payload":{"prompt":"Apart from family, education, government and religion, which of these is also listed among the functional mechanisms or institutions of society?","options":["Social category","Corruption","Healthcare","Culture shock"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"Healthcare and the media are listed alongside family, education, government and religion as institutions of society. Corruption is a social problem, not an institution."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 253, $official_bank_source${"itemId":"6940d0d9-d9a5-564c-9155-ce7dfa33ce6b","questionId":"a601a7eb-e93d-5e65-957a-316b0e73838c","sourceKey":"bank:SOC101:S101N2-078","payload":{"prompt":"Social institutions arise through","options":["Biological inheritance","Communal consensus","Military decree","Individual choice"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Institutions develop through communal consensus, meaning members of a society come to agree on them over time. Individual choice cannot create an institution, because institutions are shared arrangements of a whole community."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 254, $official_bank_source${"itemId":"bca1d5b6-47a9-5c90-9de6-b60534528245","questionId":"6bb951f3-ccba-54b7-98b7-96a1187f0775","sourceKey":"bank:SOC101:S101N2-079","payload":{"prompt":"Unlike a social category, a social group requires","options":["No relationship among its members","Classification for statistical purposes only","Complementary functions among its members","Only one shared characteristic"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"A social group needs complementary functions, so its members' roles fit together. Having one shared characteristic with no required relationship is what defines a social category, used mainly for statistical grouping."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 255, $official_bank_source${"itemId":"280eb077-48ac-5211-b447-323d8b0ad037","questionId":"5db004bb-2b2c-51b4-bcf9-0d8248881682","sourceKey":"bank:SOC101:S101N2-080","payload":{"prompt":"The National Bureau of Statistics counts all primary-school teachers in Lagos State, though most of them have never met one another. For sociologists, these teachers form","options":["A secondary group","A formal organisation","A social category","A primary group"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"A social category is a set of people classified by a shared characteristic, with no required relationship, and it is used for statistical grouping. A secondary group still involves some interaction among members, which these teachers do not have."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 256, $official_bank_source${"itemId":"e52c2d69-731b-5b7d-b178-eccccf5d4fe5","questionId":"e3493c12-d3b9-560d-8627-7a52d856ab58","sourceKey":"bank:SOC101:S101N2-081","payload":{"prompt":"Which statement is true of a social category?","options":["Its members must interact face to face regularly","Its members must perform complementary functions","Its members must share many characteristics","Its members share a characteristic but need not relate to one another"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"A social category groups people by a shared characteristic, and no relationship among them is required. Complementary functions are a requirement of a social group, which is exactly what separates a group from a category."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 257, $official_bank_source${"itemId":"1d4b693a-f54e-5808-a2b4-ceb4bc6483c2","questionId":"55eee8d4-0d00-58fd-b732-a7451ecb2a3b","sourceKey":"bank:SOC101:S101N2-082","payload":{"prompt":"Four childhood friends in Surulere who share intimate interaction, deep emotional involvement and a strong sense of belonging together form","options":["A primary group","A social category","A secondary group","A formal organisation"],"correctOption":0,"section":"Social structure, institutions and groups","explanation":"Primary groups are marked by intimate interaction, emotional involvement and group consciousness, all present among these friends. A secondary group is less intimate, impersonal and instrumental, which does not fit close childhood friends."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 258, $official_bank_source${"itemId":"05b0f348-45ea-5b16-8d68-6fa88f217026","questionId":"dadb16af-de01-5d08-a9e4-f9bd61ebabf7","sourceKey":"bank:SOC101:S101N2-083","payload":{"prompt":"Customers and cashiers at a bank in Lagos interact briefly and impersonally, only to complete transactions. Their relationship is typical of","options":["A primary group","A secondary group","A social category","An extended family"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Secondary groups are less intimate and impersonal, with contact that is ephemeral and instrumental, just like a quick bank transaction. A primary group would involve intimate interaction and emotional involvement, which is missing here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 259, $official_bank_source${"itemId":"65067bad-af04-52c1-83d6-b93754daa201","questionId":"ba6d9fc7-8c50-5330-97e1-bd5aaa66475c","sourceKey":"bank:SOC101:S101N2-084","payload":{"prompt":"In a bureaucracy, appointment and promotion to office are based on","options":["Inheritance from a parent","Friendship with the head of office","Merit and qualifications","The ethnic origin of the candidate"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"Bureaucracy is marked by meritocracy, so people are appointed and promoted on merit. Inheritance is the basis of positions such as primogeniture in a family, not of offices in a bureaucracy."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 260, $official_bank_source${"itemId":"ca000d51-e0de-57b0-ae27-6a6da9e839ee","questionId":"039c0cfd-b4aa-51c7-a018-daf23ccdab98","sourceKey":"bank:SOC101:S101N2-085","payload":{"prompt":"Which set lists features of a bureaucracy?","options":["Intimate interaction, emotional involvement and group consciousness","Shared characteristics with no required relationship","Meritocracy, hierarchical offices, rules, and separation of the person from the office","Inherited positions, no written rules and merging of person and office"],"correctOption":2,"section":"Social structure, institutions and groups","explanation":"A bureaucracy has meritocracy, a hierarchy of offices, rules, and a clear separation between the person and the office. Intimate interaction, emotional involvement and group consciousness describe a primary group, which is the opposite of an impersonal bureaucracy."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 261, $official_bank_source${"itemId":"6d6de0d7-8745-52ff-87d7-2a3bcaba722c","questionId":"cef5265c-80ff-5052-a2c5-1523e8c317e5","sourceKey":"bank:SOC101:S101N2-086","payload":{"prompt":"Which statement correctly contrasts primary and secondary groups?","options":["Both primary and secondary groups are short-lived and impersonal","Primary groups involve intimate, emotional ties; secondary groups are impersonal and instrumental","Primary groups have no relationships; secondary groups require complementary functions","Primary groups are impersonal and instrumental; secondary groups involve intimate, emotional ties"],"correctOption":1,"section":"Social structure, institutions and groups","explanation":"Primary groups have intimate interaction, emotional involvement and group consciousness, while secondary groups are less intimate, impersonal and instrumental. The reversed statement is the tempting trap, since it swaps the defining traits of the two kinds of group."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 262, $official_bank_source${"itemId":"267668da-c49c-552e-b43e-7c5222669927","questionId":"b9b93bce-4b14-5757-b65d-38d0c9cc75e6","sourceKey":"bank:SOC101:S101N2-087","payload":{"prompt":"Family, education, economy, politics, religion and health are best classified as","options":["Social patterns","Social categories","Primary groups","Social institutions"],"correctOption":3,"section":"Social structure, institutions and groups","explanation":"These six are the major social institutions of society. Social patterns are recurring, predictable ways of behaving, not organised structures such as the family or the economy."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 263, $official_bank_source${"itemId":"c6032b31-079d-5acc-aeb4-ef454dc8007d","questionId":"2b17424e-ab91-5d0f-baac-1051f413d093","sourceKey":"bank:SOC101:SOC-0010","payload":{"prompt":"Social stratification can be defined as:","options":["Institutionalized social inequality","Regularized pattern of social norm","Prescribed normative patterns","Discontinued social formation"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Social stratification is the ranking of people into layers in a way that makes inequality a built-in, lasting part of society, so it is institutionalized social inequality. Options B and C describe norms in general rather than inequality, and option D does not describe any recognized sociological concept."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 264, $official_bank_source${"itemId":"a577987e-9b8c-5b4b-b8e8-1a318d413dce","questionId":"e73740aa-03e3-56bb-b235-48b7b01a07b7","sourceKey":"bank:SOC101:SOC-0012","payload":{"prompt":"A system of social mobility can be:","options":["Intergenerational","Vertical","Horizontal","All of the above"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"Social mobility can be described in several ways: intergenerational (comparing a person's position with their parents'), vertical (moving up or down the class ladder) and horizontal (moving to a different position at roughly the same level). Since options A, B and C are all genuine types of mobility, D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 265, $official_bank_source${"itemId":"3359315b-aa34-5da7-b6a3-c9def02d129a","questionId":"56d7ba2b-6db1-5090-ab80-12d9629bca46","sourceKey":"bank:SOC101:SOC-0013","payload":{"prompt":"Caste system of social stratification can be found in:","options":["India","Modern industrial Britain","All the above","None of the above"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"India is the classic example of a caste system, where status is fixed at birth, marriage across caste lines is forbidden and religion supports the ranking. Modern industrial Britain in option B is a standard example of a class system, where people can move up or down. Since B is not a caste society, C (all the above) is wrong, and D is wrong because India does have caste."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 266, $official_bank_source${"itemId":"b6d96f8d-adcd-5709-81e2-aa696baee1dc","questionId":"2af227a1-7006-53a2-8b96-cc822e5fc023","sourceKey":"bank:SOC101:SOC-0014","payload":{"prompt":"These names - Pareto, Mosca and Michels - are associated with ________ theory of social stratification.","options":["Class","Elite","Conflict","Structural functional"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Vilfredo Pareto, Gaetano Mosca and Robert Michels are the classical elite theorists, who argued that every society is ruled by a small organized minority. Class theory (A) is linked with Marx, and structural functional theory (D) with Davis, Moore and Parsons; conflict theory (C) is a broad label rather than the specific name of their school."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 267, $official_bank_source${"itemId":"cf5335fb-bb6c-5d81-8d3b-44d1808e084d","questionId":"289c69db-af37-5718-bd0a-283cb1133cbe","sourceKey":"bank:SOC101:SOC-0016","payload":{"prompt":"Is there inequality in Nigeria?","options":["Yes","No","Not quite","Developing"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Yes - like every society, Nigeria has inequality, with clear differences in income, wealth, education, power and access to services between groups. Options B and C deny or downplay something that is plainly present, and D is not an answer to the question."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 268, $official_bank_source${"itemId":"e8ab46bf-ddbc-587c-b84b-494798382172","questionId":"353349d1-5574-58b6-86e6-781cd1f56b4d","sourceKey":"bank:SOC101:SOC-0019","payload":{"prompt":"The Osu Caste System is found in which of these places?","options":["India","Rwanda","Nigeria","Burundi"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"The Osu system is found among the Igbo of south-eastern Nigeria, where Osu people were historically treated as outcasts dedicated to deities. India (A) has the Hindu caste system, not Osu, while Rwanda (B) and Burundi (D) are known for Hutu-Tutsi divisions."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 269, $official_bank_source${"itemId":"46828267-f3cb-556f-a43f-162d04bc8d49","questionId":"b0928842-4b5a-5e05-824b-f35f95dff191","sourceKey":"bank:SOC101:SOC-0020","payload":{"prompt":"One characteristic of the estate type of social stratification is ________","options":["Slavery","Religion","Feudal land ownership","None of the above"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"The estate system was the stratification system of feudal Europe, where a person's position depended largely on the ownership and control of land by lords and nobles. Slavery in option A is a separate stratification system, and religion in B was important but was not what defined the estate system. Since C is correct, D is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 270, $official_bank_source${"itemId":"aba232b9-e02a-5bc6-95ba-89af19a9fba2","questionId":"cb5e5075-6a13-5d16-8bfc-39d9e247b9a4","sourceKey":"bank:SOC101:SOC-0021","payload":{"prompt":"Marxists are of the view that the world's richest nations represent ________","options":["The world's bourgeoisie","The world's proletariat","Lumpen proletariat","None of the above"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Marxists apply class analysis to the whole world, so the rich industrial nations that own and control most global wealth are seen as the world's bourgeoisie. The poor nations whose labour and resources are exploited are the world's proletariat (B), and the lumpen proletariat (C) refers to the lowest, unorganized layer within a society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 271, $official_bank_source${"itemId":"ae3d72aa-c82d-5744-8ddd-e295e0de8bbc","questionId":"876b5f7f-ab10-5ff7-8d5c-28e7e28802d8","sourceKey":"bank:SOC101:SOC-0023","payload":{"prompt":"Caste system is the most ________ form of social stratification.","options":["Rigid","Open","Simple","Legal"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"The caste system is the most rigid, or closed, system because a person's position is fixed at birth and movement between castes is almost impossible. Option B is the opposite, since open systems such as class allow mobility, and options C and D do not describe its main feature."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 272, $official_bank_source${"itemId":"15a9f200-24a8-598d-b279-61c6f6105b70","questionId":"f66de355-00e6-5796-a99e-1e8826f10bf1","sourceKey":"bank:SOC101:SOC-0024","payload":{"prompt":"The Brahmins are the ________ in the Hindu Caste System.","options":["Priests","Warriors","Herders","Outcastes"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Brahmins form the highest caste in Hinduism and are the priests and scholars. The warriors (B) are the Kshatriyas, and the outcastes (D) are the so-called untouchables who fall outside the caste ranking altogether."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 273, $official_bank_source${"itemId":"d346b33e-207a-5285-aba2-7048fd8abce6","questionId":"70e8d090-20e1-5ecc-b591-b967c614e996","sourceKey":"bank:SOC101:SOC-0043","payload":{"prompt":"Gender issues are important because","options":["Government is interested in gender","NGOs are interested in them","Equity is required for development","Only gender can lead to development"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"Gender matters because a society cannot develop fully when half its population faces unequal access to education, jobs and power, so equity is needed for development. Options A and B only point to who is interested, not why the issue matters, and D exaggerates by claiming gender alone drives development."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 274, $official_bank_source${"itemId":"d8d7adc2-5599-5d20-9155-8eac07f3706e","questionId":"d6fc0b0e-d0e1-5a98-965e-b9cfebe754d3","sourceKey":"bank:SOC101:SOC-0044","payload":{"prompt":"One of these contains elements that are purely linked with gender","options":["Expectations, values, beliefs, anatomy","Beliefs, privileges, values, constraints","Values, beliefs, hormones, culture","Culture, chromosomes, beliefs, sex"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Gender refers to the social and cultural side of being male or female, and beliefs, privileges, values and constraints are all socially created. Options A, C and D each slip in a biological element - anatomy, hormones, or chromosomes and sex - which belong to sex rather than gender."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 275, $official_bank_source${"itemId":"47acd8ab-7bdd-5565-9686-3ca0086c22c4","questionId":"15aa88ed-ff10-50f0-abcd-5041f95bc63a","sourceKey":"bank:SOC101:SOC-0054","payload":{"prompt":"Which of these is not true?","options":["Gender relations always take the form of male dominance and female subordination","Gender relations are best understood within social institutions","Gender relations vary within context","Gender relations are relations of power"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Option A is false because of the word 'always': gender relations differ across societies and situations, and they do not take one fixed form everywhere. Options B, C and D are accepted views - gender relations are shaped by institutions, change with context and involve power."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 276, $official_bank_source${"itemId":"07800cb4-f055-5a92-8417-8e8176932e4a","questionId":"0153b0c4-9563-558a-8d56-50432c9191fb","sourceKey":"bank:SOC101:SOC-0085","payload":{"prompt":"Class is another word for ________","options":["Group of people","Category","People of same economic status","None of the above"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"A social class is a group of people who share a similar economic position, such as income, wealth or occupation. Options A and B are too general, since many kinds of groups and categories exist that are not classes."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 277, $official_bank_source${"itemId":"83c212d2-a9ba-5937-9432-ed5424fef5a6","questionId":"01238703-b1e2-5901-9bc9-a2afd856c559","sourceKey":"bank:SOC101:SOC-0087","payload":{"prompt":"The movement of an individual or groups from one position of society stratification system to another is ________","options":["Social movement","Social mobility","Social interaction","None of the above"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Social mobility is the movement of individuals or groups from one position in the stratification system to another, for example moving up from the working class to the middle class. Option A, a social movement, is an organised collective effort to bring about or resist change, not a change of position. Option C, social interaction, simply means people acting towards one another."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 278, $official_bank_source${"itemId":"7db3c599-2b27-50c5-ad02-5cd61f8feff9","questionId":"b757c245-2d65-57ea-b442-4f353542d3ee","sourceKey":"bank:SOC101:SOC-0090","payload":{"prompt":"Functionalist view of social stratification is associated with ________","options":["Talcott Parsons","Wilbert Moore","Kingsley Davis","All of the above"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"The functionalist theory of stratification argues that inequality is necessary to make sure the most important positions are filled by the most capable people. Kingsley Davis and Wilbert Moore set out the best-known version of this argument, and Talcott Parsons also explained stratification in functionalist terms. Since all three are linked to the functionalist view, D is the best answer rather than any single name in A, B or C."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 279, $official_bank_source${"itemId":"307531bc-0da4-5258-891a-54c98b245d15","questionId":"7caa5cc8-a4e6-593f-8e5b-7998a465b263","sourceKey":"bank:SOC101:SOC-0092","payload":{"prompt":"The classic international poverty line, popularised by the World Bank, was expressed as about ________ a day per person","options":["One British Pound","One Euro","One US Dollar","One Canadian Dollar"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"The classic international poverty line was about one US dollar a day per person, a benchmark popularised by the World Bank and since revised upward for price changes. The US dollar is used as a common reference currency for comparing living standards across countries. The British pound, euro and Canadian dollar in A, B and D are not used for the global poverty benchmark."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 280, $official_bank_source${"itemId":"3e97f3a2-f9ce-5017-bd80-89a0064409ea","questionId":"56d65798-fb30-5085-aa48-48c7b06d53e6","sourceKey":"bank:SOC101:SOC-0104","payload":{"prompt":"The linkage between gender and sex is that","options":["Gender is determined at birth and sex is not","Social interpretations are given to gender issues","Biological attributes are formed from gender issues","Social interpretations are given to biological attributes"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"Sex refers to biological attributes such as anatomy and chromosomes, while gender is the set of social meanings, roles and expectations that society attaches to those biological differences. So the link is that social interpretations are given to biological attributes. Option A reverses the idea, since sex is what is identified at birth, and options B and C confuse which part is social and which is biological."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 281, $official_bank_source${"itemId":"df7ec8be-3b3d-583f-b0fa-14548e588284","questionId":"659ee7de-7287-569a-8658-0f3ffb860eb3","sourceKey":"bank:SOC101:SOC-0204","payload":{"prompt":"Conflict theory of social stratification says?","options":["The problem is the structure of society","The problem is the religion of the society","The problem is value system of society","All of the above"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Conflict theory sees inequality as built into the structure of society, where powerful groups control resources and keep others down. Options B and C point to religion or values, which conflict theorists treat as products of that structure rather than the root problem. Because B and C are wrong, D ('All of the above') is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 282, $official_bank_source${"itemId":"0dd36c61-3a95-5b8f-b157-593a35b65a60","questionId":"2b88f7eb-82a4-588c-8897-37ec4d6b9f1f","sourceKey":"bank:SOC101:SOC-0214","payload":{"prompt":"This set of theorists - Pareto, Mosca and Michels - have been described as","options":["Neo-Marxists","Neo-Weberians","Neo-Machiavellians","Postmodernists"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"Pareto, Mosca and Michels are the classical elite theorists, often called the neo-Machiavellians because, like Machiavelli, they saw power as always held by a ruling minority. Option A is wrong because they rejected the Marxist idea that power comes only from class and that a classless society is possible, and option B is wrong because they were not followers of Weber."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 283, $official_bank_source${"itemId":"43e1531f-9c85-5697-9c18-f8cc249e55fd","questionId":"1d340a4f-f975-5d23-b790-a3c5225a0ff4","sourceKey":"bank:SOC101:SOC-0242","payload":{"prompt":"________ studied ________ societies to conclude that the division of labour was based on biological differences.","options":["Talcott Parsons, 234","Sigmund Freud, 223","G.P. Murdock, 224","Henry George, 231"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"G.P. Murdock surveyed 224 societies and concluded that the sexual division of labour was based on biological differences between men and women, such as men's greater physical strength. Talcott Parsons in option A is known for his functionalist theory of the family, and Sigmund Freud in option B was a psychoanalyst, not the author of this cross-cultural survey."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 284, $official_bank_source${"itemId":"63e19b1e-d0ae-5c0c-80f2-5ac003a0f834","questionId":"fdce325e-7a5b-5183-9fde-896bb7937742","sourceKey":"bank:SOC101:SOC-0251","payload":{"prompt":"The fact that male child preference is not equally serious in all societies is an example of","options":["Biological determinism","The dynamism of gender","Cultural lag","Feminism"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Gender roles and preferences are shaped by culture, so they differ from one society to another and change over time, which shows the dynamism of gender. Option A, biological determinism, would predict the same pattern everywhere, so it does not fit. Cultural lag in C and feminism in D do not describe this variation."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 285, $official_bank_source${"itemId":"7651ff6c-b9f0-5cbd-a36e-2c8a7e1661e3","questionId":"ae6a4133-c1cd-52d5-83cd-3ae16cefb53c","sourceKey":"bank:SOC101:SOC-0286","payload":{"prompt":"The estate type of social stratification is defined in terms of ________ relations","options":["Legal","Economic","Religious","Status"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"The estate system, as in feudal Europe, divided people into ranks such as nobles, clergy and serfs whose rights and duties were fixed by law. That is why estates are defined in terms of legal relations. Option B fits class systems, which are based on economic position, and C fits religious divisions such as caste."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 286, $official_bank_source${"itemId":"b30799ec-4f26-5bed-b3b7-5986423bf10e","questionId":"cefff89a-494b-5b09-8e62-4e37648f89de","sourceKey":"bank:SOC101:SOC-0293","payload":{"prompt":"Which of these is not true of gender relations?","options":["It is a relation of power","It is static","It is best understood within contexts","It often shows male dominance and female subordination"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Gender relations are socially created, so they change over time and differ across societies; calling them static (B) is false. Options A, C and D are all true: gender relations involve power, they make sense only within their social and cultural context, and in many societies they show male dominance."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 287, $official_bank_source${"itemId":"86c8249e-de73-5559-98eb-069a163f4eac","questionId":"ea313d5b-be84-5db7-9089-39254bde1bc6","sourceKey":"bank:SOC101:S101N2-088","payload":{"prompt":"Societies may be stratified along several lines. Which of these is NOT one of them?","options":["Gender","Caste","Race or ethnicity","Blood group"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"Societies are stratified by class, caste, race or ethnicity and gender. Blood group is a medical characteristic that does not rank people into layers of unequal power and privilege."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 288, $official_bank_source${"itemId":"dba1dac2-13c7-596d-8d04-0df6ea257c1e","questionId":"716809fe-929b-5dfd-ab36-530fcdaae5c1","sourceKey":"bank:SOC101:S101N2-089","payload":{"prompt":"The distribution of authority, influence and control in a society is referred to as","options":["Cultural lag","Power relations","Social mobility","Social category"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Power relations describe how authority, influence and control are shared out in a society. Social mobility is different: it is the movement of individuals or groups between positions in the stratification system."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 289, $official_bank_source${"itemId":"728fe382-d34f-5117-9d86-17f3c6f6c76b","questionId":"75e0c1d6-1ad7-5808-84a7-6c16a8f76dd3","sourceKey":"bank:SOC101:S101N2-090","payload":{"prompt":"Social stratification implies","options":["The absence of inequality","Equal rewards for all positions","Equal access to power","Unequal access to power"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"Social stratification is institutionalised social inequality, so it implies that people have unequal access to power. The options suggesting equal access or equal rewards contradict the very idea of ranked layers."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 290, $official_bank_source${"itemId":"d14b755e-a2bb-5724-bfaa-c82b061f419b","questionId":"9c862cb1-a906-5e75-ad93-4a4973ef45b6","sourceKey":"bank:SOC101:S101N2-091","payload":{"prompt":"Which of the following is NOT a system of social stratification?","options":["Slavery","Caste system","Estate system","Industrial system"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"Caste, estate, slavery and class are systems of social stratification. The industrial system is a way of organising production, not a system of ranking people into strata."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 291, $official_bank_source${"itemId":"0e9a2280-201f-5e4c-8bcf-09fef96f5291","questionId":"e7e57cb0-944b-5d0b-affb-9a2f7ef5cf9d","sourceKey":"bank:SOC101:S101N2-092","payload":{"prompt":"Global inequality between nations is described as resulting from","options":["Acculturation","Globalisation","Cultural lag","Primogeniture"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Global inequality, the gap between rich and poor nations, is linked to globalisation. Cultural lag describes material culture changing faster than non-material culture, which is not an explanation of inequality between nations."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 292, $official_bank_source${"itemId":"ab4dd750-42c9-5a52-b4b2-6345534934fd","questionId":"1a8a0cc5-0801-56cc-9fd3-98b3eec95550","sourceKey":"bank:SOC101:S101N2-093","payload":{"prompt":"Anatomy, hormones and chromosomes are aspects of","options":["Gender","Sex","Social class","Ascribed role"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Anatomy, hormones and chromosomes are biological attributes, which make up sex. Gender is the set of social interpretations given to those biological attributes, such as beliefs, privileges, values and constraints."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 293, $official_bank_source${"itemId":"77d0b57d-bf1c-582c-b895-b1cfd91ad07a","questionId":"b456ded6-7c4c-5ff7-ac09-05636b4bdeed","sourceKey":"bank:SOC101:S101N2-094","payload":{"prompt":"Which of the following statements about gender relations is true?","options":["They always take the form of male dominance","They are relations of power that vary with context","They are purely biological","They are fixed and never change"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Gender relations are relations of power, they vary from one context to another, and they are best understood within institutions. The claim that they always take the form of male dominance is false, because gender relations are not static and differ across settings."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 294, $official_bank_source${"itemId":"725ed87e-f66b-5982-ae60-b46a48bff276","questionId":"a082ee8b-f25c-5065-bda6-aa96ae7a37f7","sourceKey":"bank:SOC101:S101N2-095","payload":{"prompt":"Gender relations are best understood within","options":["Social categories","Biological attributes","Institutions","Chromosomes"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"Gender relations are relations of power that are best understood within institutions such as the family, the workplace and the state. Chromosomes and biological attributes relate to sex, not to the social relations of gender."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 295, $official_bank_source${"itemId":"08285bf4-468d-5c4a-abf0-8707a70d8a5b","questionId":"bcd81692-3c3d-5085-8bc3-3691a68c4cf8","sourceKey":"bank:SOC101:S101N2-096","payload":{"prompt":"Apart from the need for equity in development, gender issues are important because they","options":["Prove that the division of labour is natural","Call attention to a lack of equity","Show that gender relations never change","Focus mainly on hormones and chromosomes"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Gender issues matter because equity is needed for development and because they draw attention to a lack of equity. Focusing on hormones and chromosomes would be about sex, not gender issues."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 296, $official_bank_source${"itemId":"5fdc189f-14f5-5c4c-85bf-788e30838493","questionId":"930ddc4f-38a0-5449-a217-9682eff37784","sourceKey":"bank:SOC101:S101N2-097","payload":{"prompt":"The rise of women's studies is linked to which body?","options":["The Economic Community of West African States","The UN Commission on the Status of Women","The International Labour Organization","The World Bank"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Women's studies is linked to the UN Commission on the Status of Women, set up in 1946. The World Bank is known for international poverty lines, not for the development of women's studies."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 297, $official_bank_source${"itemId":"a01bf923-d4c9-5994-b6bd-98d90c5e531a","questionId":"1631017b-8677-5e6b-8f64-73719d916a2e","sourceKey":"bank:SOC101:S101N2-098","payload":{"prompt":"The UN Commission on the Status of Women, to which women's studies is linked, was established in","options":["1975","1960","1985","1946"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"The UN Commission on the Status of Women dates from 1946, and women's studies is linked to its work. The later years, such as 1975, are not the founding date of this commission."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 298, $official_bank_source${"itemId":"7311dce1-8b98-5b53-9162-0bcc873a0275","questionId":"f3701cfd-1c6c-5e62-904f-6e2b84b36354","sourceKey":"bank:SOC101:S101N2-099","payload":{"prompt":"Which theory of social stratification is associated with Davis, Moore and Parsons?","options":["Conflict theory","Functionalist theory","Elite theory","Marxist theory"],"correctOption":1,"section":"Stratification, inequality, power and mobility","explanation":"Davis, Moore and Parsons are the names linked to the functionalist theory of stratification. Elite theory is tempting, but it is associated with Pareto, Mosca and Michels, the neo-Machiavellians."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 299, $official_bank_source${"itemId":"34b9e080-33e3-5746-ba28-01a6125db6c8","questionId":"f938c412-408f-56e4-8e17-7939c254580a","sourceKey":"bank:SOC101:S101N2-100","payload":{"prompt":"When an Oba dies, a member of the royal family inherits the throne by custom, and the people obey the new Oba because of long-standing tradition. In Weber's terms, this is","options":["Traditional authority","Legal-rational authority","Charismatic authority","Bureaucratic merit"],"correctOption":0,"section":"Stratification, inequality, power and mobility","explanation":"Traditional authority rests on custom, age and often gender, and it can be inherited, as the throne is here. Charismatic authority depends on a leader's personal qualities and cannot be inherited, so it does not fit a throne passed on within a royal family."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 300, $official_bank_source${"itemId":"a83ed4a6-285f-5818-8430-836eaa3cb2c7","questionId":"0a364875-59dc-5b63-848b-2682e5da238e","sourceKey":"bank:SOC101:S101N2-101","payload":{"prompt":"A youth leader in Ajegunle draws thousands of followers who obey him because of his exceptional personal qualities. Weber would call his authority","options":["Inherited authority","Traditional authority","Charismatic authority","Legal-rational authority"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"Charismatic authority is based on the personal qualities of the leader and cannot be inherited or transferred. Traditional authority would rest on custom and inheritance, not on the leader's personal appeal."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 301, $official_bank_source${"itemId":"97428f63-53c0-5d3e-a78f-1fa4221709d0","questionId":"72847c34-ed7b-51b9-9982-50632012fd6e","sourceKey":"bank:SOC101:S101N2-102","payload":{"prompt":"A bank in Lagos appoints its branch manager purely on qualifications and competence, regardless of age or gender. This reflects Weber's","options":["Charismatic authority","Traditional authority","Legal-rational authority","Caste authority"],"correctOption":2,"section":"Stratification, inequality, power and mobility","explanation":"Legal-rational authority is based on reason, with positions going to the most qualified regardless of age or gender. Traditional authority would instead rest on custom, age and often gender."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 302, $official_bank_source${"itemId":"5ae7baa6-9e4e-528a-8b13-5baa293a229d","questionId":"a5a55d3c-9004-52b1-9516-f3bc538b793d","sourceKey":"bank:SOC101:S101N2-103","payload":{"prompt":"In Marx's view, the class that owns the means of production is the","options":["Brahmins","Neo-Machiavellians","Proletariat","Bourgeoisie"],"correctOption":3,"section":"Stratification, inequality, power and mobility","explanation":"Marx called the owners of the means of production the bourgeoisie, and he saw society as marked by conflict between them and the working class. The proletariat is the working class, the group that does not own the means of production."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 303, $official_bank_source${"itemId":"9e9d671d-5aa4-5ba4-9da1-f3634043f309","questionId":"e899ce5d-359f-5218-8652-77dc289d339f","sourceKey":"bank:SOC101:SOC-0028","payload":{"prompt":"The process by which individuals learn the culture of their society is known as","options":["Initiation","Induction","Education","Socialization"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"Socialization is the lifelong process through which people learn and internalize the norms, values and ways of life of their society. Education (C) is only one part of this, carried out mainly in schools, while initiation (A) and induction (B) refer to entry into a specific group or role."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 304, $official_bank_source${"itemId":"a510af75-b59d-52b0-baa3-6d94105f7a78","questionId":"9e250254-00b9-5194-96b7-f0513745f29b","sourceKey":"bank:SOC101:SOC-0264","payload":{"prompt":"The institution basically responsible for early childhood socialization is?","options":["The school","Parents","The mother","The family"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"The family is the institution chiefly responsible for early childhood socialization, as it is where children first learn language, values and norms. Options B and C, parents and the mother, are members of the family rather than an institution. Option A, the school, comes in later in childhood."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 305, $official_bank_source${"itemId":"9b8f6eab-4914-5f3e-99eb-8ecd9e11b41b","questionId":"a059f5c3-3c3d-5d06-a1d9-d54e5e1fe002","sourceKey":"bank:SOC101:SOC-0272","payload":{"prompt":"The following is a factor in the development of personality","options":["Biological inheritance","Cultural determinants","Group experience","All of the above"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"Personality develops from biological inheritance, cultural influences and the experiences people have in groups, so all three are factors. Picking only A, B or C would leave out the other influences, which is why D is correct."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 306, $official_bank_source${"itemId":"df505875-55e0-5d15-8877-0266662656e7","questionId":"7fef08d1-b771-502a-bed5-59ebf157a45e","sourceKey":"bank:SOC101:S101N2-104","payload":{"prompt":"The process of internalising in individuals or children the moral orientations they need to navigate life is called","options":["Culture shock","Socialization","Anomie","Acculturation"],"correctOption":1,"section":"Socialization and human behaviour","explanation":"Socialization is the process through which individuals, especially children, take in the moral orientations needed to get through life. Acculturation is narrower, describing a person adjusting to the dominant culture of a new environment."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 307, $official_bank_source${"itemId":"09ebfb58-dd36-53ab-868a-ae02580b9796","questionId":"a59be26c-338a-5593-b66c-2a00d88c27fd","sourceKey":"bank:SOC101:S101N2-105","payload":{"prompt":"Which of the following shows the correct order in which socialization progresses?","options":["Family, school, larger society","Larger society, school, family","School, family, larger society","Family, larger society, school"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Socialization begins in the family, moves to the school, and then extends to the larger society of complex organisations and the wider world. Putting the school before the family is wrong because the family is responsible for the earliest, childhood stage."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 308, $official_bank_source${"itemId":"1c2af4f1-ac56-5222-9353-26e675108805","questionId":"f52983d9-1a07-52b3-bc6a-e26d79054cec","sourceKey":"bank:SOC101:S101N2-106","payload":{"prompt":"In the progression of socialization, the stage that comes immediately after the family is the","options":["Workplace","Larger society","School","Complex organisation"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"Socialization moves from the family to the school and then to the larger society. Complex organisations belong to the last stage, the larger society, so they come after the school, not straight after the family."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 309, $official_bank_source${"itemId":"d6b5006a-808b-5571-af0e-2c37a13681b3","questionId":"7898f993-ce74-54d3-8351-84d1b349df71","sourceKey":"bank:SOC101:S101N2-107","payload":{"prompt":"The final and widest stage in the progression of socialization is","options":["The family","The peer group","The school","The larger society"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"Socialization ends in the larger society, which includes complex organisations and the wider world. The family is where socialization begins, not where it ends."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 310, $official_bank_source${"itemId":"6931ffdb-6a9a-580d-9e85-724048d92212","questionId":"2ca60d70-0fd0-589c-9e44-6537d59ad1ea","sourceKey":"bank:SOC101:S101N2-108","payload":{"prompt":"A major effect of socialization on the individual is that it","options":["Moulds behaviour to fit society's expectations","Removes the need for norms and values","Causes material culture to change faster than non-material culture","Makes all individuals biologically identical"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Socialization shapes a person's behaviour so that it fits what society expects. The option about material culture changing faster describes cultural lag, which is unrelated to how individuals are socialised."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 311, $official_bank_source${"itemId":"d7606202-d521-5c05-a452-53aec33ff798","questionId":"93e1c56c-dd68-5f2b-a27a-1a0c24d2a1f7","sourceKey":"bank:SOC101:S101N2-109","payload":{"prompt":"Which of these statements about socialization is true?","options":["It continues after the family, in school and society","It takes place only inside the classroom","It is passed on biologically from parents","It ends as soon as a child leaves the family"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Socialization starts in the family, continues in the school and carries on in the larger society of complex organisations and the wider world. The claim that it takes place only in schools is wrong, because the family begins the process and the larger society continues it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 312, $official_bank_source${"itemId":"911abb88-e525-5d0b-8493-258ce289ac70","questionId":"3669b2d4-bf9a-51dd-86ba-c948f64179a1","sourceKey":"bank:SOC101:S101N2-110","payload":{"prompt":"Behaviour that is in line with the culture and conventions of a people is described as","options":["Instinctive behaviour","Animal behaviour","Deviant behaviour","Human behaviour"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"Human behaviour is behaviour that follows the culture and conventions of a people. Deviant behaviour is the opposite case, since it departs from a society's norms."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 313, $official_bank_source${"itemId":"6b2d6952-af23-5f2f-8023-0564f3c8cc31","questionId":"90a600cb-742b-51a2-8919-edb518d1bfe3","sourceKey":"bank:SOC101:S101N2-111","payload":{"prompt":"A Yoruba boy in Ibadan prostrates to greet his elders because his culture expects it. His action is best explained as","options":["Behaviour in line with the culture and conventions of his people","A sign of anomie in the family","A reaction to cultural lag in society","An inborn instinct shared by all children"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"The boy is behaving in line with the culture and conventions of his people, which is what human behaviour means. Calling it an inborn instinct is wrong, because the greeting is learned through socialization and differs from one culture to another."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 314, $official_bank_source${"itemId":"f01b0a51-5002-50be-9d0c-1843626198e9","questionId":"ba153349-d2b7-5524-a6c0-8872b31b2330","sourceKey":"bank:SOC101:S101N2-112","payload":{"prompt":"Human behaviour differs from animal behaviour mainly because human behaviour is driven by","options":["Physical strength and the need for survival","Social interaction, knowledge-seeking, interpretation and motive","Instinct alone, without any social influence","Hormones and other purely biological forces"],"correctOption":1,"section":"Socialization and human behaviour","explanation":"Human behaviour is shaped by social interaction, the search for knowledge, interpretation and motive. Instinct alone cannot be the answer, because what sets humans apart is that they act on interpretation and motive within a culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 315, $official_bank_source${"itemId":"0837d012-757c-5aed-aa32-7dca17af2f3f","questionId":"e1286e78-41fd-5255-b13c-ea0b0f63ef3b","sourceKey":"bank:SOC101:S101N2-113","payload":{"prompt":"Which statement about animal behaviour is correct?","options":["It results from internalising moral orientations","It is not necessarily driven by logic or anticipation of social response","It follows the culture and conventions of a people","It is driven mainly by interpretation and motive"],"correctOption":1,"section":"Socialization and human behaviour","explanation":"Animal behaviour is not necessarily shaped by logic or by expecting how others will respond. Interpretation and motive are what drive human behaviour, which is the key difference between the two."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 316, $official_bank_source${"itemId":"8b387975-f5ff-5755-9f6b-c4d49ec076ed","questionId":"993a1dbb-b60a-5f2a-a555-ac4ad05a41aa","sourceKey":"bank:SOC101:S101N2-114","payload":{"prompt":"Beliefs, norms, values, religion, conventions and laws are best described as","options":["Biological factors in personality","Agents of socialization","Components of culture that shape socialization","Stages of socialization"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"These six are the components of culture that shape how people are socialised. Agents of socialization are the channels that do the socialising, such as the family, school, peers and media."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 317, $official_bank_source${"itemId":"cb367dac-960d-5b27-89ef-1183c4b6c0f0","questionId":"79913490-aff5-52e6-8dd4-fdf409c25a33","sourceKey":"bank:SOC101:S101N2-115","payload":{"prompt":"Which of the following is NOT one of the components of culture that shape socialization?","options":["Beliefs","Conventions","Chromosomes","Laws"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"The components of culture that shape socialization are beliefs, norms, values, religion, conventions and laws. Chromosomes are biological attributes, which belong to sex rather than to culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 318, $official_bank_source${"itemId":"476ebc2e-7ccf-5062-83f3-14daf0cf09c7","questionId":"cfb11bf2-e144-57be-b8c3-51534138d604","sourceKey":"bank:SOC101:S101N2-116","payload":{"prompt":"Which set correctly lists four agents of socialization?","options":["Family, school, peer group and social media","Family, chromosomes, school and hormones","Id, ego, superego and peer group","Beliefs, norms, values and laws"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Family, school, peer pressure and social media are four agents of socialization, the channels through which people learn their culture. Beliefs, norms, values and laws are components of culture that shape socialization, not the agents that carry it out."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 319, $official_bank_source${"itemId":"6cc1ac9f-866c-57ea-9fb4-58dec01db698","questionId":"f9ee31b0-d24d-5824-9b3a-48737810e683","sourceKey":"bank:SOC101:S101N2-117","payload":{"prompt":"Within a few months of resuming at UNILAG, a 100L student starts dressing, talking and spending money like her hostel friends. Which agent of socialization is most clearly at work?","options":["The school curriculum","The family","The peer group","Religion"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"Her hostel friends are her peers, and the pressure to fit in with them is shaping her behaviour. The school is tempting because she is at university, but it is her friends, not her courses, that are changing her dress and spending."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 320, $official_bank_source${"itemId":"7ac21ed7-b4bd-53ad-b964-2fe90cbfd30f","questionId":"9fc973a1-41da-5be8-a0d4-f2d2fe30f1fd","sourceKey":"bank:SOC101:S101N2-118","payload":{"prompt":"A teenager in Ikeja picks up new slang, fashion trends and opinions mainly from videos he watches on Instagram and TikTok. The agent of socialization at work is","options":["Social media","The family","The school","Religion"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Social media is one of the agents of socialization, and here it is the main channel through which the teenager learns new styles and views. The family is the first agent in childhood, but the scenario shows that the online videos, not his family, are shaping him."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 321, $official_bank_source${"itemId":"b31626c1-f2e7-5961-b660-ed53b19467fd","questionId":"eaeb1474-7514-5a69-9218-e941c0b03e8b","sourceKey":"bank:SOC101:S101N2-119","payload":{"prompt":"Pupils in a Lagos primary school learn to be punctual, to queue and to obey rules set by their teachers. The agent of socialization at work is the","options":["Mass media","School","Family","Peer group"],"correctOption":1,"section":"Socialization and human behaviour","explanation":"The school is the agent of socialization that comes after the family and teaches discipline and rule-following. The peer group also influences children, but the stem shows teachers' rules, which points to the school."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 322, $official_bank_source${"itemId":"f2e46ff7-bcfb-5c7c-b10c-93b1ba448889","questionId":"48c72a27-7d8b-5a71-bf6e-72a108230e6b","sourceKey":"bank:SOC101:S101N2-120","payload":{"prompt":"A sociologist lists the channels through which a child in Lagos learns culture. Which item does NOT belong on a list of agents of socialization?","options":["The peer group","Mass media","The mosque","Chromosomes"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"Mass media, religious bodies such as the mosque, and the peer group all teach people the culture of their society, so they are agents of socialization. Chromosomes are biological, and they do not teach anyone anything about culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 323, $official_bank_source${"itemId":"50d600dc-9aa7-57d0-bf23-ac0cddda4bcd","questionId":"093180ca-c487-5f6c-9b3b-5693873e8111","sourceKey":"bank:SOC101:S101N2-121","payload":{"prompt":"Identical twins raised in the same home in Yaba develop different personalities, partly because one of them survived a serious accident as a child. This shows the influence of which factor in personality development?","options":["Group experience","Biological inheritance","Cultural determinants","Unique experience"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"A personal event that happens to only one twin is a unique experience, one of the factors in personality development. Biological inheritance cannot explain the difference, because identical twins share the same inheritance."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 324, $official_bank_source${"itemId":"ee33c53a-bf33-5b72-8bc9-583b245fb8ec","questionId":"aa12d895-7360-5d57-9837-06f32e615bca","sourceKey":"bank:SOC101:S101N2-122","payload":{"prompt":"Biological inheritance, cultural determinants, group experience and unique experience are all","options":["Factors in personality development","Agents of socialization","Stages of socialization","Components of culture"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"These four are factors that together shape the development of personality. Agents of socialization are different: they are channels such as the family, school, peers and media."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 325, $official_bank_source${"itemId":"70cb805c-f10c-5294-83b8-5b4fa2d2532a","questionId":"9ce76d24-8750-59fd-abbf-fdba4ac47deb","sourceKey":"bank:SOC101:S101N2-123","payload":{"prompt":"Sociology is called a behavioural science because it","options":["Studies only economic production","Studies only inanimate objects","Studies only the individual mind","Studies every aspect of life from birth to death"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"As a behavioural science, sociology studies every aspect of human life from birth to death, and even the collapse of societies. Studying only the individual mind would describe psychology, which focuses on individual mental processes."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 326, $official_bank_source${"itemId":"b969ddfa-2235-5e39-bcd0-324f3bf970c9","questionId":"d9e6b0ee-f23f-5efc-b75a-18fbb2e94677","sourceKey":"bank:SOC101:S101N2-124","payload":{"prompt":"The work titled \"The World System\" is associated with","options":["Immanuel Wallerstein","Claude Ake","Peter Ekeh","Mahmood Mamdani"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Immanuel Wallerstein, a 20th-century American sociologist, is associated with the world-system idea. Peter Ekeh is known for \"Colonialism and the Two Publics: A Theoretical Statement\", not for the world system."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 327, $official_bank_source${"itemId":"fede632b-76ae-5c02-9123-8dd1f38ef057","questionId":"55cf1a3c-eee8-559d-8f2b-10ec8581eb03","sourceKey":"bank:SOC101:S101N2-125","payload":{"prompt":"Immanuel Wallerstein, associated with \"The World System\", is described as a 20th-century","options":["American sociologist","Ugandan historian","Nigerian political scientist","Russian revolutionary"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Wallerstein is described as a 20th-century American sociologist. A Russian revolutionary would describe Lenin, the author of \"Imperialism: The Highest Stage of Capitalism\"."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 328, $official_bank_source${"itemId":"83f555dd-8061-5ccf-aa63-9d98624420c0","questionId":"f0dfdbe4-cc91-5559-b188-cfca6762a198","sourceKey":"bank:SOC101:S101N2-126","payload":{"prompt":"\"Imperialism: The Highest Stage of Capitalism\" was written by","options":["Immanuel Wallerstein","Claude Ake","Karl Marx","Lenin"],"correctOption":3,"section":"Socialization and human behaviour","explanation":"Lenin wrote \"Imperialism: The Highest Stage of Capitalism\". Karl Marx is the tempting choice because the title is about capitalism, but this particular work is Lenin's."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 329, $official_bank_source${"itemId":"9653eda4-34d5-5cc7-a036-a115746e7d03","questionId":"e9b4a83a-15a2-59fe-baa6-5c44e911805c","sourceKey":"bank:SOC101:S101N2-127","payload":{"prompt":"\"Colonialism and the Two Publics: A Theoretical Statement\" was written by","options":["Mahmood Mamdani","Lenin","Peter Ekeh","Claude Ake"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"Peter Ekeh is the author of \"Colonialism and the Two Publics: A Theoretical Statement\". Claude Ake is another African scholar, but his work cited here is \"Revolutionary Pressures in Africa\"."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 330, $official_bank_source${"itemId":"063da4d6-ad96-54de-88a7-8cf2a52fde29","questionId":"29d60e00-ead1-5c11-83c9-82130bc2516d","sourceKey":"bank:SOC101:S101N2-128","payload":{"prompt":"Claude Ake is the author of","options":["Citizen and Subject","Revolutionary Pressures in Africa","Colonialism and the Two Publics","Imperialism: The Highest Stage of Capitalism"],"correctOption":1,"section":"Socialization and human behaviour","explanation":"Claude Ake wrote \"Revolutionary Pressures in Africa\". \"Citizen and Subject\" is also about Africa, but it was written by Mahmood Mamdani."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 331, $official_bank_source${"itemId":"a2b15232-54f4-521d-8530-239843c35d91","questionId":"f0b27359-a178-56e5-b176-fdab2e8776c8","sourceKey":"bank:SOC101:S101N2-129","payload":{"prompt":"\"Citizen and Subject\" was written by","options":["Mahmood Mamdani","Immanuel Wallerstein","Claude Ake","Peter Ekeh"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Mahmood Mamdani is the author of \"Citizen and Subject\". Peter Ekeh wrote a different work on colonial Africa, \"Colonialism and the Two Publics: A Theoretical Statement\"."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 332, $official_bank_source${"itemId":"1e3d4954-b48d-56d4-9894-01e63c4f3295","questionId":"b1736095-db2d-5ded-9932-6c233a7a029e","sourceKey":"bank:SOC101:S101N2-130","payload":{"prompt":"Which pairing of author and work is correct?","options":["Lenin: The World System","Peter Ekeh: Revolutionary Pressures in Africa","Mahmood Mamdani: Citizen and Subject","Claude Ake: Colonialism and the Two Publics"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"Mahmood Mamdani wrote \"Citizen and Subject\". The other pairings are mixed up: \"Colonialism and the Two Publics\" is Peter Ekeh's, \"Revolutionary Pressures in Africa\" is Claude Ake's, and \"The World System\" is linked to Wallerstein."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 333, $official_bank_source${"itemId":"6257282a-3a62-58eb-94e5-0dfeef6632a6","questionId":"d4467352-7f20-56b8-bdec-bcb57da786ff","sourceKey":"bank:SOC101:S101N2-131","payload":{"prompt":"In relation to conformity, deviance is best described as","options":["Departure from norms","Adjustment to a dominant culture","The internalisation of moral orientations","Strict obedience to norms"],"correctOption":0,"section":"Socialization and human behaviour","explanation":"Deviance is departure from the norms of society, the opposite of conformity. The internalisation of moral orientations is socialization itself, which usually produces conformity rather than deviance."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 334, $official_bank_source${"itemId":"96e98a17-10f3-5a66-9899-6741d15102f3","questionId":"5cffb57d-17f9-5e8c-9ea8-d979bade094e","sourceKey":"bank:SOC101:S101N2-132","payload":{"prompt":"The sociologist who explained deviance as a response to blocked legitimate means of reaching accepted goals is","options":["Charles Horton Cooley","Robert K. Merton","Karl Marx","Talcott Parsons"],"correctOption":1,"section":"Socialization and human behaviour","explanation":"Robert K. Merton's strain theory says people turn to deviant means when legitimate means to accepted goals are blocked. Cooley is known for the looking-glass self, which explains self-concept rather than deviance."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 335, $official_bank_source${"itemId":"39c31ec9-666b-5a20-a8f1-9aca7878e759","questionId":"6d713c9e-61df-550d-85cd-89919ee0b3e0","sourceKey":"bank:SOC101:S101N2-133","payload":{"prompt":"Durkheim's term for normlessness, in which people disregard the rules of society, is","options":["Collective consciousness","Division of labour","Anomie","Solidarity"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"Anomie means normlessness: a breakdown of the social system and a disregard for rules. Solidarity is the opposite idea, referring to the bonds that hold society together."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 336, $official_bank_source${"itemId":"61f4cb47-3e6f-52a2-8c71-bcea85f14ce6","questionId":"61f1c29a-dca6-5dc0-85f6-e5dfce26c114","sourceKey":"bank:SOC101:S101N2-134","payload":{"prompt":"The family is the agent mainly responsible for which stage of socialization?","options":["University education","Old age","Early childhood","Adult working life"],"correctOption":2,"section":"Socialization and human behaviour","explanation":"The family is basically responsible for early childhood socialization, the very first stage. University education belongs to the school stage and the larger society that follow the family."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 337, $official_bank_source${"itemId":"9f833e9f-3c9e-5200-b9ad-d542643e97b3","questionId":"6dd66adc-e721-5fee-b6f3-045398f847cc","sourceKey":"bank:SOC101:SOC-0083","payload":{"prompt":"The following are ethical issues in research except","options":["Confidentiality","Honesty","Anonymity","Face to face interaction"],"correctOption":3,"section":"Research methods in sociology","explanation":"Face-to-face interaction is simply a way of collecting data, as in an interview, not an ethical principle. Confidentiality (A), honesty (B) and anonymity (C) are all central ethical concerns because they protect participants and the integrity of the research."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 338, $official_bank_source${"itemId":"3c484301-bb34-5a32-8902-d6dcfbfc33aa","questionId":"789a72b5-8993-5df6-b0ac-8f0cd6a777c7","sourceKey":"bank:SOC101:SOC-0084","payload":{"prompt":"Questionnaire is the only instrument of social survey","options":["False - interviews, observation and other instruments can also be used","True - a social survey can only use a questionnaire","True - but only when the respondents are literate","False - questionnaires cannot be used in social surveys at all"],"correctOption":0,"section":"Research methods in sociology","explanation":"The statement is false: a questionnaire is only one survey instrument, and researchers also use structured interviews, observation and other tools, so A is correct. Options B, C and D are wrong because the questionnaire is neither the only instrument nor limited to literate respondents only, and it is in fact one of the most common survey tools."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 339, $official_bank_source${"itemId":"02352b68-a399-5ad9-9799-ac78308ab3fc","questionId":"bc30e32c-8271-50c3-afe6-857ffd914051","sourceKey":"bank:SOC101:SOC-0212","payload":{"prompt":"In social research, a sample can be defined as","options":["An example of a product","All people living in a society","All research instruments","A smaller representation of a larger population"],"correctOption":3,"section":"Research methods in sociology","explanation":"In research, a sample is a smaller group selected to represent a larger population, so researchers can study the few and draw conclusions about the many. Option A is the everyday shop meaning of the word, not its research meaning. Option B, all the people living in a society, describes the whole population, and option C confuses a sample with research instruments such as questionnaires."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 340, $official_bank_source${"itemId":"663197c3-bf4c-5390-9528-365c42a8c375","questionId":"f16a64ce-bf84-5169-83ed-2ee8bc51031c","sourceKey":"bank:SOC101:SOC-0250","payload":{"prompt":"Research questionnaire can be administered in the following except","options":["Face to face interview","Telephone interview","Mailed questionnaire","Participant observation"],"correctOption":3,"section":"Research methods in sociology","explanation":"Questionnaires can be administered in a face-to-face interview, over the telephone or by post as a mailed questionnaire. Participant observation is a different research method in which the researcher joins in the group's life and watches, so it is not a way of administering a questionnaire. Options A, B and C are all standard modes of administration."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 341, $official_bank_source${"itemId":"d75e5233-a2ed-53c6-ae67-680e55b5543e","questionId":"3259508d-b37d-57e8-9834-74360e5a45db","sourceKey":"bank:SOC101:S101N3-001","payload":{"prompt":"In sociology, research is best defined as","options":["The statistical analysis of numerical data, without any other kind of inquiry","A systematic, structured process of inquiry involving planned data collection and rigorous analysis","Any gathering of information about people, whether it is planned or not","The writing of a theory about society without collecting any data"],"correctOption":1,"section":"Research methods in sociology","explanation":"Research is a systematic, structured process of inquiry in which data collection is planned and analysis is rigorous. Unplanned gathering of information is not research, because research must be systematic. Restricting research to statistics is also wrong, since qualitative, non-numerical inquiry is research too."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 342, $official_bank_source${"itemId":"18e140df-2eef-5742-a832-d050bcbff44f","questionId":"fe7becaf-b86c-5074-9926-b34c56b2e4d6","sourceKey":"bank:SOC101:S101N3-002","payload":{"prompt":"Which of the following sets gives other names used for research?","options":["Theory, hypothesis or paradigm","Sampling, coding or tabulation","Study, investigation or inquiry","Census, survey or registration"],"correctOption":2,"section":"Research methods in sociology","explanation":"Research is also called a study, an investigation or an inquiry, which is why those who carry it out are called researchers or investigators. A census or a survey is one particular way of collecting data, not another name for research as a whole. A theory or hypothesis is what research may test, not the research itself."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 343, $official_bank_source${"itemId":"a43cacf6-5744-575b-873d-32e167eeb8fa","questionId":"99c7fa3b-e12d-560d-adc7-fe57156fa63d","sourceKey":"bank:SOC101:S101N3-003","payload":{"prompt":"In a social survey, the people who provide the data are referred to as","options":["Reviewers or editors","Researchers or investigators","Sponsors or funders","Participants or respondents"],"correctOption":3,"section":"Research methods in sociology","explanation":"Participants or respondents are the people who give data in a study, for example by answering a questionnaire or an interview. Researchers or investigators are the opposite side: they conduct the study and collect the data."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 344, $official_bank_source${"itemId":"6c9c923a-5a61-5e64-a017-b3650501d69f","questionId":"e706f2b3-fa76-50fd-9c25-5451138f3f95","sourceKey":"bank:SOC101:S101N3-004","payload":{"prompt":"A UNILAG sociologist designs a study, prepares the questionnaire and collects responses from 200 students. In research terms, the sociologist is the","options":["Investigator","Unit of analysis","Respondent","Sampling frame"],"correctOption":0,"section":"Research methods in sociology","explanation":"The person who conducts a study is the researcher or investigator, so the sociologist who designs it and collects the data is the investigator. The students who answer the questionnaire are the respondents, not the sociologist."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 345, $official_bank_source${"itemId":"f807bb5f-31f9-59c7-b32e-aa53532aec94","questionId":"2ee855a5-6548-5951-abd1-78d4500dd07a","sourceKey":"bank:SOC101:S101N3-005","payload":{"prompt":"The three broad purposes of research are to","options":["Measure, compare and compete","Describe, compete and control","Understand, predict and control","Observe, record and publish"],"correctOption":2,"section":"Research methods in sociology","explanation":"Research aims to understand social phenomena, predict them and control them. Options that include competing are wrong, because competition is not a purpose of research. Observing and recording are things researchers do along the way, not the three broad purposes."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 346, $official_bank_source${"itemId":"964c2420-d6e8-5eda-a2e6-a134e12ba658","questionId":"b62e47ab-8cd5-5b14-8ac5-2d6a39732082","sourceKey":"bank:SOC101:S101N3-006","payload":{"prompt":"Which of the following is NOT one of the three broad purposes of research?","options":["Understanding","Control","Competition","Prediction"],"correctOption":2,"section":"Research methods in sociology","explanation":"The three broad purposes of research are understanding, prediction and control, so competition is the odd one out. Control may look out of place, but it is one of the three: knowledge from research helps people manage and shape social situations."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 347, $official_bank_source${"itemId":"4b93c5f2-4933-5592-9c6a-519fbf9a2a4c","questionId":"bf3a95eb-824d-5070-9c08-cef9b0426073","sourceKey":"bank:SOC101:S101N3-007","payload":{"prompt":"The Lagos State Ministry of Health commissions a study of malaria cases in Ikorodu so that it can design a better prevention programme. Which purpose of research does this mainly serve?","options":["Informing policy and practice and solving problems","Triangulating qualitative and quantitative data","Protecting the anonymity of respondents","Operationalising an abstract concept"],"correctOption":0,"section":"Research methods in sociology","explanation":"One concrete purpose of research is to inform policy and practice and solve problems, which is exactly what the ministry wants from the malaria study. Triangulation is a feature of mixed-methods research, a way of cross-checking data, not the aim the ministry has in mind."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 348, $official_bank_source${"itemId":"ae436039-e496-52cc-bad4-8b44d60da308","questionId":"1802fb18-9354-58b4-a62a-fa0c0f6c9de6","sourceKey":"bank:SOC101:S101N3-008","payload":{"prompt":"In social research, the term research design refers to","options":["The overall plan of a study","The questionnaire used to collect data","The final report of a study's findings","The statistical test used to analyse data"],"correctOption":0,"section":"Research methods in sociology","explanation":"A research design is the overall plan of a study, covering its purpose, population, selection of participants, time dimension, data collection methods and analysis techniques. The questionnaire and the statistical test are only parts of that plan, not the design itself."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 349, $official_bank_source${"itemId":"7e642ee4-4976-5b34-9233-da3bae5cea68","questionId":"8c3c859a-fe60-5ebf-b9bb-b4fc24d00680","sourceKey":"bank:SOC101:S101N3-009","payload":{"prompt":"When stating the purpose of a study in a research design, a researcher may set out to","options":["Explore, describe or explain","Publish, review or cite","Sample, stratify or weight","Survey, interview or observe"],"correctOption":0,"section":"Research methods in sociology","explanation":"The purpose of a study in a research design is to explore, describe or explain a phenomenon. Surveying, interviewing and observing are data collection methods, a separate element of the design."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 350, $official_bank_source${"itemId":"2c726e3b-7747-57fc-b4b8-ea49419466d7","questionId":"1b815fe2-5ca7-5fdc-93ee-b307bc03a8c2","sourceKey":"bank:SOC101:S101N3-010","payload":{"prompt":"Which of the following is NOT an element of a research design?","options":["Study population and unit of analysis","Choice of a journal for publishing the results","Selection of participants","Time dimension"],"correctOption":1,"section":"Research methods in sociology","explanation":"A research design covers the purpose, study population and unit of analysis, selection of participants, time dimension, data collection methods and analysis techniques. Choosing a journal happens after the study and is not part of the design. The time dimension may sound minor, but it is a recognised element of the design."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 351, $official_bank_source${"itemId":"be0e6e5f-0f2d-5179-abf0-17e5da30b9bf","questionId":"2147c3f2-d026-5296-8434-56b1b820bb6d","sourceKey":"bank:SOC101:S101N3-011","payload":{"prompt":"A researcher studying traders in Balogun market must decide whether to collect data once or to follow the same traders over five years. This decision concerns which element of research design?","options":["Ethical principle","Sampling technique","Unit of analysis","Time dimension"],"correctOption":3,"section":"Research methods in sociology","explanation":"Deciding whether a study takes place at one point in time or over a long period is a decision about its time dimension. The unit of analysis concerns who or what is being studied (here, traders), not how long the study runs."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 352, $official_bank_source${"itemId":"fbe9a236-05f4-5143-9623-72b3a91aa103","questionId":"95ec4364-948f-539c-8314-b7b616bd0819","sourceKey":"bank:SOC101:S101N3-012","payload":{"prompt":"The three types of research method in sociology are","options":["Quantitative, qualitative and mixed-methods","Probability, non-probability and mixed sampling","Exploratory, descriptive and explanatory","Surveys, interviews and observation"],"correctOption":0,"section":"Research methods in sociology","explanation":"Research methods are grouped into quantitative, qualitative and mixed-methods approaches. Surveys, interviews and observation are data collection methods, and exploring, describing and explaining are purposes of a study, not types of method."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 353, $official_bank_source${"itemId":"13ede4d8-0070-54bb-b432-0c3757aba180","questionId":"6712ee9f-f344-580a-ae65-297aec416226","sourceKey":"bank:SOC101:S101N3-013","payload":{"prompt":"Quantitative research is characterised by","options":["Combining interviews and surveys to cross-check results","Photographs and personal stories interpreted for their meaning","Numerical data and statistical analysis","Long, in-depth interviews with a few people about their experiences"],"correctOption":2,"section":"Research methods in sociology","explanation":"Quantitative research uses numerical data and statistical analysis to quantify relationships. In-depth interviews and interpreting personal stories belong to qualitative research, while combining interviews and surveys is mixed-methods research."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 354, $official_bank_source${"itemId":"f582d54f-4498-5cb4-933c-0f0785370638","questionId":"7d238e02-9a60-5978-9a97-827b15eaa1b4","sourceKey":"bank:SOC101:S101N3-014","payload":{"prompt":"Qualitative research mainly emphasises","options":["Meaning, context and depth","Large-scale statistical analysis","Counting every member of a population","Quantifying relationships between variables"],"correctOption":0,"section":"Research methods in sociology","explanation":"Qualitative research is non-numerical and interpretative, so it focuses on meaning, context and depth. Quantifying relationships and statistical analysis are the hallmarks of quantitative research."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 355, $official_bank_source${"itemId":"69c9f2a1-cd17-5be9-b625-71babfbc50e7","questionId":"39452ef6-a399-5436-8a37-488f58eb121b","sourceKey":"bank:SOC101:S101N3-015","payload":{"prompt":"Of the methods below, only one is qualitative. Which one is it?","options":["Census","Quasi-experiment","Longitudinal survey","Photovoice"],"correctOption":3,"section":"Research methods in sociology","explanation":"Photovoice is a qualitative method, along with in-depth interviews, focus groups, ethnography and observational studies. A census, a longitudinal survey and a quasi-experiment all produce numerical data, so they are quantitative methods."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 356, $official_bank_source${"itemId":"34f75939-2f4f-5798-96b9-2459212c7ba1","questionId":"5798a511-89b6-5afb-9dda-23d2ce7e3066","sourceKey":"bank:SOC101:S101N3-016","payload":{"prompt":"Which of the following is NOT a quantitative research method?","options":["Focus group discussion","Cross-sectional survey","Census","Experiment"],"correctOption":0,"section":"Research methods in sociology","explanation":"A focus group discussion is a qualitative method, because it gathers non-numerical views in depth from a small group. Census, experiments and cross-sectional surveys produce numerical data for statistical analysis, so they are quantitative."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 357, $official_bank_source${"itemId":"55d929b4-bdf8-5591-aaf6-a99f678597b4","questionId":"c71d6c70-e151-5e4c-9c5f-a7f8843fa210","sourceKey":"bank:SOC101:S101N3-017","payload":{"prompt":"Triangulation of data is a key feature of which approach to research?","options":["Informed consent","Secondary data analysis","Purposive sampling","Mixed-methods research"],"correctOption":3,"section":"Research methods in sociology","explanation":"Mixed-methods research combines quantitative and qualitative methods, so findings from one can be checked against the other. This cross-checking is called triangulation. Purposive sampling is a way of choosing participants, not a way of combining methods."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 358, $official_bank_source${"itemId":"b4d57139-3297-5dfc-92f7-52b7820fdc5e","questionId":"593167ac-c2a3-5655-a082-808d4544b5de","sourceKey":"bank:SOC101:S101N3-018","payload":{"prompt":"Cross-sectional and longitudinal designs are two kinds of","options":["Ethnographies","Sampling techniques","Focus groups","Surveys"],"correctOption":3,"section":"Research methods in sociology","explanation":"Surveys or questionnaires can be cross-sectional (data collected at one point in time) or longitudinal (data collected over a period). These are quantitative methods. Focus groups and ethnography are qualitative methods, and they are not divided in this way."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 359, $official_bank_source${"itemId":"635aae12-a9d3-5635-a928-dfa89cf2e892","questionId":"0e2f2c90-25ae-5c6c-b594-c2ab10aff219","sourceKey":"bank:SOC101:S101N3-019","payload":{"prompt":"A researcher lives among traders in a Lagos market for several months, taking part in and observing their daily life in order to understand their culture. This method is best described as","options":["Ethnography","Quasi-experiment","Census","Cross-sectional survey"],"correctOption":0,"section":"Research methods in sociology","explanation":"Ethnography is a qualitative method in which the researcher studies a group's way of life in depth, often by living among them. A census and a cross-sectional survey collect numerical data from many people at one time, not deep cultural understanding."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 360, $official_bank_source${"itemId":"292f26e5-b194-56e6-b904-bb2e5e3f23f2","questionId":"e0bfacfb-1134-53db-a219-a78c54a6facc","sourceKey":"bank:SOC101:S101N3-020","payload":{"prompt":"A 200L student writes a project by analysing crime figures already published by the Nigeria Police Force, without collecting any new data. Which data collection method is this?","options":["Observation","In-depth interview","Secondary data analysis","Focus group discussion"],"correctOption":2,"section":"Research methods in sociology","explanation":"Analysing data that someone else has already collected and published is secondary data analysis. Focus groups, interviews and observation all require the researcher to collect new data directly from people or settings."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 361, $official_bank_source${"itemId":"3705bddd-326b-5f1e-989b-582e3949ef3f","questionId":"c40bf60e-4261-5e57-bb2d-2bd539af9d23","sourceKey":"bank:SOC101:S101N3-021","payload":{"prompt":"The two broad types of sampling are","options":["Random and stratified sampling","Probability and non-probability sampling","Quantitative and qualitative sampling","Primary and secondary sampling"],"correctOption":1,"section":"Research methods in sociology","explanation":"Sampling is divided into probability sampling (simple random, stratified, systematic, multi-stage) and non-probability sampling (purposive, quota, snowball). Random and stratified sampling are both techniques within the probability type, not the two broad types."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 362, $official_bank_source${"itemId":"46751aec-7235-5250-976d-6539b72fc43a","questionId":"ca2898d6-49e1-502a-a980-8b03fba043ab","sourceKey":"bank:SOC101:S101N3-022","payload":{"prompt":"Of the sampling techniques listed below, which belongs to the probability group?","options":["Stratified sampling","Purposive sampling","Quota sampling","Snowball sampling"],"correctOption":0,"section":"Research methods in sociology","explanation":"Stratified sampling is a probability technique, together with simple random, systematic and multi-stage sampling. Purposive, quota and snowball sampling are non-probability techniques."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 363, $official_bank_source${"itemId":"1fb77c8b-b7f9-5c8c-b850-a30d31bd85f0","questionId":"e009d96b-7452-55d9-8c62-fb2be56cdf98","sourceKey":"bank:SOC101:S101N3-023","payload":{"prompt":"Which of the following is NOT a probability sampling technique?","options":["Simple random sampling","Systematic sampling","Quota sampling","Multi-stage sampling"],"correctOption":2,"section":"Research methods in sociology","explanation":"Quota sampling is a non-probability technique, like purposive and snowball sampling. Simple random, systematic and multi-stage sampling are all probability techniques. Multi-stage sampling can seem unfamiliar, but it belongs to the probability group."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 364, $official_bank_source${"itemId":"702e571d-0c9e-5033-9292-f3e8642295ec","questionId":"4fc8af7d-5d55-552a-b309-e1a8d7344742","sourceKey":"bank:SOC101:S101N3-024","payload":{"prompt":"Snowball sampling belongs to which broad type of sampling?","options":["Mixed-methods sampling","Non-probability sampling","Systematic sampling","Probability sampling"],"correctOption":1,"section":"Research methods in sociology","explanation":"Snowball sampling is a non-probability technique, together with purposive and quota sampling. Systematic sampling is itself a probability technique, not a broad type that snowball sampling falls under."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 365, $official_bank_source${"itemId":"cecd30c0-e1da-5b42-aeb5-3f55b5e2c736","questionId":"b352db3c-68b5-5a57-8ad8-0bde042d5006","sourceKey":"bank:SOC101:S101N3-025","payload":{"prompt":"Multi-stage sampling is classified as a","options":["Probability sampling technique","Non-probability sampling technique","Qualitative data collection method","Principle of research ethics"],"correctOption":0,"section":"Research methods in sociology","explanation":"Multi-stage sampling is one of the probability techniques, alongside simple random, stratified and systematic sampling. It is not a non-probability technique, because that group is made up of purposive, quota and snowball sampling."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 366, $official_bank_source${"itemId":"2e33bd35-80ae-55b0-b278-378b2cb6b882","questionId":"57f27f94-80f5-57b9-8e1a-ad07cdf16ab9","sourceKey":"bank:SOC101:S101N3-026","payload":{"prompt":"The three principles of research ethics are","options":["Objectivity, empiricism and testability","Informed consent, deception and disclosure, and avoiding harm","Understanding, prediction and control","Respect for persons, beneficence and non-maleficence, and justice"],"correctOption":3,"section":"Research methods in sociology","explanation":"The three ethical principles are respect for persons (autonomy), beneficence and non-maleficence, and justice. Informed consent, deception and disclosure, and avoiding harm are among the four major ethical considerations, which put these principles into practice; they are not the principles themselves."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 367, $official_bank_source${"itemId":"a03afbe7-cc7a-5604-a623-6b40339c6912","questionId":"96be56c3-324f-5f91-bf58-2705e386473f","sourceKey":"bank:SOC101:S101N3-027","payload":{"prompt":"In research ethics, the principle of respect for persons is also expressed as respect for","options":["Triangulation","Autonomy","Justice","Beneficence"],"correctOption":1,"section":"Research methods in sociology","explanation":"Respect for persons means respecting participants' autonomy, their right to make their own decisions, for example about whether to take part. Justice and beneficence are separate ethical principles, not other names for respect for persons."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 368, $official_bank_source${"itemId":"f14da619-e77d-5909-a8bf-1c941dd6d82f","questionId":"047400b7-7428-5528-8775-168da9e924d2","sourceKey":"bank:SOC101:S101N3-028","payload":{"prompt":"The ethical principle of beneficence and non-maleficence requires researchers to","options":["Hide the true purpose of the study from participants","Let participants decide freely whether to take part","Maximise benefit and minimise risk to participants","Combine qualitative and quantitative data"],"correctOption":2,"section":"Research methods in sociology","explanation":"Beneficence and non-maleficence means doing good and avoiding harm, that is, maximising benefit and minimising risk. Letting participants decide freely whether to take part reflects respect for persons (autonomy), a different principle."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 369, $official_bank_source${"itemId":"d397fe16-577a-5a7c-9db3-8d58567d2073","questionId":"3439b97f-3daa-55d2-92ca-9a6106caa177","sourceKey":"bank:SOC101:S101N3-029","payload":{"prompt":"Which of the following is NOT one of the four major ethical considerations in research?","options":["Informed consent","Random selection of participants","Deception and disclosure","Avoiding harm"],"correctOption":1,"section":"Research methods in sociology","explanation":"The four major ethical considerations are informed consent, deception and disclosure, confidentiality and anonymity, and avoiding harm. Random selection of participants is a sampling decision, not an ethical consideration."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 370, $official_bank_source${"itemId":"49305b13-07cf-5df9-9971-ef2e112736e6","questionId":"1f12d683-5635-54a8-8a19-78f70183a158","sourceKey":"bank:SOC101:S101N3-030","payload":{"prompt":"Before interviewing factory workers in Ikeja, a researcher explains what the study is about and tells them they may refuse to take part without any penalty. Which ethical consideration is being observed?","options":["Purposive sampling","Triangulation","Justice","Informed consent"],"correctOption":3,"section":"Research methods in sociology","explanation":"Informed consent means participants agree to take part voluntarily after being told what the study involves, which is what the researcher is securing here. Justice is one of the three broad ethical principles, but explaining the study and making participation voluntary is specifically informed consent."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 371, $official_bank_source${"itemId":"df7db274-de25-5436-a7d2-c307040165fb","questionId":"8855d42a-ce2c-55e8-9140-9da2287178c9","sourceKey":"bank:SOC101:S101N3-031","payload":{"prompt":"A researcher tells respondents in Surulere that her questionnaire is about shopping habits when it is really about their political loyalties. Which ethical consideration has she violated?","options":["Confidentiality and anonymity","Secondary data analysis","Justice","Deception and disclosure"],"correctOption":3,"section":"Research methods in sociology","explanation":"The consideration of deception and disclosure requires researchers to avoid harmful deception and reveal the true purpose of a study, which she has failed to do. Confidentiality and anonymity concern protecting respondents' identities and information, which is not the problem here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 372, $official_bank_source${"itemId":"49e39ae7-6a1c-5d18-b517-ef1fe79e3ae7","questionId":"31dedb66-fa06-5e2e-8b9b-429b9e066db1","sourceKey":"bank:SOC101:S101N3-032","payload":{"prompt":"A published research report on drug use among youths in Mushin includes the full names and home addresses of the respondents. Which ethical consideration has been breached?","options":["Triangulation","Deception and disclosure","Confidentiality and anonymity","Time dimension"],"correctOption":2,"section":"Research methods in sociology","explanation":"Naming respondents and revealing where they live breaks confidentiality and anonymity, which protect participants' identities and information. Deception and disclosure is about being honest regarding the study's true purpose, not about protecting identities."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 373, $official_bank_source${"itemId":"397f055e-cce0-5125-bfa1-ef992ea4f62e","questionId":"5f04715a-d960-5af6-bad1-8d21f7920e2e","sourceKey":"bank:SOC101:S101N3-033","payload":{"prompt":"Mixed-methods research is research that combines","options":["Cross-sectional and longitudinal surveys","Quantitative and qualitative methods","Respect for persons and justice","Probability and non-probability sampling"],"correctOption":1,"section":"Research methods in sociology","explanation":"Mixed-methods research combines quantitative and qualitative methods, so that each set of data can check the other. Using both cross-sectional and longitudinal surveys would still be purely quantitative."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 374, $official_bank_source${"itemId":"ded6997b-9a99-50fc-bea4-87948a7316a4","questionId":"e920ecc2-b4f4-5957-a534-22beefae6db4","sourceKey":"bank:SOC101:S101N3-034","payload":{"prompt":"In-depth interviews are an example of which type of research method?","options":["Qualitative","Quantitative","Mixed-methods","Probability sampling"],"correctOption":0,"section":"Research methods in sociology","explanation":"In-depth interviews collect detailed, non-numerical accounts that are interpreted for meaning and context, so they are a qualitative method. Quantitative methods such as surveys and experiments rely on numerical data and statistics."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 375, $official_bank_source${"itemId":"8890392e-9bce-53d9-a04e-1880e1ce8493","questionId":"01cd3dee-0b2f-51cd-a2c6-87266f8cc25b","sourceKey":"bank:SOC101:S101N3-035","payload":{"prompt":"A researcher studying poverty in Lagos decides that each household, rather than each individual, will be the thing studied and counted. This is a decision about the study's","options":["Ethical principles","Unit of analysis","Analysis techniques","Time dimension"],"correctOption":1,"section":"Research methods in sociology","explanation":"The unit of analysis is the person, group or thing that a study examines, here the household. It is one element of the research design. The time dimension concerns whether data are collected once or over a period, not what is being studied."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 376, $official_bank_source${"itemId":"08340e8d-cc9e-579a-9fce-a482f47d61a3","questionId":"45b30fc3-26bd-5f8e-8f50-e66d3b0a671f","sourceKey":"bank:SOC101:S101N3-036","payload":{"prompt":"In research ethics, beneficence is paired with which other idea, so that researchers must also minimise risk to participants?","options":["Anonymity","Autonomy","Justice","Non-maleficence"],"correctOption":3,"section":"Research methods in sociology","explanation":"The principle is beneficence and non-maleficence: maximising benefit (beneficence) and minimising risk or harm (non-maleficence). Justice and autonomy (respect for persons) are the other two principles, not the partner of beneficence."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 377, $official_bank_source${"itemId":"08532d22-1f67-5be1-bc09-a2c7b127d98f","questionId":"a81348a6-793f-551f-adc6-c20137e3fd46","sourceKey":"bank:SOC101:SOC-0055","payload":{"prompt":"Social theories of social change perform the following roles except:","options":["Explain what alterations there had been in society","Explain why it happened","To understand the effect and impact of the change","To overturn the sequence of events in society"],"correctOption":3,"section":"Social institutions and social change","explanation":"Theories of social change exist to describe, explain and understand change, not to reverse or overturn events in society. Options A, B and C are all genuine roles: saying what changed, why it changed, and what effects the change had."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 378, $official_bank_source${"itemId":"8491a725-626e-5137-8902-eb2f27334d19","questionId":"67f5d070-7f73-5abc-81c3-f051b4a23131","sourceKey":"bank:SOC101:SOC-0056","payload":{"prompt":"Weberian theory of social change emphasizes which of the following:","options":["Increasing independence of human beings","Increasing wickedness of human beings","Increasing wisdom of human beings","Increasing rationality of human beings"],"correctOption":3,"section":"Social institutions and social change","explanation":"Max Weber saw modern history as a process of rationalization, in which life is increasingly organized by calculation, efficiency and rules, as in bureaucracy. Options A, B and C describe changes in human character that are not the focus of his theory."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 379, $official_bank_source${"itemId":"c7f37173-c423-524a-8c2c-075f5505ae16","questionId":"bd8f622b-20cb-58c6-aacf-33610d3b014e","sourceKey":"bank:SOC101:SOC-0065","payload":{"prompt":"In the discussion of society's evolution, who amongst the following was not associated with change from a simple to a complex society?","options":["Herbert Spencer","Charles Darwin","Ibn Battuta","Emile Durkheim"],"correctOption":2,"section":"Social institutions and social change","explanation":"Ibn Battuta was a fourteenth-century traveller and explorer, not a theorist of social evolution. Spencer (A) and Durkheim (D) both described societies moving from simple to complex forms, and Darwin's (B) theory of evolution heavily influenced that way of thinking."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 380, $official_bank_source${"itemId":"3315d889-5420-5039-b71b-43fb2aa12d99","questionId":"ffb2978b-9633-5967-806c-8d0023ddb8b9","sourceKey":"bank:SOC101:SOC-0067","payload":{"prompt":"Evolutionary theories of change encompassing the idea of survival of the fittest was embedded in which of the following perspectives:","options":["Marxism","Socio-Biology","Social Darwinism","Bureaucracy"],"correctOption":2,"section":"Social institutions and social change","explanation":"Social Darwinism applied the idea of the survival of the fittest to human societies, claiming that the strongest groups and societies naturally rise to the top. Marxism (A) explains change through class conflict, and bureaucracy (D) is a form of organization, not a theory of change."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 381, $official_bank_source${"itemId":"00bf8172-aef7-5177-a550-47b60eb5e51e","questionId":"974f0d1b-926d-5ec5-9913-7bb972e07e01","sourceKey":"bank:SOC101:SOC-0070","payload":{"prompt":"The major reasons for studying social change include which of the following:","options":["Self knowledge","To figure out what is going on around us in the world","To figure out how to intervene in our lives","All of the above"],"correctOption":3,"section":"Social institutions and social change","explanation":"Studying social change helps us understand ourselves, make sense of what is happening in the world around us, and decide how to respond to or shape those changes. Since A, B and C are all valid reasons, choosing just one of them would be incomplete."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 382, $official_bank_source${"itemId":"3cd6b802-a591-5ad6-9093-167261ada5e5","questionId":"2f006186-155f-5e47-9b93-79748888f3b8","sourceKey":"bank:SOC101:SOC-0071","payload":{"prompt":"The theory of evolution by natural selection, which inspired the idea of \"survival of the fittest\", was developed by:","options":["John Locke","Plato","Thomas Hobbes","Charles Darwin"],"correctOption":3,"section":"Social institutions and social change","explanation":"Charles Darwin developed the theory of evolution by natural selection, and the survival-of-the-fittest idea grew out of it when Herbert Spencer applied it to society. Locke (A) and Hobbes (C) wrote about the state of nature and the social contract, and Plato (B) wrote about the ideal state."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 383, $official_bank_source${"itemId":"92972e9c-3177-551f-bb4e-274b57578d78","questionId":"e73f84c1-d461-5cca-b6d6-95b862b00a9a","sourceKey":"bank:SOC101:SOC-0224","payload":{"prompt":"HIV/AIDS can be transmitted through the following means except","options":["Sexual intercourse","Sharing sharp objects","Sharing the same toilet","Mother-to-child transmission"],"correctOption":2,"section":"Social institutions and social change","explanation":"HIV is not spread through casual contact such as sharing the same toilet, because the virus does not survive or pass on that way. It is transmitted through sexual intercourse (option A), sharing sharp objects contaminated with blood (option B) and from mother to child during pregnancy, birth or breastfeeding (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 384, $official_bank_source${"itemId":"c0fdfc28-4200-5193-af2e-e1f33abd2245","questionId":"b567816c-01bd-5e34-8556-e1d40a33ce8a","sourceKey":"bank:SOC101:SOC-0234","payload":{"prompt":"Morbidity rate refers to the number of deaths that occur within a given society.","options":["True","False","Not really","None of the above"],"correctOption":1,"section":"Social institutions and social change","explanation":"False - morbidity rate refers to the level of illness or disease in a population. The number of deaths in a society is measured by the mortality rate. Option C, not really, is vague, and the statement is simply false because it mixes up the two terms."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 385, $official_bank_source${"itemId":"fb394ac0-8f5d-5982-acbd-9ba2af9bf444","questionId":"9885dd3c-e194-525d-a8eb-1fe5dea89325","sourceKey":"bank:SOC101:SOC-0266","payload":{"prompt":"The term fertility refers to the actual number of births that occur in a population","options":["True","False","None of the above","All of the above"],"correctOption":0,"section":"Social institutions and social change","explanation":"Fertility is the actual number of births that occur in a population. It is different from fecundity, which is the biological ability to have children. So the statement is true, and options C and D do not apply."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 386, $official_bank_source${"itemId":"17629c88-6a91-53d9-83dc-495536cad807","questionId":"e4ace3b6-46bf-5d80-aa7c-57f2711bacc0","sourceKey":"bank:SOC101:SOC-0271","payload":{"prompt":"Vital registration system is the","options":["Continuous recording of marriage and divorce","Method of data processing","Method in which information on births, deaths, marriages and divorces is kept in a register at the office of the registrar","None of the above"],"correctOption":2,"section":"Social institutions and social change","explanation":"Vital registration is the system in which births, deaths, marriages and divorces are recorded in a register kept at the registrar's office. Option A is too narrow because it leaves out births and deaths. Option B describes data processing, which is not what vital registration is."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 387, $official_bank_source${"itemId":"cf7ed126-c8c3-5b8e-a1b6-d90699fc5791","questionId":"2496186e-8a8f-5447-9693-df27b1d78164","sourceKey":"bank:SOC101:SOC-0278","payload":{"prompt":"Social change in a negative sense is seen to be synonymous with which of the following?","options":["Progress","Retrogression","Utopia","Globalization"],"correctOption":1,"section":"Social institutions and social change","explanation":"Social change can be positive or negative. When it is negative, society moves backwards or gets worse, which is called retrogression (B). Option A, progress, is the positive sense of social change, and Option C, utopia, means an imagined perfect society. Option D, globalization, is one kind of change, not a word for negative change."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 388, $official_bank_source${"itemId":"1934174d-4f2d-5d8a-be17-fa28729c02c3","questionId":"2a98cd6d-1830-5bb7-8092-f3ee5d073398","sourceKey":"bank:SOC101:S101N3-038","payload":{"prompt":"The phrase \"survival of the fittest\" was coined by","options":["Charles Darwin","Auguste Comte","Max Weber","Herbert Spencer"],"correctOption":3,"section":"Social institutions and social change","explanation":"Herbert Spencer coined \"survival of the fittest\", and the idea was later applied to society as Social Darwinism. Charles Darwin is the tempting choice, but his own contribution was the theory of evolution by natural selection, not the phrase."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 389, $official_bank_source${"itemId":"d4086be1-400a-5631-8c11-5144d7cfa802","questionId":"7081fc46-ef20-55b2-af4a-af0f792ddca7","sourceKey":"bank:SOC101:S101N3-039","payload":{"prompt":"Herbert Spencer, Charles Darwin and Emile Durkheim are all associated with the idea that societies","options":["Remain static and unchanging","Move from complex to simple forms","Are created by a social contract","Evolve from simple to complex forms"],"correctOption":3,"section":"Social institutions and social change","explanation":"Spencer, Darwin and Durkheim are linked with evolutionary thinking, in which societies develop from simple to complex forms. The view that societies remain static is the opposite of evolution."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 390, $official_bank_source${"itemId":"95628d1d-4016-5d6d-beea-bdc3b5574e5d","questionId":"ff2c3211-0664-53e8-9d15-3ee0851901bb","sourceKey":"bank:SOC101:S101N3-040","payload":{"prompt":"Which theorist's theory of social change emphasises the increasing rationality of human beings?","options":["Charles Darwin","Karl Marx","Max Weber","Herbert Spencer"],"correctOption":2,"section":"Social institutions and social change","explanation":"Weber's theory of change stresses the growing rationality of human beings, with life increasingly organised by reason, rules and calculation. Karl Marx explained change through class conflict and stages of economic development, not rationality."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 391, $official_bank_source${"itemId":"4ebf7023-1f60-5f65-8f7c-622bae26d406","questionId":"68f8abf7-25f0-59fa-b61f-0fa497958138","sourceKey":"bank:SOC101:S101N3-041","payload":{"prompt":"Which of the following is NOT a reason for studying social change?","options":["To stop all change from happening in society","To know how to intervene in our own lives","To understand what is going on in the world around us","Self-knowledge"],"correctOption":0,"section":"Social institutions and social change","explanation":"People study social change for self-knowledge, to understand the world around them and to know how to intervene in their lives. Stopping all change is not a reason for studying it, because society cannot be kept static."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 392, $official_bank_source${"itemId":"61868b77-ddea-531c-81aa-ead89daae994","questionId":"3576f448-b160-5247-b32d-db612d7c9d1a","sourceKey":"bank:SOC101:S101N3-042","payload":{"prompt":"In population studies, the number of deaths occurring in a population is referred to as","options":["Morbidity","Fertility","Mortality","Migration"],"correctOption":2,"section":"Social institutions and social change","explanation":"Mortality refers to deaths in a population. Morbidity is often confused with it, but morbidity does not mean deaths. Fertility refers to the actual number of births."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 393, $official_bank_source${"itemId":"3ab048e6-41d1-528a-bea2-e36dc408f828","questionId":"fcb3fb0d-2163-5a98-af05-113500cadbe7","sourceKey":"bank:SOC101:S101N3-043","payload":{"prompt":"The actual number of births recorded in Lagos State in a given year is a measure of the state's","options":["Migration","Mortality","Fertility","Morbidity"],"correctOption":2,"section":"Social institutions and social change","explanation":"Fertility is the actual number of births that occur in a population, so a count of births measures fertility. Mortality refers to deaths, not births."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 394, $official_bank_source${"itemId":"73ca936f-0b1b-5d2c-8499-d2a6775db526","questionId":"8debe1b5-2e39-51ea-a404-88d3a899b5e9","sourceKey":"bank:SOC101:S101N3-044","payload":{"prompt":"Which pair of the following are standard means of collecting demographic data?","options":["Folkways and mores","Primogeniture and inheritance","Ethnoscape and mediascape","Census and vital registration"],"correctOption":3,"section":"Social institutions and social change","explanation":"Demographic data come mainly from the census and from vital registration. Folkways and mores are types of norms, and ethnoscape and mediascape are terms from the study of globalisation."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 395, $official_bank_source${"itemId":"453e8f98-a19f-5dfa-b205-837895be74f1","questionId":"20896331-b191-55de-9d55-718602c5d6b2","sourceKey":"bank:SOC101:S101N3-045","payload":{"prompt":"A couple registers their marriage at a marriage registry in Ikoyi, and the record is kept in the registrar's office. This record forms part of the","options":["Secondary group","Sampling frame","Vital registration system","National census"],"correctOption":2,"section":"Social institutions and social change","explanation":"Vital registration is the recording of births, deaths, marriages and divorces in a registrar's office, so a registered marriage is part of it. A census is a separate exercise that counts the whole population at a particular time, rather than recording events as they happen."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 396, $official_bank_source${"itemId":"e8f2758d-65cc-5f9f-a4d3-029c3e6925e6","questionId":"58821626-c3a8-5151-8f4d-558afedd2196","sourceKey":"bank:SOC101:S101N3-046","payload":{"prompt":"Which social institution is the most basic, responsible for reproduction, the socialization of children and emotional support?","options":["Religion","The family","Government","Education"],"correctOption":1,"section":"Social institutions and social change","explanation":"The family is the most basic institution, responsible for reproduction, the early socialization of children and emotional support for its members. Education also socializes, but its main function is transmitting knowledge, skills and values, and it does not handle reproduction."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 397, $official_bank_source${"itemId":"84f77ed2-a324-5f51-88a3-e177f88d4ee0","questionId":"de663d7b-78a1-50c9-9d0a-906e3e81530f","sourceKey":"bank:SOC101:S101N3-047","payload":{"prompt":"The social institution whose main function is to transmit knowledge, skills and values is","options":["Education","Health","Government","The economy"],"correctOption":0,"section":"Social institutions and social change","explanation":"Education is the institution that transmits knowledge, skills and values from one generation to the next. Government's functions are maintaining order, providing public services and enforcing laws."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 398, $official_bank_source${"itemId":"54a63372-7d20-5b1a-85ed-3ef7c41feb27","questionId":"b61ef9f8-ca72-5f15-83c0-91bc0de8932c","sourceKey":"bank:SOC101:S101N3-048","payload":{"prompt":"Officials of a Lagos State traffic agency arrest motorists who drive against traffic, and the state also builds roads for the public. These activities show the functions of which institution?","options":["Government","Education","The family","Religion"],"correctOption":0,"section":"Social institutions and social change","explanation":"Government maintains order, provides public services and enforces laws, all shown by arresting traffic offenders and building public roads. Religion also shapes conduct, but through a system of beliefs and values rather than state law enforcement."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 399, $official_bank_source${"itemId":"3c5c3802-047e-51db-b402-c117c3bf294e","questionId":"b3d6f346-285f-5008-912e-6b568551a65b","sourceKey":"bank:SOC101:S101N3-049","payload":{"prompt":"As a social institution, religion is best described as","options":["A system for producing and distributing goods","A system of beliefs and values","A system for transmitting skills for employment","A system for enforcing laws and maintaining order"],"correctOption":1,"section":"Social institutions and social change","explanation":"Religion is a system of beliefs and values shared by its members. Enforcing laws and maintaining order is the function of government, and producing and distributing goods belongs to the economy."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 400, $official_bank_source${"itemId":"dc759c9d-652e-531c-825d-2a8b7b2859f1","questionId":"a265b214-5e41-5193-9ea6-b54b96cd3c35","sourceKey":"bank:SOC101:S101N3-050","payload":{"prompt":"Social institutions generally come into being through","options":["Communal consensus","The decree of a single ruler","Accidental events","Biological inheritance"],"correctOption":0,"section":"Social institutions and social change","explanation":"Institutions arise through communal consensus: members of society come to agree on established ways of meeting their needs. They are not biologically inherited, because they are social arrangements that people create and pass on."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 401, $official_bank_source${"itemId":"d11b9c20-d7f2-5185-be76-72ab90f8c436","questionId":"20fbd180-c00d-59c1-bca6-05a9416475ae","sourceKey":"bank:SOC101:S101N3-051","payload":{"prompt":"Family, education, economy, politics and religion are major social institutions. Which of the following completes the list?","options":["Social category","Secondary group","Health","Peer group"],"correctOption":2,"section":"Social institutions and social change","explanation":"The six major institutions are family, education, economy, politics, religion and health. A peer group, a secondary group or a social category is a collection of people, not an established institution that meets a basic need of society."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 402, $official_bank_source${"itemId":"e560457d-1eb1-58bb-bdb1-92ba690d28a6","questionId":"22047cb4-9b65-5052-a92f-8b5d54de4d93","sourceKey":"bank:SOC101:S101N3-052","payload":{"prompt":"Mosques, churches and traditional shrines in Lagos all belong to which social institution?","options":["Government","Religion","The economy","Education"],"correctOption":1,"section":"Social institutions and social change","explanation":"Mosques, churches and shrines are places where people practise shared beliefs and values, so they belong to religion as an institution. Government is concerned with order, public services and law enforcement, not worship."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 403, $official_bank_source${"itemId":"3285d591-e05f-578a-b14e-08a2eb60b611","questionId":"dffe1ae1-95f2-5a35-905e-b8e2708b6e8b","sourceKey":"bank:SOC101:S101N3-053","payload":{"prompt":"The traders of Balogun market, the banks on Broad Street and the factories in Ikeja all belong to which social institution?","options":["The family","The economy","Religion","Health"],"correctOption":1,"section":"Social institutions and social change","explanation":"Markets, banks and factories are where goods and services are produced, exchanged and paid for, so they belong to the economy, the institution of economy and work. The family is the basic institution for reproduction and child-rearing, not production for the market."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 404, $official_bank_source${"itemId":"fbf16841-7c2f-5eee-9ba7-c8984538cb5a","questionId":"28a04bf4-208f-560e-9ad8-df624f020013","sourceKey":"bank:SOC101:S101N3-054","payload":{"prompt":"Hospitals, clinics and primary healthcare centres in Lagos belong to which social institution?","options":["Education","Health","Government","Religion"],"correctOption":1,"section":"Social institutions and social change","explanation":"Hospitals and clinics form part of the health institution, concerned with health and medicine. Government may fund some of them, but the institution whose main concern is caring for the sick is health."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 405, $official_bank_source${"itemId":"8ee1cbbb-09a0-5292-8213-7ee62c34d81f","questionId":"44605940-9d9e-52fc-bc06-4bb04f455e04","sourceKey":"bank:SOC101:SOC-0057","payload":{"prompt":"Which school of thought described globalization as a new and complete process?","options":["The Skeptics","The Hyperglobalists","The Transformationalists","All of the above"],"correctOption":1,"section":"Globalization and its impacts","explanation":"Hyperglobalists argue that globalization is a genuinely new era in which national borders and states are losing their importance. The Skeptics (A) reject this as exaggerated, and the Transformationalists (C) see globalization as real but uneven and still unfolding, so D cannot be right either."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 406, $official_bank_source${"itemId":"8b324a94-e986-520d-b0b3-1c81dd18e9b9","questionId":"481f7c61-50bb-5fbe-9e39-887dfbb88bf1","sourceKey":"bank:SOC101:SOC-0058","payload":{"prompt":"Globalization in its characteristics includes the following except","options":["Interconnectedness","Global consciousness","Intensification","Traditionalism"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Globalization is marked by growing interconnectedness, intensified flows of goods, people and ideas, and a sense of the world as one place. Traditionalism, holding on to old local ways, runs against these trends, so it is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 407, $official_bank_source${"itemId":"9e504d82-824b-55ab-8095-7f4db29a1437","questionId":"ff05f00d-c9cb-56f7-ae8d-51f141260dfd","sourceKey":"bank:SOC101:SOC-0059","payload":{"prompt":"The definition of globalization as \"a process in which the constraints of geography on economic, political, social and cultural arrangements recede\" was given by which of the following?","options":["Friedman","Walter","Waters","Kant"],"correctOption":2,"section":"Globalization and its impacts","explanation":"This definition comes from the sociologist Malcolm Waters, who described globalization as geography mattering less and less for how economic, political, social and cultural life is arranged. Walter (B) is a look-alike name meant to confuse, Friedman (A) is known for popular writing on globalization, and Kant (D) was an eighteenth-century philosopher."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 408, $official_bank_source${"itemId":"50a97f90-eb05-5ff7-8801-e7248de42fde","questionId":"6df95fa2-5113-5499-9d79-8bfe2ccd07f4","sourceKey":"bank:SOC101:SOC-0061","payload":{"prompt":"The three dimensions of the World System include the following except:","options":["The Epicenter","The Core","The Semi-periphery","The Periphery"],"correctOption":0,"section":"Globalization and its impacts","explanation":"World-systems theory divides the world into the core (rich industrial nations), the semi-periphery (middle-level nations) and the periphery (poor nations supplying raw materials and cheap labour). The epicenter is not one of these zones."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 409, $official_bank_source${"itemId":"7385ca00-a284-5489-92bc-848447135bf3","questionId":"7185fb23-0810-5d5b-9a18-8524075804c4","sourceKey":"bank:SOC101:SOC-0062","payload":{"prompt":"The World System as a theory of globalization was developed by which of the following?","options":["Immanuel Wallerstein","Immanuel Kant","Frantz Fanon","Max Weber"],"correctOption":0,"section":"Globalization and its impacts","explanation":"Immanuel Wallerstein developed world-systems theory, which explains global inequality through the relationship between core, semi-periphery and periphery nations. Kant (B) shares the first name but was a philosopher, and Fanon (C) is known for writing on colonialism."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 410, $official_bank_source${"itemId":"9cc4b719-52db-51ae-9ed9-d616c7c56a13","questionId":"f4c39651-b45a-5e1a-a17d-61685ff70ea3","sourceKey":"bank:SOC101:SOC-0063","payload":{"prompt":"The Global Culture theory includes the following except","options":["Ethnoscapes","Mediascapes","Technoscapes","Indiascapes"],"correctOption":3,"section":"Globalization and its impacts","explanation":"In Arjun Appadurai's global culture theory, cultural flows are described as ethnoscapes, mediascapes, technoscapes, financescapes and ideoscapes. There is no 'Indiascape', which is the invented option here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 411, $official_bank_source${"itemId":"fd28da53-fcf5-562a-91cf-0e3c25d883bb","questionId":"96f0d1cf-81df-5daf-98ee-3ecd1f7b1059","sourceKey":"bank:SOC101:SOC-0064","payload":{"prompt":"Which of the following best describes the meaning of Ethnoscape?","options":["Flow of ideas","Flow of Indians","Flow of people","Flow of images"],"correctOption":2,"section":"Globalization and its impacts","explanation":"An ethnoscape is the movement of people across the world - migrants, tourists, refugees and workers. The flow of ideas (A) is an ideoscape and the flow of images (D) is a mediascape, while B misreads 'ethno' as referring to one nationality."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 412, $official_bank_source${"itemId":"3049edb7-82cd-521f-bfde-4399fa719000","questionId":"500078a7-9283-513f-84e0-5f6b10a8e3fb","sourceKey":"bank:SOC101:SOC-0066","payload":{"prompt":"Which school of thought debunked the idea of globalization as a new and complete process?","options":["The Skeptics","The Hyperglobalists","The Transformationalists","All of the above"],"correctOption":0,"section":"Globalization and its impacts","explanation":"The Skeptics argue that globalization is not new, pointing out that world trade and investment were already high in earlier periods, and that nation-states remain powerful. The Hyperglobalists (B) are the ones who claim it is a new era, so they could not have debunked the idea."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 413, $official_bank_source${"itemId":"c12130ca-b864-5976-872f-d4e3d3566884","questionId":"402f8b0a-21f4-5c04-9fe7-d07865d85d7c","sourceKey":"bank:SOC101:SOC-0072","payload":{"prompt":"Finanscape in cultural globalization means:","options":["Flow of money","Flow of ideas","Flow of images","Flow of people"],"correctOption":0,"section":"Globalization and its impacts","explanation":"A financescape is the fast global movement of money and capital through currency markets, stock exchanges and investments. The flow of ideas (B) is an ideoscape, the flow of images (C) is a mediascape, and the flow of people (D) is an ethnoscape."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 414, $official_bank_source${"itemId":"deac488f-c9ee-5e18-b4f2-e8ee268b423c","questionId":"5d056dd7-02b2-5c28-8b08-e944eedffb05","sourceKey":"bank:SOC101:SOC-0073","payload":{"prompt":"Technoscape as an issue in globalization connotes which of the following:","options":["Flow of techniques","Flow of images","Flow of technology","Flow of energy"],"correctOption":2,"section":"Globalization and its impacts","explanation":"A technoscape is the global spread of technology, both mechanical and informational, across borders. Option A sounds close but 'techniques' is not the term used, and the flow of images (B) is a mediascape."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 415, $official_bank_source${"itemId":"5a7c01fb-20c3-5ec8-aee1-7eaa3dcc0bb6","questionId":"82327458-9edf-5fd1-a860-69e6a4f47c6b","sourceKey":"bank:SOC101:SOC-0202","payload":{"prompt":"An aspect of globalization whereby the Nation-state is seen as losing much of its influence was a view propounded by which school of thought:","options":["The Functionalists","The Structuralists","The Modernization theorists","The Hyperglobalists"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Hyperglobalists argue that globalization is creating a borderless world in which the nation-state is losing much of its power to global markets and organisations. Options A and B are general sociological perspectives, not schools of thought about globalization, and option C, modernization theory, is about how societies develop rather than the decline of the nation-state."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 416, $official_bank_source${"itemId":"513ceb69-5a51-58ad-9600-286ba13401f5","questionId":"26e5b64d-a657-55b5-8fb6-c2892c8a6c54","sourceKey":"bank:SOC101:SOC-0213","payload":{"prompt":"Major theoretical considerations in the treatment of globalization include the following except","options":["Functionalist Theory","World Systems Theory","Global Capitalist Theory","Global Society Theory"],"correctOption":0,"section":"Globalization and its impacts","explanation":"The major theories used to explain globalization include world-systems theory, global capitalism theory and global society theory. Functionalist theory is a general perspective on society, not one of the specific globalization theories, so A is the exception. Options B, C and D are all recognised globalization theories."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 417, $official_bank_source${"itemId":"ed6485b9-bc14-51f7-aadd-1ddd85d0cf29","questionId":"c741a0e1-7192-5f44-889f-dabda7d0052d","sourceKey":"bank:SOC101:SOC-0236","payload":{"prompt":"Glocalization, a theme in globalization, means","options":["The occurrence of globalization in the Caribbean","Manifestation of globalization in African culture","Gainful collection of ideas","Thinking globally and acting locally"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Glocalization describes the blending of the global and the local, often summed up as thinking globally and acting locally, for example when global companies adapt products to local tastes. Option B is too narrow because glocalization is not limited to Africa, and option A wrongly ties it to one region."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 418, $official_bank_source${"itemId":"62479020-4830-5d45-aae5-037e0b612a7b","questionId":"729e2b74-24c7-5114-a896-3cbf4224d8f2","sourceKey":"bank:SOC101:SOC-0238","payload":{"prompt":"Which of these developments are seen to have facilitated the development of globalization?","options":["Global economy","Globalizing technology","Political changes","All of the above"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Globalization has been driven by the growth of a global economy, new technologies that connect the world, and political changes that opened borders to trade and movement. Since all three contributed, D is correct. Choosing only A, B or C leaves out the other factors."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 419, $official_bank_source${"itemId":"93e028c9-70e9-54fc-875c-4c2f31217254","questionId":"32ba5df8-2123-54c4-adf0-2724487c14be","sourceKey":"bank:SOC101:SOC-0256","payload":{"prompt":"Dominant capitalist economy implies that most nations of the world have gone capitalist. Which pair is usually cited as the exception because they remain under communist-party rule?","options":["Norway and Sweden","U.S.A. and Canada","Brazil and Mexico","Cuba and China"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Cuba and China are governed by communist parties and are usually cited as the main exceptions to the worldwide spread of capitalism, even though China now has large private markets. Norway and Sweden in A are capitalist welfare states. The U.S.A., Canada, Brazil and Mexico in B and C are capitalist economies."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 420, $official_bank_source${"itemId":"2ab3a42e-5263-5aba-8657-355055fe91f4","questionId":"28d24fc5-f8bb-5ee4-b115-64f7907fada0","sourceKey":"bank:SOC101:SOC-0257","payload":{"prompt":"Economic globalization is most closely associated with","options":["Modernization","Communist Manifesto","Communalism","Dominant capitalist economy"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Economic globalization means the spread of a single world market in which capitalist trade, investment and production dominate, so it is closely tied to the idea of a dominant capitalist economy. Option A, modernization, is a broader change from traditional to modern society. The Communist Manifesto in B and communalism in C point away from global capitalism."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 421, $official_bank_source${"itemId":"4c8256c9-b297-583c-8333-9c38a6cd288d","questionId":"285dca8d-b70d-5378-b79e-471564b4a179","sourceKey":"bank:SOC101:SOC-0259","payload":{"prompt":"Major aspects of globalization include the following except","options":["Globalizing technology","Global economy","Global inequality","Global monarchy"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Globalization is about growing links between countries through technology, the world economy and the inequalities that come with these links. There is no such thing as a 'global monarchy' ruling the world, so D is the exception. Options A, B and C are all real, widely discussed aspects of globalization."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 422, $official_bank_source${"itemId":"24753182-afa9-5765-ab11-2e870663e3b1","questionId":"0dd874ef-48c3-5897-90f0-6417462cba1a","sourceKey":"bank:SOC101:SOC-0279","payload":{"prompt":"The following include some of the key concepts of globalization except:","options":["Interconnectedness","Intensity","Conference","Interdependence"],"correctOption":2,"section":"Globalization and its impacts","explanation":"Key ideas in globalization include interconnectedness, intensity of global flows and interdependence among countries. A conference is simply a meeting, not a concept of globalization, so C is the exception. Options A, B and D all describe how globalization links the world."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 423, $official_bank_source${"itemId":"797e8121-d2ae-53a4-a3c9-78b4cdd4c8dc","questionId":"b68a5e40-3883-5d34-bb5a-bd9adaabbac7","sourceKey":"bank:SOC101:SOC-0283","payload":{"prompt":"Technological advances in the area of information processing, communications and transportation are seen to facilitate which of the following?","options":["Aggressiveness","Independence","Inter-dependence","Isolation"],"correctOption":2,"section":"Globalization and its impacts","explanation":"Advances in information processing, communication and transport bring countries closer together, so they come to depend on one another, which is interdependence. Option B, independence, is the opposite of this effect. Isolation in D and aggressiveness in A do not describe what these technologies encourage."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 424, $official_bank_source${"itemId":"e23b872c-b8e2-5a41-bdcf-70270f88fe15","questionId":"6b9ffc61-ce40-59ba-9b86-92710c3ac32d","sourceKey":"bank:SOC101:SOC-0295","payload":{"prompt":"Newly Industrializing Countries (NICs) of the world are regarded as what in Immanuel Wallerstein's categorizations?","options":["Core nations","Dependent nations","Periphery nations","Semi-periphery nations"],"correctOption":3,"section":"Globalization and its impacts","explanation":"In Wallerstein's world-systems theory, the semi-periphery sits between the rich core and the poor periphery, and it includes countries that are industrializing quickly, like the NICs, so D is correct. Option A, core nations, are the most advanced industrial economies, while Option C, periphery nations, mainly supply raw materials and cheap labour. Option B is not one of Wallerstein's three categories."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 425, $official_bank_source${"itemId":"d07c1fe8-1c94-5fb9-9cc8-82e795f8e958","questionId":"fb6e54e4-a64f-535f-a5df-c260f8a29122","sourceKey":"bank:SOC101:SOC-0301","payload":{"prompt":"Who was the person known to have differentiated global scapes into five major divisions?","options":["Lyotard","Friedman","Waters","Appadurai"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Arjun Appadurai described globalization in terms of five 'scapes': ethnoscapes, mediascapes, technoscapes, financescapes and ideoscapes, so D is correct. Option C, Waters, is known for a general book on globalization, and Options A and B are not linked to the five scapes."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 426, $official_bank_source${"itemId":"9a14109b-dddf-5138-bccd-d7ebe9404b2b","questionId":"9f688c22-ee5a-5621-bc21-ad8827a66e5c","sourceKey":"bank:SOC101:S101N3-055","payload":{"prompt":"Globalization is best defined as","options":["Increased interconnectedness and interdependence among countries, driven by technology, communication and trade","A policy of closing national borders to protect local industries from foreign competition","The movement of people from rural areas to cities within a single country","The control of weaker countries by a stronger country through military force"],"correctOption":0,"section":"Globalization and its impacts","explanation":"Globalization means countries becoming more interconnected and interdependent, driven by technology, communication and trade. Rural-urban migration within one country happened during industrialisation, but it is internal movement, not global interconnection."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 427, $official_bank_source${"itemId":"ff1cb017-2543-5f50-9edb-ce25459966ad","questionId":"bdea4d3d-7bcd-5187-9ec3-8da4c704ee83","sourceKey":"bank:SOC101:S101N3-056","payload":{"prompt":"Which of the following is NOT a key feature of globalization?","options":["Expansion of foreign direct investment","Liberalisation of international trade","Cross-border movement of labour and transactions","Raising tariffs and import quotas"],"correctOption":3,"section":"Globalization and its impacts","explanation":"The key features of globalization are trade liberalisation, expanding foreign direct investment and cross-border movement of transactions, labour and culture. Raising tariffs and quotas does the opposite: it restricts trade, whereas cutting them helps drive globalization."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 428, $official_bank_source${"itemId":"6c1df30d-f3cf-573c-9d7b-19e4f103964c","questionId":"d7ef56aa-9a0a-5180-97ff-f031a59d3455","sourceKey":"bank:SOC101:S101N3-057","payload":{"prompt":"The Federal Government reduces import tariffs and removes quotas on many goods to encourage international trade. This is an example of which factor prompting globalization?","options":["Cultural exchange","Policy decisions","Technology","Ecological globalization"],"correctOption":1,"section":"Globalization and its impacts","explanation":"Cutting tariffs and quotas is a policy decision, one of the two factors prompting globalization. Technology is the other factor, but it works by using ICT to reduce barriers of time and space, not by changing trade rules."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 429, $official_bank_source${"itemId":"aa109dde-8e2f-50fb-aa63-60a2fb2f7482","questionId":"3efbaadc-caa1-58f2-adb4-9d5ed09e71ab","sourceKey":"bank:SOC101:S101N3-058","payload":{"prompt":"The two factors that prompt globalization are","options":["Education and inclusive policies","Power dynamics and social constructs","Prejudice and discrimination","Policy decisions and technology"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Globalization is prompted by policy decisions, such as cutting tariffs and quotas, and by technology, especially ICT that reduces barriers of time and space. Power dynamics and social constructs are the factors that contribute to inequality, not to globalization."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 430, $official_bank_source${"itemId":"e6794f01-4708-547c-bb73-2e375dbe9a84","questionId":"273199c9-a6da-5f3e-9c64-16ec6e07af1f","sourceKey":"bank:SOC101:S101N3-059","payload":{"prompt":"An ECOWAS agreement allows Nigerians to travel and move goods freely into Ghana and other member states. This illustrates which type of globalization?","options":["Digital globalization","Geographical globalization","Financial globalization","Ecological globalization"],"correctOption":1,"section":"Globalization and its impacts","explanation":"Geographical globalization covers agreements such as ECOWAS that allow free movement of people and goods across borders. Ecological globalization is about countries sharing responsibility for the environment, not about moving people and goods."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 431, $official_bank_source${"itemId":"961c5338-6e40-5329-919c-bd1d43b7fb38","questionId":"1e7da1a0-75b7-5e3b-a1a3-41dcba5054ad","sourceKey":"bank:SOC101:S101N3-060","payload":{"prompt":"Countries agreeing to share responsibility for cutting pollution and protecting the climate is an example of which type of globalization?","options":["Ecological globalization","Financial globalization","Geographical globalization","Cultural globalization"],"correctOption":0,"section":"Globalization and its impacts","explanation":"Ecological globalization refers to shared environmental responsibility among countries, such as joint action on pollution and climate. Geographical globalization is about agreements on free movement of people and goods, like ECOWAS."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 432, $official_bank_source${"itemId":"34006df6-93de-511f-9aed-647c91b769f0","questionId":"7bad4fd0-e3c3-5127-8b68-ab06d91b51fc","sourceKey":"bank:SOC101:S101N3-061","payload":{"prompt":"A comedian in Lagos posts skits on social media and gains millions of followers in other countries. This best illustrates which type of globalization?","options":["Digital globalization","Geographical globalization","Ecological globalization","Financial globalization"],"correctOption":0,"section":"Globalization and its impacts","explanation":"Digital globalization is globalization through digital platforms such as social media, which let content reach audiences anywhere. Geographical globalization involves the physical movement of people and goods under agreements like ECOWAS, not online content."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 433, $official_bank_source${"itemId":"48376613-b038-5aa3-ad16-72d8a27288fd","questionId":"4d104a5a-dfd1-58bd-aaff-3dade816b203","sourceKey":"bank:SOC101:S101N3-062","payload":{"prompt":"Globalization is commonly classified into several types. Which of these is not one of them?","options":["Military globalization","Financial globalization","Geographical globalization","Ecological globalization"],"correctOption":0,"section":"Globalization and its impacts","explanation":"The five types of globalization are cultural, digital, financial, geographical and ecological. Military globalization is not one of them. Ecological globalization may seem unlikely, but it is a recognised type that refers to shared environmental responsibility."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 434, $official_bank_source${"itemId":"c09cc3e1-8675-5ee5-b228-b277e79e1f19","questionId":"4a1afd70-9368-572e-8c17-426c3f2c3e54","sourceKey":"bank:SOC101:S101N3-063","payload":{"prompt":"Of the following outcomes, which one counts as an advantage that globalization brings?","options":["Over-reliance on foreign products","Loss of cultural identity","Spread of misinformation","Access to information"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Access to information is a benefit of globalization, along with economic growth, cultural exchange, foreign investment and a better quality of life. Over-reliance on foreign products, misinformation and loss of cultural identity are disadvantages."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 435, $official_bank_source${"itemId":"6050efe5-1de6-5b4a-b6cc-421b959873a7","questionId":"cc33ad20-39c7-58f9-9cab-b47fe5d6f58f","sourceKey":"bank:SOC101:S101N3-064","payload":{"prompt":"Many young Nigerians abandon their local languages, dress and festivals in favour of foreign styles they see online. Which disadvantage of globalization does this illustrate?","options":["Environmental pollution","Loss of cultural identity","Economic disparities","Cultural exchange"],"correctOption":1,"section":"Globalization and its impacts","explanation":"When people abandon their own language, dress and festivals for foreign ones, they lose part of their cultural identity, a disadvantage of globalization. Cultural exchange is the tempting option, but it is a benefit: cultures share with each other while keeping their own identity."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 436, $official_bank_source${"itemId":"5300ca7e-a9ba-55fb-9e80-db651a181755","questionId":"a1690629-a1c9-5874-8e52-5909120a50c7","sourceKey":"bank:SOC101:S101N3-065","payload":{"prompt":"Each of the following is a drawback of globalization EXCEPT","options":["Spread of misinformation","Improved quality of life","Economic disparities","Environmental pollution"],"correctOption":1,"section":"Globalization and its impacts","explanation":"Improved quality of life is a benefit of globalization, not a disadvantage. Economic disparities, environmental pollution and the spread of misinformation are all listed disadvantages."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 437, $official_bank_source${"itemId":"d2b62c59-5b9e-5121-a88c-1538bc18b30d","questionId":"34d17b08-0ff5-5815-ae77-48515d483a3b","sourceKey":"bank:SOC101:S101N3-066","payload":{"prompt":"Nigerian consumers increasingly prefer imported rice, clothes and electronics, so local producers struggle to sell their goods. Which disadvantage of globalization does this show?","options":["Over-reliance on foreign products","Cultural exchange","Economic growth","Foreign investment"],"correctOption":0,"section":"Globalization and its impacts","explanation":"Depending heavily on imported goods at the expense of local producers is over-reliance on foreign products, a disadvantage of globalization. Foreign investment is a benefit and involves foreign capital coming into the country, not consumers preferring imports."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 438, $official_bank_source${"itemId":"6eac52a3-05b8-5b6d-a455-7a562db8d630","questionId":"e5f48a29-c428-54c1-9850-986aba71637e","sourceKey":"bank:SOC101:S101N3-067","payload":{"prompt":"Which scholar is cited for describing the manifestations of globalization?","options":["Malcolm Waters","Leslie Sklair","Arjun Appadurai","Immanuel Wallerstein"],"correctOption":1,"section":"Globalization and its impacts","explanation":"Leslie Sklair is cited for the manifestations of globalization. Malcolm Waters is the tempting option, but he gave the definition of globalization as a process in which the constraints of geography recede."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 439, $official_bank_source${"itemId":"0bf2475d-5d6d-5f3e-b58c-54368d02ac9b","questionId":"9461f9dc-f488-518c-bcb5-6365f82b81ab","sourceKey":"bank:SOC101:S101N3-068","payload":{"prompt":"Besides the Hyperglobalists and the Skeptics, the third school of thought on globalization is the","options":["Positivists","Interactionists","Functionalists","Transformationalists"],"correctOption":3,"section":"Globalization and its impacts","explanation":"The three schools of thought on globalization are the Hyperglobalists, the Skeptics and the Transformationalists. Functionalists, positivists and interactionists belong to general sociological theory, not to the globalization debate."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 440, $official_bank_source${"itemId":"aa7a0502-0f85-5e4e-ac83-dc5fdc40c388","questionId":"9ae95dd8-13cb-5f3f-9ba8-ab0466436812","sourceKey":"bank:SOC101:S101N3-069","payload":{"prompt":"In Arjun Appadurai's global culture theory, the flow of images and information across the world is called","options":["Finanscape","Ethnoscape","Mediascape","Ideoscape"],"correctOption":2,"section":"Globalization and its impacts","explanation":"A mediascape is the global flow of images and information, for example through films, television and news. An ideoscape is the flow of ideas, an ethnoscape is the flow of people and a finanscape is the flow of money."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 441, $official_bank_source${"itemId":"0ee09dc9-976c-54b9-871c-9d0da2241dde","questionId":"963f9485-5733-5849-9676-e809c3cf5f21","sourceKey":"bank:SOC101:S101N3-070","payload":{"prompt":"The worldwide spread of ideas such as democracy and human rights is an example of which of Appadurai's scapes?","options":["Mediascape","Ideoscape","Technoscape","Ethnoscape"],"correctOption":1,"section":"Globalization and its impacts","explanation":"An ideoscape is the global flow of ideas, so the spread of democracy and human rights is an ideoscape. A mediascape is the flow of images and information; these ideas may travel through the media, but what is flowing here is the ideas themselves."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 442, $official_bank_source${"itemId":"cd4371f6-c49a-5fb3-a141-ecc0c3ef623f","questionId":"a36fd166-4b75-5c14-ab81-2d56a2fda66a","sourceKey":"bank:SOC101:S101N3-071","payload":{"prompt":"Thousands of Nigerian nurses and doctors relocating to the United Kingdom for work is an example of which of Appadurai's scapes?","options":["Finanscape","Ideoscape","Ethnoscape","Mediascape"],"correctOption":2,"section":"Globalization and its impacts","explanation":"An ethnoscape is the global flow of people, such as health workers migrating abroad. A finanscape is the flow of money, so it would describe the money these workers send home, not their own movement."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 443, $official_bank_source${"itemId":"42a6e76c-05c8-5b69-8c39-240b1ab758de","questionId":"85b5724b-52d4-5554-89ca-53500514bbe4","sourceKey":"bank:SOC101:S101N3-072","payload":{"prompt":"A global fast-food chain opens branches in Lagos and adds jollof rice and plantain to its menu to suit local taste. This illustrates","options":["Hyperglobalism","Glocalization","Cultural lag","Ethnocentrism"],"correctOption":1,"section":"Globalization and its impacts","explanation":"Glocalization means thinking globally and acting locally, as a global company does when it adapts its products to local culture. Hyperglobalism is a school of thought on globalization, not a business practice."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 444, $official_bank_source${"itemId":"f6de7bc5-3a58-59ef-b2d8-7b1f7b366886","questionId":"521c70db-727e-52ed-9069-c055253bcc8a","sourceKey":"bank:SOC101:S101N3-073","payload":{"prompt":"Labour migration, cross-border transactions and cultural exchange together make up which key feature of globalization?","options":["Liberalisation of international trade","Ecological globalization","Expansion of foreign direct investment","Cross-border movement"],"correctOption":3,"section":"Globalization and its impacts","explanation":"Cross-border movement is the feature of globalization that covers transactions, labour migration and cultural exchange between countries. Liberalisation of international trade refers specifically to removing barriers to trade, such as tariffs, not to the movement of people and culture."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 445, $official_bank_source${"itemId":"b33ddf65-92d5-5a69-a9d8-fe70a28b4455","questionId":"4244a2da-4683-58fd-b7cc-7c0d605bd18b","sourceKey":"bank:SOC101:S101N3-074","payload":{"prompt":"Contemporary social issues are best described as","options":["Natural disasters that occur without human involvement","Historical events that shaped ancient societies","Current social phenomena and challenges affecting societies globally","Personal problems that affect only individuals"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Contemporary issues are current social phenomena and challenges that affect societies around the world, such as globalisation, inequality, social justice, identity and diversity. Historical events of ancient societies are not current, and purely personal problems are not shared social challenges."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 446, $official_bank_source${"itemId":"c14d9c81-4ed3-522e-98df-85ddc941204d","questionId":"4b5ca31d-1ffd-582c-98ca-341ed603d409","sourceKey":"bank:SOC101:S101N3-075","payload":{"prompt":"Why is the study of contemporary social issues important?","options":["It stops all social change from taking place","It proves that one culture is superior to others","It removes the need for laws and government","It helps address social challenges and promote social cohesion"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Studying contemporary issues helps societies address their challenges and promote cohesion, so that people live together more harmoniously. It does not aim to prove one culture superior, which would contradict cultural relativism."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 447, $official_bank_source${"itemId":"8f227828-8fef-5108-9b78-b832c26e0076","questionId":"59d646c5-0e96-55ef-9718-7774a61dc674","sourceKey":"bank:SOC101:S101N3-076","payload":{"prompt":"Which of the following sets lists contemporary social issues?","options":["Mechanical and organic solidarity","Theological, metaphysical and scientific stages","Globalisation, inequality, social justice, identity and diversity","Social statics and social dynamics"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Globalisation, inequality, social justice, identity and diversity are examples of contemporary issues facing societies today. The theological, metaphysical and scientific stages make up Comte's law of three stages, a classical theory of how societies develop."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 448, $official_bank_source${"itemId":"780eb98b-2d48-51cd-a9e9-4098f084c189","questionId":"308f1e7f-93d3-5828-8711-2646d7045d06","sourceKey":"bank:SOC101:S101N3-077","payload":{"prompt":"Inequality is defined as","options":["The unfair distribution of resources, opportunities and privileges","The appreciation of differences among individuals and groups","The fair and equitable distribution of resources, opportunities and privileges","The way a group perceives itself by its culture or beliefs"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Inequality is the unfair distribution of resources, opportunities and privileges in a society. The fair and equitable distribution of the same things is the definition of social justice, which is the opposite of inequality."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 449, $official_bank_source${"itemId":"d996e61e-36d3-5b46-8dd7-a91aa9722249","questionId":"c5c45a44-9339-59fc-839c-476912ca7020","sourceKey":"bank:SOC101:S101N3-078","payload":{"prompt":"The fair and equitable distribution of resources, opportunities and privileges, so that everyone can thrive, is called","options":["Diversity","Inequality","Social justice","Identity"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Social justice is the fair and equitable distribution of resources, opportunities and privileges so that everyone can thrive. Inequality is the opposite: the unfair distribution of the same things."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 450, $official_bank_source${"itemId":"4326342e-913e-5109-82c7-a4c7433ddc53","questionId":"426235b5-3779-56b5-8358-000f544a1c73","sourceKey":"bank:SOC101:S101N3-079","payload":{"prompt":"The five types of inequality are","options":["Personal, social and cultural","Ethnic, cultural, religious and gender","Economic, gender, racial, disability and political","Cultural, digital, financial, geographical and ecological"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Inequality takes five forms: economic, gender, racial, disability and political. Cultural, digital, financial, geographical and ecological are types of globalization, and ethnic, cultural, religious and gender are the types of diversity."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 451, $official_bank_source${"itemId":"403c1db2-9e3a-59e7-b515-b3fb24fc974e","questionId":"627d0b04-349a-5c15-810c-53d49d3a4222","sourceKey":"bank:SOC101:S101N3-080","payload":{"prompt":"A qualified wheelchair user in Ikeja cannot take up a job because the office building has no ramp or lift. This is an example of which type of inequality?","options":["Gender inequality","Disability inequality","Racial inequality","Political inequality"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Disability inequality occurs when people with disabilities are denied opportunities, here a job, because their needs are not met. Gender and racial inequality are based on a person's sex or race, which are not the issue in this case."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 452, $official_bank_source${"itemId":"62cce3f7-8d4c-5335-9251-905260283cfa","questionId":"61118a9a-5ef3-52ae-b71b-0acfb71f8f1e","sourceKey":"bank:SOC101:S101N3-081","payload":{"prompt":"In a rural community, girls are withdrawn from school to marry early while their brothers continue their education. This is an example of","options":["Political inequality","Racial inequality","Disability inequality","Gender inequality"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Gender inequality is unequal access to opportunities on the basis of gender, as when girls lose schooling that boys keep. Racial inequality would involve unequal treatment by race, not sex."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 453, $official_bank_source${"itemId":"0f227ff8-5b0f-53d1-85da-364fd51c8c22","questionId":"c2a4cc7d-68a7-5f67-9613-60b658cf6f8b","sourceKey":"bank:SOC101:S101N3-082","payload":{"prompt":"Citizens of a particular group are barred by law from voting or standing for election, while other citizens can do both. This is an example of","options":["Disability inequality","Economic inequality","Racial inequality","Political inequality"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Political inequality is unequal access to political rights and power, such as voting and standing for office. Economic inequality concerns unequal income, wealth and resources, not voting rights."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 454, $official_bank_source${"itemId":"9554feea-31b6-5622-94e4-418589fa229a","questionId":"7669f0db-7ad3-5163-8e17-1ca6c4072381","sourceKey":"bank:SOC101:S101N3-083","payload":{"prompt":"Residents of Banana Island live in luxury mansions while many residents of Makoko, a few kilometres away, live in poverty. This contrast best illustrates","options":["Gender inequality","Political inequality","Economic inequality","Racial inequality"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Economic inequality is the unfair distribution of income, wealth and other resources, shown by the gap between wealthy Banana Island and poor Makoko. Political inequality concerns unequal political rights and power, which the example does not describe."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 455, $official_bank_source${"itemId":"86a07bb1-bbf5-5973-9f9d-03ea8d173172","questionId":"19871941-2fda-5616-87ae-f0c3c9d3475d","sourceKey":"bank:SOC101:S101N3-084","payload":{"prompt":"Customers are refused service at a hotel abroad because of the colour of their skin. This is an example of","options":["Gender inequality","Disability inequality","Political inequality","Racial inequality"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Racial inequality is unequal treatment or opportunity based on race or skin colour, as in being refused service. Gender inequality is based on a person's sex, which is not the basis of the treatment here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 456, $official_bank_source${"itemId":"ed24f5bf-e610-5dd0-8ca3-51da5aaa0b1a","questionId":"ace2dd2d-c28c-5fc6-b67d-c074eaf04ce6","sourceKey":"bank:SOC101:S101N3-085","payload":{"prompt":"The two factors that contribute to inequality are","options":["Prejudice and discrimination","Policy decisions and technology","Education and inclusive policies","Power dynamics and social constructs"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Inequality is driven by power dynamics and by social constructs such as religion, gender, ethnicity, age, race and class. Policy decisions and technology are the two factors that prompt globalization, not inequality."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 457, $official_bank_source${"itemId":"ae0fdfb1-d154-534a-9277-db035f3a0504","questionId":"210c66ea-cc9a-5527-bec1-bcc532257ade","sourceKey":"bank:SOC101:S101N3-086","payload":{"prompt":"Which of the following is NOT among the social constructs that contribute to inequality?","options":["Sexual orientation","Intelligence","Prestige","Power dynamics"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Power dynamics is a separate contributing factor to inequality, not one of the social constructs. The social constructs are religion, gender, prestige, ethnicity, age, race, sexual orientation, intelligence and class."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 458, $official_bank_source${"itemId":"0b00621d-2c00-5596-a7a6-5e21b9e8baff","questionId":"45b0edeb-34f9-5d55-bb25-cf0074c1ca19","sourceKey":"bank:SOC101:S101N3-087","payload":{"prompt":"Age, race, class and ethnicity are examples of which factor contributing to inequality?","options":["Forms of identity","Power dynamics","Social constructs","Principles of social justice"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Age, race, class and ethnicity are social constructs, one of the two factors that contribute to inequality. Power dynamics is the other factor; it concerns who holds power, not the categories into which people are placed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 459, $official_bank_source${"itemId":"108e68eb-eec2-5766-9a79-5fc4694dfd82","questionId":"a30b0371-3e87-50ea-b497-2b224293d734","sourceKey":"bank:SOC101:S101N3-088","payload":{"prompt":"In a local government area, a few influential men decide how all community funds are shared because they hold the most power, so other residents receive very little. This mainly illustrates which factor contributing to inequality?","options":["Power dynamics","Innovation","Diversity","Participation"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Power dynamics, meaning who holds power and how they use it, contributes to inequality when a powerful few control how resources are shared. Participation is the opposite situation, a principle of social justice in which everyone takes part in decisions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 460, $official_bank_source${"itemId":"550bb62b-88e9-5462-b08d-b082c92cbdd4","questionId":"405fa504-8447-5870-8023-a815bf07a3df","sourceKey":"bank:SOC101:S101N3-089","payload":{"prompt":"Social justice rests on five principles. Which of these is not one of them?","options":["Equal access","Equity","Participation","Meritocracy"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"The five principles of social justice are equal access, equity, diversity, participation and respect for human rights. Meritocracy, appointment by merit, is a feature of bureaucracy, not a principle of social justice."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 461, $official_bank_source${"itemId":"ab2371c9-1f32-5e76-8a94-1e35b30c8005","questionId":"9e4fdd9d-e835-52b9-8bb4-2040f8feec1a","sourceKey":"bank:SOC101:S101N3-090","payload":{"prompt":"In social justice, the principle of equity means","options":["Including different groups in decision-making","Distribution based on need","Giving everyone exactly the same share","Allowing everyone to vote in elections"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Equity means distributing resources based on need, so those who need more receive more. Giving everyone exactly the same share is the tempting option, but that is equal treatment, which ignores differences in need."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 462, $official_bank_source${"itemId":"6c63c4f4-29bc-5276-a360-71910c29b8f4","questionId":"bdf3b6d9-4045-55ed-ac70-a5649ab49437","sourceKey":"bank:SOC101:S101N3-091","payload":{"prompt":"When diversity is listed as a principle of social justice, it means","options":["Equal access to opportunities for all","Respect for the basic rights of every person","Inclusion of different groups in decision-making","Distribution of resources based on need"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"As a principle of social justice, diversity means including people of different groups and backgrounds in decision-making. Distribution based on need is equity, a different principle."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 463, $official_bank_source${"itemId":"63e1ff3a-4e44-5380-858d-afe05b5dc554","questionId":"8a02c97e-1ddc-5041-a881-286ae4797d13","sourceKey":"bank:SOC101:S101N3-092","payload":{"prompt":"UNILAG gives extra bursaries and support to students from the poorest homes, so that they can study on a fairer footing with others. Which principle of social justice does this reflect?","options":["Equal access","Equity","Respect for human rights","Participation"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Equity means distributing resources based on need, which is why the poorest students receive extra support. Equal access is close, but it is about making opportunities open to all, not about giving more to those who need more."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 464, $official_bank_source${"itemId":"1b43365a-fa9a-581b-a15e-a7de766d0a79","questionId":"3d2c1df8-6d5a-5876-8b05-26957982087f","sourceKey":"bank:SOC101:S101N3-093","payload":{"prompt":"Residents of a Lagos community are consulted at town-hall meetings and allowed to vote on how their local budget is spent. Which principle of social justice is at work?","options":["Equity","Respect for human rights","Participation","Equal access"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Participation is the principle that people take part in the decisions that affect them, as residents do when they vote on their budget. Equity concerns sharing resources based on need, not taking part in decisions."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 465, $official_bank_source${"itemId":"fd730daf-854c-580c-bd66-6ae9fc8a4b00","questionId":"5c1d59ad-65e5-5e63-9b20-965aab2209af","sourceKey":"bank:SOC101:S101N3-094","payload":{"prompt":"A new law ensures that every qualified Nigerian, whatever their ethnic group or background, can apply for federal jobs and use public facilities. This mainly reflects which principle of social justice?","options":["Equity","Power dynamics","Participation","Equal access"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Equal access means opportunities and facilities are open to everyone, whatever their background. Equity is different, because it gives more to those who need more instead of opening the same opportunities to all."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 466, $official_bank_source${"itemId":"4aad8fd8-e2ef-53db-87c1-fbb720bb9a89","questionId":"7d9af2a2-90e4-5b3d-8de7-4b1038eb108d","sourceKey":"bank:SOC101:S101N3-095","payload":{"prompt":"A court rules that the police may not torture suspects to obtain confessions, because every person has basic rights. Which principle of social justice does this uphold?","options":["Respect for human rights","Participation","Equity","Equal access"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Protecting every person from torture is respect for human rights, one of the five principles of social justice. Equity concerns distributing resources based on need, which is not what the ruling is about."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 467, $official_bank_source${"itemId":"11076b48-91f2-5052-89b8-348ce39612f7","questionId":"dd3213be-54c7-5685-951a-fa169c318335","sourceKey":"bank:SOC101:S101N3-096","payload":{"prompt":"How an individual or group perceives themselves in terms of culture, gender, beliefs or religion is called","options":["Identity","Diversity","Social justice","Inequality"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Identity is how an individual or group sees itself in terms of culture, gender, beliefs or religion. Diversity is different: it is about appreciating the differences among individuals or groups and bringing them together."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 468, $official_bank_source${"itemId":"f6a21217-a05c-5c99-a137-a1fc3634176e","questionId":"6c80f610-4e2e-5a88-9fe2-25ddc5681502","sourceKey":"bank:SOC101:S101N3-097","payload":{"prompt":"A person's identity is shaped by","options":["Government laws alone","Income alone","Experience, interaction and culture","Genes and hormones alone"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Identity is shaped by experience, interaction with others and culture, so it develops socially over time. Genes and hormones are biological, and they alone do not determine how people see themselves."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 469, $official_bank_source${"itemId":"668c4061-74ea-58b0-95fc-34756476510d","questionId":"4d892f07-6433-54fe-b5ad-6d0e55033231","sourceKey":"bank:SOC101:S101N3-098","payload":{"prompt":"The three forms of identity are","options":["Ascribed, achieved and assigned","Economic, racial and political","Ethnic, religious and gender","Personal, social and cultural"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"The three forms of identity are personal, social and cultural. Ethnic, religious and gender are types of diversity, and economic, racial and political are types of inequality."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 470, $official_bank_source${"itemId":"375ff623-c85a-5000-a594-813cbf1dd24b","questionId":"a0260079-bef5-5317-9ab5-21c90f50ccc8","sourceKey":"bank:SOC101:S101N3-099","payload":{"prompt":"The form of identity that refers to how a group sees itself is","options":["Social identity","Ethnic identity","Personal identity","Cultural identity"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Social identity is how a group sees itself. Personal identity is the tempting alternative, but it refers to how an individual sees themself, not a group."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 471, $official_bank_source${"itemId":"7a59c06a-bccd-52b7-9e70-3b7ce5fcac36","questionId":"8e4b37b2-8ca2-5a63-bd46-e2d779b18ee4","sourceKey":"bank:SOC101:S101N3-100","payload":{"prompt":"A 100L student describes herself as hardworking, creative and ambitious. This self-description is an example of","options":["Personal identity","Social identity","Cultural identity","Religious diversity"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Personal identity is how an individual sees themself, as the student does when she describes her own qualities. Social identity is how a group sees itself, and here only one person is describing herself."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 472, $official_bank_source${"itemId":"23841ef5-79bb-5acd-91bd-e7fc24ff7821","questionId":"d87d3e60-adb9-554d-826e-afc9b4a43678","sourceKey":"bank:SOC101:S101N3-101","payload":{"prompt":"A Yoruba man living in Canada makes a point of speaking Yoruba at home, eating Yoruba food and celebrating Yoruba festivals. This mainly reflects his","options":["Personal identity","Political identity","Social identity","Cultural identity"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Cultural identity is a person's identification with a culture, shown here by keeping Yoruba language, food and festivals. Personal identity is how he sees his own individual qualities, which is not what the example describes."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 473, $official_bank_source${"itemId":"cccfdaea-efcc-5216-a284-3982f76b4f05","questionId":"4af5413c-ba42-52da-8aae-bb0c0304ce1d","sourceKey":"bank:SOC101:S101N3-102","payload":{"prompt":"Members of a Lagos football fan club see themselves as the most loyal supporters in the country and take pride in that image as a group. This is an example of","options":["Gender diversity","Social identity","Cultural identity","Personal identity"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Social identity is how a group sees itself, as the fan club does when its members share a collective self-image. Personal identity would be how one individual sees themself, not the group as a whole."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 474, $official_bank_source${"itemId":"27dd7131-345f-56cb-972c-77b391bd54cd","questionId":"ddf4f43c-295f-527e-b463-971057c97af2","sourceKey":"bank:SOC101:S101N3-103","payload":{"prompt":"Which statement correctly distinguishes personal identity from social identity?","options":["Personal identity is how an individual sees themself; social identity is how a group sees itself","Personal identity is identification with a culture; social identity is how an individual sees themself","Personal identity is fixed at birth; social identity is learned through socialization","Personal identity is how a group sees itself; social identity is how an individual sees themself"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"Personal identity is about how an individual sees themself, while social identity is about how a group sees itself. Identification with a culture is cultural identity, the third form, not personal identity."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 475, $official_bank_source${"itemId":"6756e165-e8de-5a87-b0ae-d61832878142","questionId":"ce52e453-e581-54c7-9bc5-f8c280428013","sourceKey":"bank:SOC101:S101N3-104","payload":{"prompt":"Appreciating and focusing on the differences among individuals or groups, and bringing people of different backgrounds together, is known as","options":["Identity","Inequality","Diversity","Equity"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Diversity means appreciating differences among people and bringing different backgrounds together. Identity is how an individual or group perceives itself, not the bringing together of different groups."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 476, $official_bank_source${"itemId":"802d7e06-596f-541e-bfbe-94615491ff53","questionId":"87803137-aa2a-591f-8f0c-af6e293c075c","sourceKey":"bank:SOC101:S101N3-105","payload":{"prompt":"The four types of diversity are","options":["Cultural, digital, financial and ecological","Ethnic, cultural, religious and gender","Personal, social and cultural","Economic, gender, racial, disability and political"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"The four types of diversity are ethnic, cultural, religious and gender. Economic, gender, racial, disability and political are the five types of inequality, which overlap only on gender."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 477, $official_bank_source${"itemId":"457cfc9d-5098-57d7-a504-9aefd99cadab","questionId":"9c1a0a81-4130-57b3-8ea0-901def1caedd","sourceKey":"bank:SOC101:S101N3-106","payload":{"prompt":"A Lagos firm deliberately recruits staff from Hausa, Igbo, Yoruba and Ijaw backgrounds. Which type of diversity does this mainly show?","options":["Religious diversity","Ethnic diversity","Economic diversity","Gender diversity"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Recruiting staff from different ethnic groups such as Hausa, Igbo, Yoruba and Ijaw shows ethnic diversity. Religious diversity is about people of different faiths, which the example does not mention."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 478, $official_bank_source${"itemId":"95d658fe-3a68-5d92-8af6-46d8e3512e57","questionId":"353f5a86-f9ef-5aaa-b5f1-bdc5d1b388d4","sourceKey":"bank:SOC101:S101N3-107","payload":{"prompt":"In a UNILAG department, Muslim, Christian and traditional worshippers work side by side, and prayer spaces are provided for each group. Which type of diversity does this mainly show?","options":["Disability diversity","Gender diversity","Ethnic diversity","Religious diversity"],"correctOption":3,"section":"Inequality, social justice, identity and diversity","explanation":"Staff of different faiths working together, with space for each to worship, shows religious diversity. Ethnic diversity is about people from different ethnic groups, which is not the difference highlighted here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 479, $official_bank_source${"itemId":"881bf579-2a76-54f1-9a8d-19be150bcbe9","questionId":"84c3de9b-3d93-5c69-ab1e-517a1d8dfbc8","sourceKey":"bank:SOC101:S101N3-108","payload":{"prompt":"The two advantages of diversity are","options":["Power dynamics and social constructs","Prejudice and discrimination","Economic growth and innovation","Education and inclusive policies"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Diversity brings two advantages: economic growth and innovation. Education and inclusive policies are ways to promote diversity, not its advantages, and prejudice and discrimination are challenges to it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 480, $official_bank_source${"itemId":"a87ddfcf-f3b9-5bcd-ac67-65be2b5b96d2","questionId":"860c402e-403d-5de4-b560-9d44eaf0b610","sourceKey":"bank:SOC101:S101N3-109","payload":{"prompt":"A tech start-up in Yaba brings together staff from many different backgrounds, and their varied perspectives lead to new product ideas. Which advantage of diversity does this illustrate?","options":["Prejudice","Inclusive policies","Innovation","Lack of empathy"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Innovation is an advantage of diversity: people with different backgrounds bring different ideas, which leads to new products. Inclusive policies are a way of promoting diversity, not an advantage that comes from it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 481, $official_bank_source${"itemId":"52b24386-8862-5790-8cee-9b0fa64b52ce","questionId":"2e826b0d-6db4-5e0e-a52a-8c5411525949","sourceKey":"bank:SOC101:S101N3-110","payload":{"prompt":"Which of the following is NOT a challenge to diversity?","options":["Lack of empathy","Innovation","Discrimination","Prejudice"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Innovation is an advantage of diversity, not a challenge to it. The three challenges are prejudice, discrimination and lack of empathy."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 482, $official_bank_source${"itemId":"6ab2f3c5-6fd9-55cf-86c4-ce9b3ab31a5e","questionId":"1b5cc450-7af7-5920-b75c-1aebd6a57357","sourceKey":"bank:SOC101:S101N3-111","payload":{"prompt":"The two ways of promoting diversity are","options":["Prejudice and discrimination","Policy decisions and technology","Education and inclusive policies","Economic growth and innovation"],"correctOption":2,"section":"Inequality, social justice, identity and diversity","explanation":"Diversity is promoted through education and inclusive policies. Economic growth and innovation are the advantages that diversity brings, not the ways of promoting it."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 483, $official_bank_source${"itemId":"8630ca97-d81b-5c70-9632-3d58545b254c","questionId":"892c0780-bcac-52bc-a881-4b132e6d3b9d","sourceKey":"bank:SOC101:S101N3-112","payload":{"prompt":"A bank in Lagos adopts a recruitment rule that guarantees fair consideration to applicants of every ethnic group, religion and gender. This is an example of promoting diversity through","options":["Inclusive policies","Lack of empathy","Power dynamics","Social constructs"],"correctOption":0,"section":"Inequality, social justice, identity and diversity","explanation":"A recruitment rule that guarantees fair consideration for all groups is an inclusive policy, one of the two ways of promoting diversity. Power dynamics and social constructs are factors that contribute to inequality, not ways of promoting diversity."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 484, $official_bank_source${"itemId":"b234b293-1470-5544-8266-dab3752eb8eb","questionId":"91f2a241-dbb4-5c42-8fc5-f6f13467aafe","sourceKey":"bank:SOC101:S101N3-113","payload":{"prompt":"Lack of empathy is best classified as","options":["A form of identity","A challenge to diversity","A principle of social justice","A way of promoting diversity"],"correctOption":1,"section":"Inequality, social justice, identity and diversity","explanation":"Lack of empathy is one of the three challenges to diversity, along with prejudice and discrimination. It is not a way of promoting diversity; those ways are education and inclusive policies."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 485, $official_bank_source${"itemId":"6652e0a4-6fb3-5cbd-8d30-5e0ba54501b8","questionId":"85077c6f-4f44-57f9-b2d9-fce8148391aa","sourceKey":"bank:SOC101:S101N4-001","payload":{"prompt":"Social relationships are best defined as","options":["The movement of individuals from one social position to another","The ranking of people into layers by wealth and power","The connections and interactions people have with others","The process by which people learn the culture of their society"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Social relationships are simply the connections and interactions we have with other people, from family and friends to colleagues. Ranking people into layers by wealth and power describes stratification, while movement between positions is social mobility, so neither defines a relationship."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 486, $official_bank_source${"itemId":"f99a7a46-ea85-5d28-a558-96d53b9af40c","questionId":"3ace76b3-7f53-57b3-84f4-8276baa54b3d","sourceKey":"bank:SOC101:S101N4-002","payload":{"prompt":"The quality of a person's social relationships most directly affects their","options":["Mental and emotional health","Ethnic origin","Ascribed status at birth","Legal citizenship"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Good or poor relationships shape how a person feels and copes, so their quality directly affects mental and emotional health. Ascribed status, citizenship and ethnic origin are fixed by birth or law and are not changed by how well someone relates to others."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 487, $official_bank_source${"itemId":"552c7770-66df-5138-a4e6-9f51cfd440f9","questionId":"3aac1592-adc7-5029-bfa4-c8ae0f47f0f9","sourceKey":"bank:SOC101:S101N4-003","payload":{"prompt":"Which statement about social relationships in today's fast-paced, digital life is correct?","options":["They are harder to maintain but remain essential","They are easier to maintain and less important","They have become unnecessary because of social media","They are no longer affected by how people communicate"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Busy schedules and constant screen use make relationships harder to keep up, yet people still need them, so they remain essential. The idea that social media has made them unnecessary is wrong; online life changes how relationships are kept, not whether we need them."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 488, $official_bank_source${"itemId":"34366e3c-fb27-5d7b-ab02-42fe843b7f0d","questionId":"7134fe58-afeb-5bc4-89a0-91b5d66d0c90","sourceKey":"bank:SOC101:S101N4-004","payload":{"prompt":"In the framework of personal and social competence, self-awareness and self-management together make up","options":["Social competence","Personal competence","Effective expression of emotions","Digital citizenship"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Self-awareness and self-management are about handling yourself, so they form personal competence. Social competence is the other half of the framework, made up of social awareness and relationship management, which are about dealing with others."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 489, $official_bank_source${"itemId":"bba8bf2f-19e2-5e1c-8a14-1b0324cb33a5","questionId":"215c735e-f851-5aef-9f20-a851441688db","sourceKey":"bank:SOC101:S101N4-005","payload":{"prompt":"Tunde, a 100L student, notices that a group member is upset during a class project and handles the disagreement so the group keeps working well together. Which part of the competence framework is he mainly showing?","options":["Personal competence","Online etiquette","Social competence","Digital boundaries"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Noticing how others feel is social awareness, and handling the disagreement well is relationship management; together these make up social competence. Personal competence is tempting, but it covers self-awareness and self-management, which focus on oneself rather than on others."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 490, $official_bank_source${"itemId":"72dcbd90-a26d-5a1c-8d37-dff9ccddc114","questionId":"85af3ffe-d920-59bf-8072-852524235288","sourceKey":"bank:SOC101:S101N4-006","payload":{"prompt":"Which of the following correctly matches a component with its type of competence?","options":["Self-awareness - social competence","Relationship management - personal competence","Self-management - personal competence","Social awareness - personal competence"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Self-management belongs to personal competence, alongside self-awareness. Social awareness and relationship management belong to social competence, so pairing either of them with personal competence, or pairing self-awareness with social competence, is a mismatch."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 491, $official_bank_source${"itemId":"226003a3-c01b-5ea9-b5d5-7a0f651c94b5","questionId":"696b2835-e4a6-5c20-8aee-2a4a8c1d77b0","sourceKey":"bank:SOC101:S101N4-007","payload":{"prompt":"How many types of social relationship are identified when studying how to understand and manage relationships?","options":["Two","Five","Three","Four"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Four types are identified: family, friendships, romantic relationships and colleagues or professional relationships. Three is a tempting answer because several other lists in the topic, such as communication skills and challenging situations, have three items each."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 492, $official_bank_source${"itemId":"7d3bf04d-3d1a-5778-9f79-75fd86f76c4b","questionId":"3555d9b1-d69c-5aba-b7d8-515870531849","sourceKey":"bank:SOC101:S101N4-008","payload":{"prompt":"Which of the following is NOT one of the four types of social relationship?","options":["Friendships","Colleague or professional relationships","Family relationships","Political relationships"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"The four types are family, friendships, romantic relationships and colleagues or professional relationships, so political relationships is not one of them. Colleague relationships may sound less personal, but they are included because teamwork and shared goals at work are a real part of social life."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 493, $official_bank_source${"itemId":"f2527c4b-6541-590e-9199-d0c149e65cbd","questionId":"857ff03c-df28-5b89-a7f9-686ba3290d6d","sourceKey":"bank:SOC101:S101N4-009","payload":{"prompt":"Relationships with parents, siblings, extended family and in-laws are classified as","options":["Romantic relationships","Family relationships","Professional relationships","Friendships"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Parents, siblings, extended family members and in-laws are all part of family relationships. In-laws may seem linked to romance because they come through marriage, but the relationship with them is a family one, not a romantic one."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 494, $official_bank_source${"itemId":"ca0541be-f7c2-5290-b382-024aa30250b9","questionId":"79ae7924-7f31-5127-a19a-369f334b5a3d","sourceKey":"bank:SOC101:S101N4-010","payload":{"prompt":"Which set of benefits is associated with family relationships?","options":["Teamwork, respect and shared goals","Privacy, screen time and tone","Mutual affection, trust and shared interests","Support, socialization and belonging"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"The family gives its members support, socializes them into society and gives them a sense of belonging. Teamwork, respect and shared goals describe colleague relationships, while mutual affection, trust and shared interests describe friendships."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 495, $official_bank_source${"itemId":"78edf07d-5ad8-57d8-978e-507e347d1bc5","questionId":"1248e73a-e50b-5396-bbbf-b2388f67e2b6","sourceKey":"bank:SOC101:S101N4-011","payload":{"prompt":"A relationship between people who are not related, built on mutual affection, trust and shared interests, is a","options":["Case of social exclusion","Professional relationship","Family relationship","Friendship"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Friendships rest on mutual affection, trust and shared interests between people who choose each other. A family relationship is based on kinship such as parents, siblings and in-laws, which the stem rules out by saying the people are not related."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 496, $official_bank_source${"itemId":"15f39b04-30ad-5e27-b154-f1a4e316d55c","questionId":"69ce9c1e-687f-5192-a026-4ae36cf8488c","sourceKey":"bank:SOC101:S101N4-012","payload":{"prompt":"A relationship marked by emotional and physical intimacy and commitment is a","options":["Romantic relationship","Family relationship","Professional relationship","Friendship"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Emotional and physical intimacy together with commitment are the marks of a romantic relationship. Friendship involves affection and trust, but it is defined by shared interests rather than physical intimacy and commitment."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 497, $official_bank_source${"itemId":"10bc092d-2e90-5d02-8fdf-dcf5ac6e16b0","questionId":"bb289f48-938c-5a26-b0da-9396c88b5567","sourceKey":"bank:SOC101:S101N4-013","payload":{"prompt":"Teamwork, respect and shared goals are the main features of which type of relationship?","options":["Romantic relationships","Family relationships","Colleague or professional relationships","Friendships"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"People who work together relate through teamwork, mutual respect and goals they share at work, which defines colleague or professional relationships. Friendships also involve respect, but they are built on mutual affection, trust and shared interests rather than shared work goals."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 498, $official_bank_source${"itemId":"09766b76-70d5-53ea-92e9-0d15d4f61b11","questionId":"c41e31de-d645-55a4-9ea0-208ef1938114","sourceKey":"bank:SOC101:S101N4-014","payload":{"prompt":"Which of the following is NOT a challenge of colleague or professional relationships?","options":["Family approval","Workplace politics","Decorum","Power dynamics"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Workplace politics, power dynamics and decorum are the challenges that come with professional relationships. Family approval belongs to romantic relationships, where in Nigeria the approval of the family and the rituals involved matter a great deal."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 499, $official_bank_source${"itemId":"d6feac79-bb9a-57b1-a20b-b944479e3c9b","questionId":"1678677b-e905-56f5-a3f2-e05925dd057b","sourceKey":"bank:SOC101:S101N4-015","payload":{"prompt":"Adaeze works at a bank in Lagos. A senior manager's control over promotions makes junior staff afraid to speak up in meetings. This challenge in professional relationships is best described as","options":["Social exclusion","Gossip","Power dynamics","Digital boundaries"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"When one person holds authority over others, such as control over promotions, it shapes how freely the others behave; this is power dynamics. Gossip would involve spreading unverified information, which is not what is happening here."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 500, $official_bank_source${"itemId":"84cfc1d6-4ddf-5adf-a837-85dac73a71d1","questionId":"06f296dc-a68c-5944-8219-ad8295fad109","sourceKey":"bank:SOC101:S101N4-016","payload":{"prompt":"In the Nigerian context, which factor matters greatly in romantic relationships?","options":["Screen-time limits","Volunteering through NYSC","Family approval and rituals","Workplace decorum"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Romantic relationships in Nigeria are not just between two people; the approval of both families and the rituals involved carry great weight. Workplace decorum is a concern of colleague relationships, not romantic ones."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 501, $official_bank_source${"itemId":"4b66504b-a92d-5b27-bc87-9966218eb458","questionId":"c08bcc5f-1a4a-5d96-ae11-e4f0c31720e6","sourceKey":"bank:SOC101:S101N4-017","payload":{"prompt":"Which statement about family relationships in Nigeria is correct?","options":["The extended family shapes decisions, conflict resolution and celebrations","Family approval plays no part in romantic relationships","Elders are given no special role in family life","Only the nuclear family takes part in major family decisions"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"In Nigeria the extended family is closely involved in family life, shaping decisions, settling conflicts and taking part in celebrations. The claim that only the nuclear family takes part in decisions is wrong, because uncles, aunts and other relatives are often deeply involved."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 502, $official_bank_source${"itemId":"20e1cbca-4926-52c0-8634-15e00f037bfa","questionId":"4cd7eb46-52b5-5b6d-8c7d-14360543512b","sourceKey":"bank:SOC101:S101N4-018","payload":{"prompt":"Within Nigerian family relationships, which group is given special respect?","options":["Younger siblings","Age-mates","Elders","Colleagues"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Nigerian family life gives elders special respect, and their views carry weight in decisions. Age-mates may be close and friendly, but they do not receive the special respect that elders do."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 503, $official_bank_source${"itemId":"984a868f-8942-516c-9e6a-2d3e0cc0adc7","questionId":"24898f48-3eb6-5807-a9ee-3640c28899c8","sourceKey":"bank:SOC101:S101N4-019","payload":{"prompt":"Which of the following is NOT one of the three communication skills for managing relationships?","options":["Digital citizenship","Conflict resolution","Effective expression of emotions","Active listening"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"The three communication skills are active listening, conflict resolution and effective expression of emotions. Digital citizenship is about responsible and ethical use of social media, so it belongs to the social media area, not to communication skills."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 504, $official_bank_source${"itemId":"39b64a99-a11e-54aa-a540-51c0a9abd806","questionId":"2a53bdb7-b170-5f15-a884-fc7f53db15d9","sourceKey":"bank:SOC101:S101N4-020","payload":{"prompt":"Active listening is valued in relationships mainly because it","options":["Creates rivalry","Encourages dependence","Builds trust","Enforces conformity"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"When people feel truly heard, they come to trust the listener, so active listening builds trust. It does not create rivalry; if anything, it reduces tension between people."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 505, $official_bank_source${"itemId":"ca591cb9-3536-59f8-9aba-c9e8ad4ce854","questionId":"811812f0-ef3e-50c7-983e-e90f9ebfce7a","sourceKey":"bank:SOC101:S101N4-021","payload":{"prompt":"Visiting his grandfather in Ibadan, a 100L student gives him full attention, nods and does not interrupt while the old man speaks. Which communication skill is the student showing?","options":["Conflict resolution","Active listening","Relationship management","Online etiquette"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Giving full attention and not interrupting is active listening, which is especially expected when dealing with Nigerian elders. Conflict resolution is wrong because there is no disagreement to settle in this situation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 506, $official_bank_source${"itemId":"ea660b22-09ea-536c-8dd5-2def24964994","questionId":"92c79524-d852-5363-900a-d0b458db5f2d","sourceKey":"bank:SOC101:S101N4-022","payload":{"prompt":"Which of the following is NOT one of the recommended steps in conflict resolution?","options":["Offer solutions","Report the person to the authorities","Apologise","Take the other person's perspective"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Conflict resolution involves staying calm, listening, taking the other person's perspective, apologising and offering solutions. Reporting to the authorities is a response recommended for bullying, not a step in resolving an ordinary disagreement."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 507, $official_bank_source${"itemId":"659fc86c-f0a4-54e1-99b2-64b4c99884f0","questionId":"75131ca8-acd6-56ec-9ecb-2e219891d1aa","sourceKey":"bank:SOC101:S101N4-023","payload":{"prompt":"Which of the following lists contains only steps in conflict resolution?","options":["Don't overshare, respect privacy and mind your tone","Use privacy settings and limit screen time","Stand up, seek support and report it","Stay calm, listen and apologise"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Staying calm, listening and apologising are all steps in conflict resolution, along with taking the other's perspective and offering solutions. Standing up, seeking support and reporting are the responses to bullying, so that list belongs to a different situation."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 508, $official_bank_source${"itemId":"cb5cac0a-739b-5010-a334-2307d8492455","questionId":"d7eeb0d5-c7d9-53a3-b5d4-6b3ad31ff3a9","sourceKey":"bank:SOC101:S101N4-024","payload":{"prompt":"Which of the following is NOT one of the ways of building social networks?","options":["Joining groups","Setting digital boundaries","Volunteering","Making friends"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Networks are built by making friends, joining groups and volunteering. Setting digital boundaries, such as privacy settings and screen-time limits, is about managing social media use rather than building a network."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 509, $official_bank_source${"itemId":"b9d2764a-a867-5efc-b158-d76139044457","questionId":"2c2a06b4-9aaa-5e7f-906e-1fe6c2a507bf","sourceKey":"bank:SOC101:S101N4-025","payload":{"prompt":"The National Youth Service Corps (NYSC) is given as an example of which way of building social networks?","options":["Volunteering","Digital citizenship","Making friends","Joining groups"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"NYSC is the example given for volunteering, where serving the community brings a person into contact with many new people. Joining groups is tempting, but its examples are student unions, faith bodies and cultural societies."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 510, $official_bank_source${"itemId":"abea2e01-c1e7-5d4f-b135-b59b857191ac","questionId":"23ccc104-d351-5c7f-9620-4933012716df","sourceKey":"bank:SOC101:S101N4-026","payload":{"prompt":"Not oversharing, respecting other people's privacy and minding your tone online are all part of","options":["Digital boundaries","Conflict resolution","Social awareness","Online etiquette"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Online etiquette is good manners on social media: not oversharing, respecting privacy and watching your tone. Digital boundaries is tempting because it also involves privacy, but it refers to your own privacy settings and screen time, not to how you treat others online."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 511, $official_bank_source${"itemId":"3e9aa5f6-5f3c-5143-8623-054e03f5a495","questionId":"62c881df-e991-5606-a371-9377e7817c36","sourceKey":"bank:SOC101:S101N4-027","payload":{"prompt":"Using privacy settings and controlling screen time are examples of","options":["Digital boundaries","Online etiquette","Digital citizenship","Building networks"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Digital boundaries are the limits you set on your own technology use, such as privacy settings and screen time. Online etiquette is about how you behave towards others online, like not oversharing and minding your tone."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 512, $official_bank_source${"itemId":"b4a8b8cf-939c-5b08-a802-656ecfa54445","questionId":"27a68aae-ecd7-529c-8201-cda05c9b43ed","sourceKey":"bank:SOC101:S101N4-028","payload":{"prompt":"The responsible and ethical use of technology, including refusing to engage in cyberbullying, is known as","options":["Digital citizenship","Online etiquette","Social exclusion","Digital boundaries"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Digital citizenship means using technology responsibly and ethically, which includes not taking part in cyberbullying. Online etiquette is close, but it focuses on manners such as not oversharing and minding your tone rather than the wider duty of ethical use."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 513, $official_bank_source${"itemId":"b8029aee-9dd6-579c-a861-e14b82acb8c6","questionId":"78cbe9bd-3519-5974-b240-c59b413aef28","sourceKey":"bank:SOC101:S101N4-029","payload":{"prompt":"A trader in Balogun market turns off her WhatsApp notifications after 9 pm and limits who can view her status updates. Which social media practice is she applying?","options":["Online etiquette","Active listening","Digital boundaries","Digital citizenship"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Limiting screen time and adjusting privacy settings are the two parts of digital boundaries. Online etiquette is about how she communicates with others, such as tone and not oversharing, not about controlling her own phone use."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 514, $official_bank_source${"itemId":"e7de8948-aadb-5422-af9a-5a221a06c3e8","questionId":"111ff4cd-2b1b-5f45-bcbd-8cb6117789b5","sourceKey":"bank:SOC101:S101N4-031","payload":{"prompt":"Unwanted aggressive behaviour, whether physical, verbal or online, is known as","options":["Power dynamics","Gossip","Social exclusion","Bullying"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Bullying is unwanted aggressive behaviour, and it can be physical, verbal or cyber. Gossip is different because it involves spreading unverified or false information rather than direct aggression."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 515, $official_bank_source${"itemId":"837ba8bb-16ea-51a0-8353-c7746b69609b","questionId":"e234dc00-5cf0-5f3c-b019-932ce170f1e7","sourceKey":"bank:SOC101:S101N4-032","payload":{"prompt":"Bullying can take which of the following forms?","options":["Ethnic, cultural and religious","Personal, social and cultural","Economic, gender and racial","Physical, verbal and cyber"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Bullying may be physical, verbal or carried out online as cyberbullying. Economic, gender and racial are types of inequality, while personal, social and cultural are forms of identity, so those lists belong to other topics."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_soc101', 'add', 516, $official_bank_source${"itemId":"a3447748-21c3-5eb3-80a2-84460daa9cc0","questionId":"b8e15313-27b3-529f-90d0-4f8ccf20e02a","sourceKey":"bank:SOC101:S101N4-033","payload":{"prompt":"Which of the following is the recommended response to bullying?","options":["Use privacy settings and limit screen time","Stand up, seek support and report it","Encourage inclusion and hospitality","Take the bully's perspective and apologise"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"The advice for bullying is to stand up to it, seek support and report it. Taking the other person's perspective and apologising are steps in resolving an ordinary conflict, not the right response to aggressive behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 517, $official_bank_source${"itemId":"af893d16-e2db-5a65-a732-694fd838f027","questionId":"513ca35d-7157-5b57-aa3c-5d6501d4559a","sourceKey":"bank:SOC101:S101N4-034","payload":{"prompt":"Spreading unverified or false information about other people is known as","options":["Bullying","Social exclusion","Gossip","Online etiquette"],"correctOption":2,"section":"Understanding and managing social relationships","explanation":"Gossip is the spreading of information about people that has not been checked or is false. Bullying is tempting, but it is defined as unwanted aggressive behaviour, not the passing on of unverified stories."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 518, $official_bank_source${"itemId":"a8d45005-e3dc-5a7f-bf38-d2bf9d175d9c","questionId":"7d9783cc-a809-5369-bf56-8f3c7963d55c","sourceKey":"bank:SOC101:S101N4-035","payload":{"prompt":"Which approach is recommended for countering social exclusion?","options":["Strict workplace decorum","Limiting screen time","Oversharing personal details","Inclusion and hospitality"],"correctOption":3,"section":"Understanding and managing social relationships","explanation":"Since social exclusion means being left out or marginalised, it is countered by including people and being hospitable to them. Limiting screen time is a digital boundary and does nothing to bring excluded people in."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 519, $official_bank_source${"itemId":"54bb9f5b-3edc-549e-99ff-d182cd6f0f1b","questionId":"78e8c65d-277f-5d99-98ff-7803a66b1622","sourceKey":"bank:SOC101:S101N4-036","payload":{"prompt":"A new 100L student from another state is never invited to group lunches and is always left out when study groups are formed. This challenging situation is best described as","options":["Gossip","Social exclusion","Workplace politics","Digital boundaries"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Being left out or pushed to the margins of a group is social exclusion. Gossip is not the answer because nobody is spreading unverified information; the student is simply being kept out."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 520, $official_bank_source${"itemId":"61e056d0-0f3c-50ab-9c85-109341b0e710","questionId":"22fa7d85-d176-55a5-82b3-5d1860c5fd29","sourceKey":"bank:SOC101:S101N4-037","payload":{"prompt":"A student repeatedly sends threatening and insulting messages to a classmate on WhatsApp. This is an example of","options":["Social exclusion","Bullying","Gossip","Online etiquette"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Repeated threats and insults are unwanted aggressive behaviour, and when sent online they are cyberbullying, one form of bullying. Gossip is wrong because the messages are attacks on the classmate, not unverified stories spread about them."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 521, $official_bank_source${"itemId":"9bac8456-6b31-5f2f-9818-68dddb61a02d","questionId":"6002cc92-f80d-5712-b372-239d6c41b213","sourceKey":"bank:SOC101:S101N4-038","payload":{"prompt":"A staff member at a firm in Ikeja tells several co-workers, without checking any facts, that a colleague is about to be sacked. This behaviour is","options":["Gossip","Active listening","Social exclusion","Bullying"],"correctOption":0,"section":"Understanding and managing social relationships","explanation":"Passing on information that has not been verified is gossip. Bullying does not fit as well because the staff member is not directing aggressive behaviour at the colleague; the problem is spreading an unchecked claim."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 522, $official_bank_source${"itemId":"83928b3f-7833-5afd-9a94-fb606edb0158","questionId":"025e8abc-8c06-56fb-a934-3d0e3199f6e5","sourceKey":"bank:SOC101:S101N4-039","payload":{"prompt":"Effective expression of emotions is classified as one of the","options":["Areas of social media use","Communication skills","Challenging situations","Ways of building networks"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"Effective expression of emotions sits with active listening and conflict resolution as one of the three communication skills. It is not a way of building networks, which are making friends, joining groups and volunteering."}}$official_bank_source$::jsonb),
  ('official_bank_soc101', 'add', 523, $official_bank_source${"itemId":"5eb2c1e8-046f-5902-989d-fbd99e88f84e","questionId":"95aafd31-7c86-5e4e-be7e-ce6f04207aac","sourceKey":"bank:SOC101:S101N4-040","payload":{"prompt":"The relationship between an employee of a bank in Lagos and her branch manager is an example of a","options":["Family relationship","Professional relationship","Friendship","Romantic relationship"],"correctOption":1,"section":"Understanding and managing social relationships","explanation":"People linked by work, such as an employee and her manager, are in a colleague or professional relationship based on teamwork, respect and shared goals. Friendship is not the best fit because the link here comes from the workplace, not from mutual affection and shared interests."}}$official_bank_source$::jsonb);
